window.SOMA={"asanalar":[{"n":1,"bolum":1,"ad":"Dağ (Tadasana)","aile":"Ayakta","seviye":"Başlangıç","yogunluk":[1,2,3],"calisan":["Kuadriseps","Transversus abdominis","Erector spinae"],"dengeleyen":["Gluteus medius ve minimus","Gastroknemius ve soleus","Pelvik taban"],"uzayan":[],"ozet":"Tüm ayakta pozların temel hizalamasını öğretir: ayaktan başın tepesine uzanan dengeli bir dikey hat. Sınıfta duruş farkındalığı ve nefesle toplanma için başlangıç noktasıdır.","asamalar":{"giris":"Ayakları kalça genişliğinde paralel yerleştirin ve ağırlığı topuklarla parmak tabanlarına eşit dağıtın. Nefes alarak omurgayı başın tepesinden yukarı uzatın, nefes vererek omuzları kulaklardan uzaklaştırın.","kalis":"Pelvis nötrde kalır, kuyruk sokumu yere doğru uzanır; kaburgalar öne taşmaz, çene yere paralel durur. Burundan sakin nefeslerle 5–8 nefes kalın.","cikis":"Nefes vererek dizleri hafifçe yumuşatın, ağırlığı bir kez öne arkaya kaydırıp ortalayın ve bir sonraki poza geçin."},"hata":{"ne":"Dizleri geriye kilitleyip pelvisi öne itmek.","neden":"Kuadriseps aşırı kasıldığında diz hiperekstansiyona gider, pelvis öne kayar ve bel çukuru artar.","yonlendirme":"Dizler yumuşak, kuyruk sokumu yere uzanır."},"soylenecekler":["Ayak tabanınızın dört köşesine eşit basın.","Başınızın tepesiyle tavana doğru uzayın.","Nefesiniz kaburgalarınızı yanlara doğru açsın, omuzlarınız aşağıda kalsın."],"eller":{"nereye":"Bir el sakrumun üst kenarına, diğer el sternumun hemen altına, düz avuçla.","nasil":"Sakrumdaki eli hafifçe aşağı, göğüsteki eli yukarı yönlendirerek omurga uzunluğunu hissettirin; itmeyin, yalnızca yön gösterin.","ne_zaman_degil":"Öğrenci izin vermediyse ya da gözleri kapalıyken habersiz yaklaşmanız gerekecekse dokunmayın."},"kolay":"Sırtı duvara yaslayarak topuk, kalça ve kürek kemiklerinin duvarla temasını hissettirin.","zor":"Gözleri kapatarak ya da kolları başın üstüne uzatarak aynı hizayı ve dengeyi koruyun.","dikkat":"Baş dönmesi tarif eden öğrencide gözler açık kalsın ve duvar yakında olsun. Ayak, diz ya da bel ağrısı söz konusuysa öğrencinin doktoruna ya da fizyoterapistine danışmasını önerin.","s":6,"fig":true},{"n":2,"bolum":1,"ad":"Sandalye (Utkatasana)","aile":"Ayakta","seviye":"Başlangıç","yogunluk":[3,5,7],"calisan":["Kuadriseps","Gluteus maximus","Erector spinae","Deltoid"],"dengeleyen":["Transversus abdominis","Tibialis anterior","Addüktörler"],"uzayan":["Gastroknemius ve soleus","Latissimus dorsi"],"ozet":"Kalçadan geriye oturmayı ve bacak gücünü omurga uzunluğuyla birleştirmeyi öğretir. Akışlarda ısınma ve dayanıklılık bölümü için idealdir.","asamalar":{"giris":"Ayaklar birleşik ya da kalça genişliğinde dururken nefes vererek dizleri bükün ve kalçaları sanki arkadaki bir sandalyeye oturuyormuş gibi geriye gönderin. Nefes alarak kolları kulak hizasında yukarı uzatın.","kalis":"Gövde hafifçe öne eğilir ama omurga uzun kalır; kaburgalar içeride, kuyruk sokumu aşağı doğru uzanır. Ağırlık topuklarda, 5 nefes kalın.","cikis":"Nefes alarak ayaklara basıp dizleri uzatın ve Dağ pozuna yükselin, nefes vererek kolları indirin."},"hata":{"ne":"Dizlerin öne kaçması ve topukların kalkması.","neden":"Kalça fleksiyonu ve ayak bileği hareketi sınırlı olduğunda beden kalçadan geriye oturmak yerine dizleri öne iterek dengeyi arar.","yonlendirme":"Geriye oturun, ağırlık topuklarda."},"soylenecekler":["Kalçalarınızı geriye, sandalyeye oturur gibi gönderin.","Ayak parmaklarınızı oynatabilmelisiniz; ağırlık topuklarda.","Kollarınız uzarken omuzlarınız kulaklardan uzak kalsın."],"eller":{"nereye":"İki el kalça kemiklerinin (iliak kristalar) üst kenarına, yanlardan.","nasil":"Kalçaları hafifçe geriye ve aşağı yönlendirerek oturma hissini verin; aşağı bastırmayın, yalnızca yön gösterin.","ne_zaman_degil":"Diz ağrısı tarif ediliyorsa, öğrenci gebeyse ve izin vermediyse ya da izin alınmadıysa dokunmayın."},"kolay":"Elleri kalçalara ya da göğüs önünde birleştirin; daha az bükülün veya sırtı duvara yaslayın.","zor":"Topukları yerden kaldırıp parmak tabanlarında aynı derinliği koruyun ya da avuçlar arasına blok sıkıştırın.","dikkat":"Diz ya da ayak bileği hassasiyetinde bükülme sığ kalsın. Omuz sıkışması varsa kollar omuz genişliğinden açık tutulsun. Ağrı sürüyorsa öğrencinin doktoruna ya da fizyoterapistine danışmasını önerin.","s":7,"fig":true},{"n":3,"bolum":1,"ad":"Savaşçı I (Virabhadrasana I)","aile":"Ayakta","seviye":"Başlangıç","yogunluk":[3,5,7],"calisan":["Kuadriseps","Gluteus maximus","Deltoid"],"dengeleyen":["Transversus abdominis","Gluteus medius ve minimus","Oblikler"],"uzayan":["İliopsoas","Gastroknemius ve soleus"],"ozet":"Kalçaları öne çevirerek ön bacakta güç ve arka bacakta uzama yaratmayı öğretir. Ayakta akışların temel kalça hizalama dersidir.","asamalar":{"giris":"Bir adımı geniş geriye atın, arka ayağı yaklaşık 45 derece dışa çevirin ve iki kalça kemiğini öne yönlendirin. Nefes vererek ön dizi ayak bileğinin üzerine bükün, nefes alarak kolları yukarı uzatın.","kalis":"Pelvis öne bakar, kaburgalar öne taşmaz; arka topuk yere basar ve arka bacak uzun kalır. 5 nefes kalın.","cikis":"Nefes alarak ön bacağı düzleştirin, nefes vererek kolları indirin ve ayakları birleştirip diğer tarafa geçin."},"hata":{"ne":"Arka kalçanın geride kalıp pelvisin yana açılması.","neden":"Arka bacakta kalça fleksörleri ve baldır kısa olduğunda pelvis öne dönemez ve yan tarafa kaçar.","yonlendirme":"Arka kalça öne, iki kalça kemiği aynı yöne."},"soylenecekler":["İki kalça kemiğiniz far gibi öne baksın.","Arka topuğunuzla yeri geriye doğru itin.","Kaburgalarınızı içeri toplayın, kollarınız yukarı uzarken beliniz uzun kalsın."],"eller":{"nereye":"Bir el arka kalçanın yan tarafına (büyük trokanter bölgesi), diğeri ön kalça kemiğine.","nasil":"Arka kalçayı nazikçe öne, ön kalçayı hafifçe geriye yönlendirerek pelvisi ortalayın; dönüşü zorlamayın.","ne_zaman_degil":"Kalça ya da diz ağrısı varsa, öğrenci gebeyse ve dokunuş istemediyse uzak durun."},"kolay":"Duruşu kısaltın ya da ayakları biraz daha yana açın (raylar gibi); elleri kalçalarda tutun.","zor":"Kolları yukarıda birleştirip bakışı başparmaklara kaldırın ya da ön uyluğu yere paralel olana kadar indirin.","dikkat":"Bel bölgesinde hassasiyet varsa kollar omuz genişliğinde kalsın ve geriye eğilme eklenmesin. Ağrı tarif edilirse öğrencinin doktoruna ya da fizyoterapistine danışmasını önerin.","s":8,"fig":true},{"n":4,"bolum":1,"ad":"Savaşçı II (Virabhadrasana II)","aile":"Ayakta","seviye":"Başlangıç","yogunluk":[3,5,7],"calisan":["Kuadriseps","Gluteus medius ve minimus","Deltoid"],"dengeleyen":["Addüktörler","Transversus abdominis","Oblikler"],"uzayan":["Addüktörler"],"ozet":"Kalçayı yana açarken öndeki dizi ayak hizasında tutmayı ve kolları yere paralel uzatmayı öğretir. Ayakta serilerde dayanıklılık ve odak için temel pozdur.","asamalar":{"giris":"Ayakları geniş açın, ön ayağı 90 derece dışa, arka ayağı hafifçe içe çevirin. Nefes alarak kolları omuz hizasında yanlara uzatın, nefes vererek ön dizi ayak bileğinin üzerine bükün.","kalis":"Pelvis ve göğüs yana açık kalır, gövde iki bacağın ortasında dik durur; ön diz ikinci parmak hizasında. Bakış ön elin parmaklarında, 5–8 nefes kalın.","cikis":"Nefes alarak ön bacağı düzleştirin, nefes vererek kolları indirin ve ayakları paralel hale getirerek diğer tarafa geçin."},"hata":{"ne":"Öndeki diz içe, ayak başparmağının ötesine kaçar.","neden":"Gluteus medius ve dış rotatorlar yorulduğunda uyluk içe döner ve diz orta hattın içine çöker.","yonlendirme":"Diz ikinci parmağı takip eder."},"soylenecekler":["Ön dizinizi serçe parmağınıza doğru hafifçe dışa açın.","Gövdeniz öne kaymasın, iki bacağınızın tam ortasında kalsın.","Parmak uçlarınızla iki duvara doğru uzanın, omuzlarınız aşağıda."],"eller":{"nereye":"Bir el ön dizin dış yüzüne, diğer el aynı tarafın dış kalçasına.","nasil":"Dizi hafifçe dışa, ikinci parmak hizasına yönlendirin; kalçayı ise nazikçe aşağı ve geriye gösterin. Hiçbir zaman dizi içe ya da aşağı bastırmayın.","ne_zaman_degil":"Diz ağrısı, kalça protezi ya da öğrencinin izin vermediği durumlarda dokunmayın."},"kolay":"Duruşu kısaltın ve ön diz bükülmesini azaltın; kollar yorulursa elleri kalçalara alın.","zor":"Ön uyluğu yere paralel indirip 10 nefes kalın ya da kolları sabit tutarak dizi nefesle bükülüp uzatın.","dikkat":"Omuz rahatsızlığında kollar daha alçak tutulsun. Diz ya da kalçada ağrı varsa bükülme sığ kalsın ve öğrencinin doktoruna ya da fizyoterapistine danışmasını önerin.","s":9,"fig":true},{"n":5,"bolum":1,"ad":"Ters savaşçı (Viparita Virabhadrasana)","aile":"Ayakta","seviye":"Başlangıç","yogunluk":[3,5,6],"calisan":["Kuadriseps","Oblikler","Gluteus medius ve minimus"],"dengeleyen":["Addüktörler","Transversus abdominis","Quadratus lumborum"],"uzayan":["Latissimus dorsi","Oblikler","Quadratus lumborum"],"ozet":"Savaşçı II'nin bacak tabanını koruyarak gövdenin yan hattını uzatmayı öğretir. Akışlarda nefesi yan kaburgalara yönlendirmek için kullanılır.","asamalar":{"giris":"Savaşçı II'den başlayın. Nefes alarak ön avucu tavana çevirip kolu yukarı ve geriye uzatın, arka eli arka uyluğa hafifçe yerleştirin.","kalis":"Ön diz bükülü ve ayak bileği üzerinde kalır, pelvis yere yakın ve sabittir; yan bel kısalmadan kemer çizer. 3–5 nefes kalın, her nefes alışta üst kaburgaları açın.","cikis":"Nefes vererek gövdeyi ortaya getirip Savaşçı II'ye dönün ya da elleri yere indirip akışa devam edin."},"hata":{"ne":"Geriye uzanırken ön dizi düzleştirip ağırlığı arka ele yüklemek.","neden":"Yan hattı açma isteğiyle beden bacak tabanını terk eder ve dengeyi arka kola devreder.","yonlendirme":"Ön diz bükülü kalsın, arka el sadece dokunur."},"soylenecekler":["Ön dizinizi bükülü tutun, kalçanız aşağıda kalsın.","Yukarıdaki parmaklarınızla önce tavana, sonra geriye uzanın.","Arka eliniz bacağınıza yalnızca dokunsun, yük taşımasın."],"eller":{"nereye":"Bir el ön dizin dış yüzüne, diğer el uzanan kolun tarafındaki yan kaburgalara.","nasil":"Dizi ikinci parmak hizasında tutması için hafifçe dışa yönlendirin, kaburgalara ise yukarı doğru hafif bir uzama yönü verin; geriye çekmeyin.","ne_zaman_degil":"Bel ya da boyun ağrısı tarif ediliyorsa, öğrenci baş dönmesi yaşıyorsa ya da izin yoksa dokunmayın."},"kolay":"Arka eli kalçaya koyun ve geriye değil yalnızca yukarı uzanın.","zor":"Arka kolu bele sararak bağlayın ya da bakışı uzanan ele kaldırıp 5 nefes kalın.","dikkat":"Boyun hassasiyetinde bakış yerde ya da yanda kalsın. Bel bölgesinde sıkışma hissi varsa uzama küçültülsün; ağrı sürerse öğrencinin doktoruna ya da fizyoterapistine danışmasını önerin.","s":10,"fig":false},{"n":6,"bolum":1,"ad":"Üçgen (Trikonasana)","aile":"Ayakta","seviye":"Başlangıç","yogunluk":[2,4,6],"calisan":["Oblikler","Quadratus lumborum","Kuadriseps"],"dengeleyen":["Hamstringler","Transversus abdominis","Gluteus medius ve minimus"],"uzayan":["Hamstringler","Addüktörler"],"ozet":"Bacağı uzun tutarak gövdeyi kalça ekleminden yana uzatmayı öğretir. Derinlik yerine yan hattın iki tarafını eşit uzatmanın en net örneğidir.","asamalar":{"giris":"Ayakları geniş açın, ön ayağı 90 derece dışa çevirin. Nefes alarak kolları yanlara uzatın, nefes vererek gövdeyi ön bacak yönünde uzatın ve ön eli incik, blok ya da yere yerleştirin.","kalis":"Gövdenin iki yan hattı eşit uzunlukta kalır, göğüs yana açıktır; ön diz kilitlenmez. Üst kol tavana uzanır, 5 nefes kalın.","cikis":"Nefes alarak arka topuğa basın ve gövdeyi tek parça halinde yukarı kaldırın, nefes vererek kolları indirip diğer tarafa geçin."},"hata":{"ne":"Yere ulaşmak için yan beli ezmek.","neden":"Hamstringler kısa olduğunda hareket kalça ekleminden değil bel omurlarından yana bükülmeyle telafi edilir.","yonlendirme":"Derin değil, uzun olsun."},"soylenecekler":["Önce ön elinizle ileri uzanın, sonra aşağı inin.","Belinizin alt tarafı da üst tarafı kadar uzun kalsın.","Göğsünüzü tavana doğru açın, ön diziniz hafif yumuşak."],"eller":{"nereye":"Bir el arka kalçanın üstüne, diğer el üst taraftaki kürek kemiğine.","nasil":"Kalçayı hafifçe geriye, kürek kemiğini göğsü açacak yönde nazikçe yönlendirin; gövdeyi aşağı bastırmayın.","ne_zaman_degil":"Boyun ya da bel ağrısı, öğrencinin dengesizlik hissettiği an ya da izin olmadığı durumlarda dokunmayın."},"kolay":"Ön eli yüksek bir bloğa ya da inciğin üst kısmına koyun; bakış yerde kalsın.","zor":"Üst kolu kulağın yanından ileri uzatın ya da ön eli ayağın arkasında yere indirip yan hattı koruyun.","dikkat":"Boyun hassasiyetinde baş yere ya da öne baksın. Hiperhareketli dizlerde ön diz hafif bükülü kalsın. Ağrı varsa öğrencinin doktoruna ya da fizyoterapistine danışmasını önerin.","s":11,"fig":true},{"n":7,"bolum":1,"ad":"Genişletilmiş yan açı (Utthita Parsvakonasana)","aile":"Ayakta","seviye":"Başlangıç","yogunluk":[3,5,7],"calisan":["Kuadriseps","Oblikler","Gluteus medius ve minimus"],"dengeleyen":["Addüktörler","Serratus anterior","Transversus abdominis"],"uzayan":["Latissimus dorsi","Addüktörler"],"ozet":"Savaşçı II bacak tabanında topuktan parmak uçlarına uzanan tek bir çapraz hat kurmayı öğretir. Yan gövde uzaması ve bacak gücünü aynı anda çalıştırır.","asamalar":{"giris":"Savaşçı II'den nefes vererek gövdeyi ön bacağa doğru uzatın ve ön ön kolu uyluğa ya da eli bloğa yerleştirin. Nefes alarak üst kolu kulağın yanından çapraz ileri uzatın.","kalis":"Ön diz ayak bileği üstünde kalır, pelvis yana açık, göğüs tavana döner; arka topuktan üst ele kadar düz bir çizgi oluşur. 5 nefes kalın.","cikis":"Nefes alarak arka ayağa basıp gövdeyi kaldırın ve Savaşçı II'ye dönün, nefes vererek bacakları düzleştirin."},"hata":{"ne":"Ön kolu dize yaslayıp gövdenin öne doğru çökmesi.","neden":"Gövde ağırlığı kol üzerine bırakıldığında serratus anterior ve oblikler devreden çıkar, göğüs yere doğru kapanır.","yonlendirme":"Ön kol dizde dinlenir, göğüs tavana açılır."},"soylenecekler":["Arka topuğunuzdan parmak uçlarınıza kadar tek bir çizgi hissedin.","Ön kolunuz uyluğunuza yük bindirmesin, yalnızca değsin.","Üst omzunuzu geriye çevirip göğsünüzü tavana açın."],"eller":{"nereye":"Bir el üst taraftaki kalçanın yanına, diğer el uzanan kolun dirseğinin hemen altına.","nasil":"Kalçayı hafifçe geriye yönlendirin ve kolu çaprazına doğru uzatarak hattı hissettirin; dönüşü zorlamayın.","ne_zaman_degil":"Omuz instabilitesi tarif ediliyorsa, öğrenci gebeyse ve izin vermediyse ya da diz ağrısı varsa dokunmayın."},"kolay":"Ön kolu uyluğa koyun, üst eli bele alın.","zor":"Ön eli ayağın dış tarafında yere indirin ya da üst kolu bacağın altından sararak bağlayın.","dikkat":"Omuz ağrısında üst kol bele alınsın. Kasık ya da diz hassasiyetinde duruş kısaltılsın; ağrı sürerse öğrencinin doktoruna ya da fizyoterapistine danışmasını önerin.","s":12,"fig":false},{"n":8,"bolum":1,"ad":"Piramit (Parsvottanasana)","aile":"Ayakta","seviye":"Orta","yogunluk":[3,5,7],"calisan":["Kuadriseps","Erector spinae","Gluteus medius ve minimus"],"dengeleyen":["Transversus abdominis","Addüktörler","Tibialis anterior"],"uzayan":["Hamstringler","Gastroknemius ve soleus"],"ozet":"Kare kalçalarla ön bacak üzerine kalçadan katlanmayı ve sırtı uzun tutmayı öğretir. Hamstring uzaması ile pelvis kontrolünü birlikte çalıştırır.","asamalar":{"giris":"Kısa bir duruşla bir ayağı geriye alın, arka ayağı hafifçe dışa çevirin ve iki kalçayı öne yönlendirin. Nefes alarak omurgayı uzatın, nefes vererek kalçadan ön bacağın üzerine eğilin.","kalis":"Pelvis kare kalır, ağırlık iki ayağa dengeli dağılır; omurga önce uzun, sonra rahatça katlanır. Eller blokta ya da yerde, 5 nefes kalın.","cikis":"Nefes alarak sırtı düz tutup elleri kalçalara alın ve gövdeyi kaldırın, nefes vererek ayakları birleştirip diğer tarafa geçin."},"hata":{"ne":"Alnı dize götürmek için sırtı yuvarlamak.","neden":"Hamstringler kısa olduğunda pelvis öne dönemez ve hareket omurganın bükülmesiyle telafi edilir.","yonlendirme":"Göğüs öne uzar, alın sonra gelir."},"soylenecekler":["Göğsünüzü ön ayağınıza doğru uzatın.","Ön kalçanızı hafifçe geriye çekin, kalçalarınız aynı hizada kalsın.","Ön dizinizi kilitlemeyin, hafif yumuşak tutun."],"eller":{"nereye":"İki el kalça kemiklerinin yan tarafına.","nasil":"Ön kalçayı hafifçe geriye, arka kalçayı öne yönlendirerek kare pelvisi hissettirin; gövdeyi aşağı bastırmayın.","ne_zaman_degil":"Hamstring zorlanması tarif ediliyorsa, bel ağrısı varsa ya da öğrenci izin vermediyse dokunmayın."},"kolay":"Elleri ön ayağın iki yanındaki yüksek bloklara koyun ve ön dizi bükülü tutun.","zor":"Elleri sırtta ters namaste ile birleştirip katlanın.","dikkat":"Bel hassasiyetinde yarım eğilmede (sırt yere paralel) kalınsın. Arka bacakta ya da arka uyluğunda ağrı varsa öğrencinin doktoruna ya da fizyoterapistine danışmasını önerin.","s":13,"fig":false},{"n":9,"bolum":1,"ad":"Dönen üçgen (Parivrtta Trikonasana)","aile":"Burgu","seviye":"Orta","yogunluk":[4,6,7],"calisan":["Oblikler","Multifidus","Kuadriseps"],"dengeleyen":["Gluteus medius ve minimus","Transversus abdominis","Addüktörler"],"uzayan":["Hamstringler"],"ozet":"Sabit ve dengeli bir pelvis üzerinde omurgayı uzatıp göğüs kafesinden dönmeyi öğretir. Burgu, denge ve hamstring uzamasını birlikte gerektirir.","asamalar":{"giris":"Kısa bir duruşta kalçaları öne yönlendirin. Nefes alarak omurgayı uzatın, nefes vererek gövdeyi öne uzatıp karşı eli bloğa ya da ön ayağın iç veya dış yanına koyun.","kalis":"Pelvis seviyeli kalır, omurga uzun eksen etrafında döner; üst kol tavana uzanır. 5 nefes kalın, her nefes alışta uzayın, nefes verişte dönün.","cikis":"Nefes vererek üst eli kalçaya alın, nefes alarak gövdeyi tek parça halinde kaldırıp diğer tarafa geçin."},"hata":{"ne":"Burguyu derinleştirmek için kalçaların yana kayması.","neden":"Burgu göğüs kafesinden değil pelvisten yapılmaya çalışıldığında gluteus medius kontrolü kaybolur ve kalça dışa itilir.","yonlendirme":"Önce kalçalar hizada, sonra dönüş."},"soylenecekler":["Kalçalarınızı ortalayın; ön kalçanız geriye, arka kalçanız öne.","Önce başınızın tepesine doğru uzayın, sonra dönün.","Burgu göbek altından değil göğsünüzden başlasın."],"eller":{"nereye":"Bir el dışa kayan kalçanın yan tarafına, diğer el üst taraftaki kürek kemiğine.","nasil":"Kalçayı orta hatta doğru nazikçe yönlendirin, kürek kemiğine yalnızca dönüş yönünü gösterin; burguyu çevirerek derinleştirmeyin.","ne_zaman_degil":"Bel ya da sakroiliak ağrısı, gebelik, disk sorunu bildirilmiş öğrenciler ya da izin olmadığında dokunmayın."},"kolay":"Alt eli yüksek bloğa koyun, üst eli kalçada tutun ve duruşu genişletin.","zor":"Alt eli ön ayağın dış yanında yere koyun ve bakışı üst ele kaldırın.","dikkat":"Gebelikte bu kapalı burgu yerine açık bir varyasyon seçilsin. Bel veya sakroiliak bölgede ağrı varsa öğrencinin doktoruna ya da fizyoterapistine danışmasını önerin.","s":14,"fig":false},{"n":10,"bolum":1,"ad":"Geniş bacaklı öne eğilme (Prasarita Padottanasana)","aile":"Öne eğilme","seviye":"Başlangıç","yogunluk":[2,4,6],"calisan":["Kuadriseps","Erector spinae"],"dengeleyen":["Addüktörler","Gluteus medius ve minimus","Transversus abdominis"],"uzayan":["Hamstringler","Addüktörler","Gastroknemius ve soleus"],"ozet":"Geniş bir taban üzerinde kalçalardan katlanmayı ve başı kalbin altına güvenle indirmeyi öğretir. Hafif bir ters duruş etkisiyle sınıfın sakinleşme aşamasına köprü kurar.","asamalar":{"giris":"Ayakları bir bacak boyu açın, ayak dış kenarlarını paralel tutun. Nefes alarak omurgayı uzatın, nefes vererek kalçalardan öne katlanıp elleri omuz altında yere koyun.","kalis":"Kalçalar ayak bileklerinin üzerinde kalır, ağırlık parmak tabanlarına hafifçe kayar; omurga uzun, boyun rahat. 5–8 nefes kalın.","cikis":"Elleri kalçalara alın, nefes alarak sırtı düz tutarak gövdeyi kaldırın ve ayakları adım adım birleştirin."},"hata":{"ne":"Ağırlığı topuklara verip başı zorla yere indirmeye çalışmak.","neden":"Kalçalar geriye kaydığında hamstringler gerilir ve beden derinliği boyundan ve sırttan arar.","yonlendirme":"Ağırlık parmak tabanlarında, kalçalar ayak bileği üstünde."},"soylenecekler":["Kalçalarınızı ayak bileklerinizin tam üstünde tutun.","Ayak dış kenarlarınıza basın, kemerleriniz yukarıda.","Başınızı bırakın, ensenizi uzatın."],"eller":{"nereye":"İki el kalça kemiklerinin üst kenarına, arkadan.","nasil":"Kalçaları hafifçe öne, ayak bileklerinin üzerine yönlendirin; aşağı itmeyin.","ne_zaman_degil":"Yüksek tansiyon, glokom ya da baş dönmesi tarif eden öğrencilerde ve izin yoksa dokunmayın."},"kolay":"Elleri bloklara koyup sırtı yere paralel tutun; dizleri hafifçe bükün.","zor":"Elleri sırtta kenetleyip kolları başın üzerine doğru uzatın.","dikkat":"Tansiyon, göz içi basıncı ya da baş dönmesi tarif eden öğrencide baş kalbin üstünde kalsın. Bel ağrısında öğrencinin doktoruna ya da fizyoterapistine danışmasını önerin.","s":15,"fig":false},{"n":11,"bolum":1,"ad":"Yüksek hamle","aile":"Ayakta","seviye":"Başlangıç","yogunluk":[3,5,7],"calisan":["Kuadriseps","Gluteus maximus","Deltoid"],"dengeleyen":["Gluteus medius ve minimus","Transversus abdominis","Addüktörler"],"uzayan":["İliopsoas"],"ozet":"Arka topuk havadayken dar bir taban üzerinde güç ve denge kurmayı öğretir. Arka bacağın kalça önünü uzatıp ön bacakta dayanıklılık yaratır.","asamalar":{"giris":"Aşağı bakan köpekten bir ayağı ellerin arasına getirin, arka topuk havada kalsın. Nefes alarak gövdeyi ve kolları yukarı kaldırın.","kalis":"Ön diz ayak bileği üstünde, arka bacak uzun ve aktiftir; pelvis öne bakar, kaburgalar içeride kalır. 5 nefes kalın.","cikis":"Nefes vererek elleri ön ayağın iki yanına indirin ve geri adımla aşağı bakan köpeğe dönün."},"hata":{"ne":"Arka dizi kilitleyip bel çukurunu artırmak.","neden":"Arka kalçanın önündeki iliopsoas kısa olduğunda pelvis öne devrilir ve bel kavisi büyür.","yonlendirme":"Arka topuk geriye, kaburgalar içeri."},"soylenecekler":["Arka topuğunuzla duvara itiyormuş gibi uzanın.","Kaburgalarınızı içeri toplayın, beliniz uzun kalsın.","Ön dizinizi ayak bileğinizin üzerinde tutun."],"eller":{"nereye":"Bir el sakruma, diğer el alt kaburgaların ön tarafına.","nasil":"Sakrumu hafifçe aşağı, kaburgaları içeri yönlendirerek nötr pelvisi hissettirin; yük bindirmeyin.","ne_zaman_degil":"Diz ağrısı, gebelik ileri dönemi ya da izin olmayan durumlarda dokunmayın."},"kolay":"Arka dizi yere indirin ya da elleri ön uyluğa koyun.","zor":"Kolları yukarıda tutarken ön dizi derinleştirin ya da nefesle arka dizi bükülüp uzatın.","dikkat":"Dengesizlik hissedenler duvar yanında çalışsın. Diz ya da kalçada ağrı söz konusuysa öğrencinin doktoruna ya da fizyoterapistine danışmasını önerin.","s":16,"fig":false},{"n":12,"bolum":1,"ad":"Alçak hamle (Anjaneyasana)","aile":"Kalça açma","seviye":"Başlangıç","yogunluk":[2,4,6],"calisan":["Kuadriseps","Gluteus maximus","Deltoid"],"dengeleyen":["Transversus abdominis","Gluteus medius ve minimus"],"uzayan":["İliopsoas","Kuadriseps"],"ozet":"Arka dizi yere koyarak kalça önünü kontrollü biçimde açmayı öğretir. Uzun oturma sonrası kalça fleksörlerine alan açmak için sınıfta sık kullanılır.","asamalar":{"giris":"Bir ayağı ellerin arasına getirin, arka dizi yere indirip ayak üstünü yere bırakın. Nefes alarak gövdeyi kaldırın, kolları yukarı uzatın.","kalis":"Kalçalar hafifçe öne kayar ama pelvis nötrde kalır; kuyruk sokumu aşağı uzanır, kaburgalar içeride. 5–8 nefes kalın.","cikis":"Nefes vererek elleri yere indirin, kalçaları geriye alıp ön bacağı geri çekin."},"hata":{"ne":"Kalçayı öne düşürüp bel çukurunu artırmak.","neden":"Kalça fleksörleri uzamadan derinlik arandığında pelvis öne devrilir ve bel kavisi uzamanın yerini alır.","yonlendirme":"Kuyruk sokumu aşağı, kasık öne."},"soylenecekler":["Arka dizinizin altına battaniye koyun, rahat olsun.","Kuyruk sokumunuzu yere doğru uzatın.","Kalçanızın ön tarafında uzamayı hissedin, belinizde değil."],"eller":{"nereye":"Bir el sakruma, diğer el aynı taraftaki alt kaburgaların önüne.","nasil":"Sakrumu nazikçe aşağı yönlendirin, kaburgaları içeri toplayın; kalçayı öne itmeyin.","ne_zaman_degil":"Diz kapağı ağrısı, gebelikte bel hassasiyeti ya da öğrencinin izin vermediği durumlarda dokunmayın."},"kolay":"Arka diz altına katlanmış battaniye koyun, elleri ön uyluğa ya da bloklara alın.","zor":"Arka ayağı aynı taraftaki elle tutup topuğu kalçaya yaklaştırın.","dikkat":"Diz kapağı hassasiyetinde arka dizin altı kalın biçimde desteklensin. Kalça ya da belde ağrı varsa öğrencinin doktoruna ya da fizyoterapistine danışmasını önerin.","s":17,"fig":false},{"n":13,"bolum":1,"ad":"Tanrıça (Utkata Konasana)","aile":"Ayakta","seviye":"Başlangıç","yogunluk":[3,5,7],"calisan":["Kuadriseps","Gluteus maximus","Gluteus medius ve minimus"],"dengeleyen":["Transversus abdominis","Pelvik taban","Erector spinae"],"uzayan":["Addüktörler"],"ozet":"Geniş ve dışa dönük bir taban üzerinde dik gövdeyle derin çömelmeyi öğretir. Kalça dış rotasyonu ve bacak dayanıklılığı için güçlü bir pozdur.","asamalar":{"giris":"Ayakları geniş açın ve parmakları yaklaşık 45 derece dışa çevirin. Nefes vererek dizleri bükün ve kalçaları dizlerle aynı yüksekliğe doğru indirin; kollar kaktüs şeklinde ya da göğüs önünde.","kalis":"Dizler ayak parmaklarıyla aynı yöne bakar, pelvis nötrde, gövde diktir. 5–8 nefes kalın, nefes verişte pelvik tabanı hafifçe yukarı toplayın.","cikis":"Nefes alarak ayaklara basıp bacakları uzatın, ayakları içe çevirip adımla toplayın."},"hata":{"ne":"Dizlerin içe çökmesi.","neden":"Kalça dış rotatorları ve gluteus medius yeterince aktif olmadığında uyluklar içe döner.","yonlendirme":"Dizler serçe parmaklara doğru açılır."},"soylenecekler":["Dizlerinizi serçe parmaklarınıza doğru açın.","Gövdenizi dik tutun, kuyruk sokumunuz yere baksın.","Ayak tabanlarınızla yeri yanlara doğru itin."],"eller":{"nereye":"İki el dizlerin iç yüzüne, hafifçe.","nasil":"Dizleri ayak parmakları yönüne doğru dışa yönlendirin; zorla açmayın, yalnızca yönü hissettirin.","ne_zaman_degil":"Kasık zorlanması ya da diz ağrısı tarif ediliyorsa ve izin yoksa dokunmayın; iç uyluğa temas her zaman önceden sorulsun."},"kolay":"Daha az bükülün ya da sırtı duvara yaslayın; elleri uyluklara koyun.","zor":"Topukları kaldırıp parmak tabanlarında aynı derinlikte kalın ya da kolları yukarıda tutun.","dikkat":"Diz ve kasık hassasiyetinde bükülme sığ tutulsun. Gebelikte duruş genişliği konfora göre ayarlansın; ağrı varsa öğrencinin doktoruna ya da fizyoterapistine danışmasını önerin.","s":18,"fig":false},{"n":14,"bolum":1,"ad":"Aşağı bakan köpek (Adho Mukha Svanasana)","aile":"Ayakta","seviye":"Başlangıç","yogunluk":[3,5,6],"calisan":["Serratus anterior","Deltoid","Kuadriseps"],"dengeleyen":["Latissimus dorsi","Hamstringler","Transversus abdominis"],"uzayan":["Hamstringler","Gastroknemius ve soleus","Latissimus dorsi"],"ozet":"Ellerden kalçalara ve kalçalardan topuklara iki uzun hat kurmayı öğretir. Akışlarda dinlenme ve geçiş pozu olarak her seviyede kullanılır.","asamalar":{"giris":"Dört ayak pozisyonundan ayak parmaklarını yere bastırın. Nefes vererek kalçaları yukarı ve geriye kaldırıp ters bir V şekli oluşturun.","kalis":"Eller omuz genişliğinde ve parmaklar açık, kalçalar tavana uzanır; omurga uzun, boyun rahat. Topuklar yere doğru, ama zorlamadan. 5–8 nefes kalın.","cikis":"Nefes vererek dizleri yere indirip çocuk pozuna geçin ya da ayaklarla ellerin arasına adım atın."},"hata":{"ne":"Topukları yere indirmek için sırtı yuvarlamak.","neden":"Hamstringler ve baldırlar kısa olduğunda pelvis arkaya devrilir ve bel omurları bükülür.","yonlendirme":"Önce uzun sırt, sonra topuklar."},"soylenecekler":["Dizlerinizi bükmekten çekinmeyin; önce uzun bir sırt.","Ellerinizle yeri itip kalçalarınızı geriye gönderin.","Başınızı kollarınızın arasında serbest bırakın."],"eller":{"nereye":"İki el sakrumun üst kısmına, ya da iki el kalça kemiklerinin arkasına.","nasil":"Kalçaları yukarı ve geriye, kuyruk sokumu yönüne doğru yönlendirin; aşağı bastırmayın.","ne_zaman_degil":"Bilek ya da omuz ağrısı, yüksek tansiyon, son dönem gebelik ve izin yoksa dokunmayın."},"kolay":"Dizleri belirgin biçimde bükün ya da elleri bloklara koyun.","zor":"Bir bacağı yukarı kaldırıp kalçaları kare tutun ya da nefes verişte burnu ellerin önüne getirip geri dönün.","dikkat":"Bilek hassasiyetinde ağırlık parmak tabanlarına dağıtılsın ya da ön kollara geçilsin. Omuz veya bilek ağrısında öğrencinin doktoruna ya da fizyoterapistine danışmasını önerin.","s":19,"fig":true},{"n":15,"bolum":1,"ad":"Ayakta yana eğilme","aile":"Ayakta","seviye":"Başlangıç","yogunluk":[1,3,4],"calisan":["Oblikler","Quadratus lumborum"],"dengeleyen":["Gluteus medius ve minimus","Transversus abdominis"],"uzayan":["Latissimus dorsi","Oblikler","Quadratus lumborum"],"ozet":"Ayakta, saf bir yan düzlemde gövdenin yan hattını uzatmayı öğretir. Isınma ya da ayakta seriler arasında nefesi yan kaburgalara yönlendirmek için kullanılır.","asamalar":{"giris":"Dağ pozunda durun. Nefes alarak kolları yukarı uzatıp avuçları birleştirin, nefes vererek kalçaları hafifçe karşı yana kaydırıp gövdeyi yana eğin.","kalis":"Kalçalar ayakların üzerinde kalır, göğüs ne öne ne arkaya döner; iki ayağa eşit ağırlık verilir. 3–5 nefes kalın, nefesi uzanan taraftaki kaburgalara gönderin.","cikis":"Nefes alarak gövdeyi ortaya getirin, nefes vererek kolları indirip diğer tarafa geçin."},"hata":{"ne":"Yana eğilirken gövdenin öne ya da arkaya dönmesi.","neden":"Yan zincir kısa olduğunda beden hareketi omurga rotasyonu ya da fleksiyonuyla tamamlamaya çalışır.","yonlendirme":"İki cam arasında eğilin."},"soylenecekler":["İki cam arasında duruyormuş gibi yalnızca yana eğilin.","Önce yukarı uzayın, sonra yana.","Üst kaburgalarınızın açıldığını hissedin."],"eller":{"nereye":"Bir el uzanan tarafın kalçasına, diğer el aynı tarafın kaburgalarına.","nasil":"Kalçayı sabit tutması için hafifçe yönlendirin, kaburgalara yukarı uzama yönü verin; yana bastırmayın.","ne_zaman_degil":"Omuz ağrısı, bel ağrısı tarif ediliyorsa ya da izin olmadığında dokunmayın."},"kolay":"Bir eli kalçada tutun, yalnızca bir kol yukarı uzansın.","zor":"Bir ayağı diğerinin arkasına çaprazlayıp yan hattı topuğa kadar uzatın.","dikkat":"Omuz rahatsızlığında kollar daha alçak kalsın. Belde batma hissi varsa eğilme küçültülsün ve öğrencinin doktoruna ya da fizyoterapistine danışmasını önerin.","s":20,"fig":false},{"n":16,"bolum":1,"ad":"Dönen sandalye (Parivrtta Utkatasana)","aile":"Burgu","seviye":"Orta","yogunluk":[4,6,7],"calisan":["Kuadriseps","Oblikler","Gluteus maximus"],"dengeleyen":["Addüktörler","Multifidus","Transversus abdominis"],"uzayan":["Rhomboidler"],"ozet":"Sandalye pozunun bacak gücünü koruyarak göğüs kafesinden burgu yapmayı öğretir. Denge, güç ve dönüşü aynı anda çalıştırır.","asamalar":{"giris":"Sandalye pozunda elleri göğüs önünde birleştirin. Nefes alarak omurgayı uzatın, nefes vererek dönüp karşı dirseği dış uyluğa yerleştirin.","kalis":"Dizler yan yana kalır, kalçalar aynı yükseklikte ve geride; omurga uzun eksen etrafında döner. Avuçlar sternum önünde, 5 nefes kalın.","cikis":"Nefes alarak ortaya dönün, nefes vererek elleri çözün ve bacakları uzatarak ayağa kalkın."},"hata":{"ne":"Burgu sırasında bir dizin öne kayması ve kalçaların hizadan çıkması.","neden":"Dönüş göğüs kafesinden değil pelvisten başlatıldığında addüktör kontrolü kaybolur ve pelvis de döner.","yonlendirme":"Dizler yan yana, burgu göğüsten."},"soylenecekler":["Dizlerinizi hizada tutun, biri öne kaçmasın.","Önce başınızın tepesine uzayın, sonra nefes verirken dönün.","Avuçlarınızı birbirine bastırıp göğsünüzü başparmaklarınıza doğru açın."],"eller":{"nereye":"Bir el dizlerin önüne (hizayı göstermek için), diğer el üst taraftaki kürek kemiğine.","nasil":"Dizleri hafifçe aynı hizaya, kürek kemiğini dönüş yönüne doğru yönlendirin; burguyu çevirerek zorlamayın.","ne_zaman_degil":"Gebelik, bel ağrısı, disk sorunu bildirilmesi ya da izin olmadığında dokunmayın."},"kolay":"Bir eli kalçaya, diğerini uyluğa koyup dönüşü kısa tutun.","zor":"Kolları açarak alt eli ayağın dış yanında yere, üst kolu tavana uzatın.","dikkat":"Gebelikte bu kapalı burgu yerine açık bir burgu seçilsin. Bel ya da diz ağrısında öğrencinin doktoruna ya da fizyoterapistine danışmasını önerin.","s":21,"fig":false},{"n":17,"bolum":1,"ad":"Alçakgönüllü savaşçı","aile":"Ayakta","seviye":"Orta","yogunluk":[4,6,7],"calisan":["Kuadriseps","Gluteus maximus","Orta ve alt trapezius"],"dengeleyen":["Gluteus medius ve minimus","Transversus abdominis","Rhomboidler"],"uzayan":["Büyük ve küçük pektoral","İliopsoas"],"ozet":"Savaşçı I tabanından ön dizin içine doğru eğilmeyi ve göğsün önünü açmayı öğretir. Bacak gücü, omuz açılımı ve teslimiyeti tek pozda birleştirir.","asamalar":{"giris":"Savaşçı I'den elleri sırtta kenetleyin ve nefes alarak göğsü açın. Nefes vererek gövdeyi ön dizin iç tarafına doğru indirin, kollar tavana uzansın.","kalis":"Ön diz ayak bileği üzerinde sabit kalır, arka bacak uzun; ön omuz dizin içine doğru iner, boyun rahattır. 5 nefes kalın.","cikis":"Nefes alarak bacaklara basıp gövdeyi kaldırın, nefes vererek elleri çözün ve diğer tarafa geçin."},"hata":{"ne":"Gövdeyi indirirken ön dizin içe çökmesi.","neden":"Gövde ağırlığı ön bacağın içine bindiğinde gluteus medius yetersiz kalır ve uyluk içe döner.","yonlendirme":"Omuz dizin içine iner, diz sabit."},"soylenecekler":["Ön dizinizi ikinci parmağınızın üzerinde sabit tutun.","Omzunuzu dizinizin iç tarafına doğru bırakın.","Kenetli ellerinizi başınızın üstüne doğru uzatın, boynunuz rahat."],"eller":{"nereye":"Bir el ön dizin dış yanına, diğer el kenetli ellerin bileklerine.","nasil":"Dizi ikinci parmak hizasında tutması için hafifçe yönlendirin; kollara çok hafif bir yukarı uzama yönü verin, asla çekmeyin.","ne_zaman_degil":"Omuz instabilitesi, yüksek tansiyon, baş dönmesi ya da izin olmadığında dokunmayın."},"kolay":"Elleri kenetlemek yerine bir kemer tutun ya da elleri öne, yere koyun.","zor":"Kenetli kolları daha da uzatıp 8 nefes kalın.","dikkat":"Baş aşağı pozisyon nedeniyle tansiyon ya da baş dönmesi tarif eden öğrencide gövde yüksekte kalsın. Omuz ağrısında öğrencinin doktoruna ya da fizyoterapistine danışmasını önerin.","s":22,"fig":false},{"n":18,"bolum":1,"ad":"Güneşe selam A (Surya Namaskar A)","aile":"Ayakta","seviye":"Başlangıç","yogunluk":[2,4,6],"calisan":["Serratus anterior","Triceps brachii","Kuadriseps","Erector spinae"],"dengeleyen":["Transversus abdominis","Rotator manşet","Büyük ve küçük pektoral"],"uzayan":["Hamstringler","Gastroknemius ve soleus"],"ozet":"Her hareketi tek bir nefese bağlayarak bedeni ısıtan klasik akışı öğretir. Sınıfın açılışında ritim, nefes ve temel pozların sıralamasını oturtur.","asamalar":{"giris":"Dağ pozunda nefes alarak kolları yukarı kaldırın (Urdhva Hastasana), nefes vererek öne katlanın (Uttanasana), nefes alarak yarım kalkışla sırtı uzatın (Ardha Uttanasana), nefes vererek geriye adım atıp Chaturanga'ya inin.","kalis":"Nefes alarak yukarı bakan köpeğe geçin, nefes vererek aşağı bakan köpekte 5 nefes kalın. Seri boyunca omuzlar kulaklardan uzak, karın merkezi aktif, nefes ve hareket birlikte.","cikis":"Nefes alarak ellerin arasına adım atıp yarım kalkış yapın, nefes vererek öne katlanın, nefes alarak kolları yukarı kaldırarak yükselin ve nefes vererek Dağ pozunda elleri indirin."},"hata":{"ne":"Chaturanga'da omuzların dirsek hizasının altına düşmesi.","neden":"Triceps ve serratus anterior yorulduğunda gövde ağırlığı omuzların önüne yüklenir ve kol başı öne kayar.","yonlendirme":"Omuzlar dirsek hizasında, göğüs öne."},"soylenecekler":["Her hareket bir nefes; nefesinizi tutmayın.","Chaturanga'da dirsekleriniz kaburgalarınıza yakın, omuzlarınız dirsek hizasında.","Gerekirse dizlerinizi yere indirin; ritim derinlikten önemlidir."],"eller":{"nereye":"Aşağı bakan köpekte iki el sakrumun üst kısmına; Chaturanga'da dokunmadan yalnızca sözlü yönlendirme.","nasil":"Köpekte kalçaları yukarı ve geriye hafifçe yönlendirin; geçişlerde akışı bölmemek için dokunuşları kısa tutun.","ne_zaman_degil":"Geçiş anlarında, bilek ya da omuz ağrısında, gebelikte ve izin yoksa dokunmayın."},"kolay":"Chaturanga yerine dizler yerde göğüs çenede inişi seçin ve yukarı bakan köpek yerine kobra yapın.","zor":"Adımlar yerine atlayarak geçin ya da her pozda 3 nefes kalarak yavaş bir seri yapın.","dikkat":"Bilek, omuz ya da bel hassasiyetinde Chaturanga ve yukarı bakan köpek değiştirilsin. Gebelikte karın üzerine yatılan geçişler çıkarılsın; ağrı varsa öğrencinin doktoruna ya da fizyoterapistine danışmasını önerin.","s":23,"fig":false},{"n":19,"bolum":1,"ad":"Güneşe selam B (Surya Namaskar B)","aile":"Ayakta","seviye":"Orta","yogunluk":[3,5,7],"calisan":["Kuadriseps","Gluteus maximus","Triceps brachii","Serratus anterior"],"dengeleyen":["Transversus abdominis","Rotator manşet","Gluteus medius ve minimus"],"uzayan":["Hamstringler","İliopsoas"],"ozet":"Güneşe selam A'ya Sandalye ve Savaşçı I ekleyerek ısıyı ve dayanıklılığı artıran akışı öğretir. Bacak gücü ile nefes ritmini uzun bir seri boyunca korumayı çalıştırır.","asamalar":{"giris":"Dağ pozundan nefes alarak dizleri bükün ve kolları kaldırın (Utkatasana), nefes vererek öne katlanın, nefes alarak yarım kalkış yapın, nefes vererek Chaturanga'ya inin, nefes alarak yukarı bakan köpeğe, nefes vererek aşağı bakan köpeğe geçin.","kalis":"Nefes alarak sağ ayağı öne alıp Savaşçı I'e kalkın, nefes vererek vinyasa ile aşağı bakan köpeğe dönün; aynısını solda tekrarlayın ve aşağı bakan köpekte 5 nefes kalın. Kalçalar Savaşçı I'de öne bakar, nefes ve hareket birliktedir.","cikis":"Nefes alarak ellerin arasına adım atıp yarım kalkış yapın, nefes vererek öne katlanın, nefes alarak Sandalye'ye inip kalkın ve nefes vererek Dağ pozunda kolları indirin."},"hata":{"ne":"Nefesin hareketten kopması ve tutulması.","neden":"Seri uzadıkça bacak ve kol kasları yorulur, diyafram yerine boyun ve omuzlarla nefes alınmaya başlanır.","yonlendirme":"Her hareket bir nefes."},"soylenecekler":["Nefesiniz hızlanırsa bir köpek pozunda durup ritmi yeniden bulun.","Savaşçı I'de iki kalça kemiğiniz öne baksın.","Sandalye'de geriye oturun, ağırlık topuklarda."],"eller":{"nereye":"Savaşçı I'de bir el arka kalçanın yanına, aşağı bakan köpekte iki el sakruma.","nasil":"Savaşçı I'de arka kalçayı hafifçe öne yönlendirin, köpekte kalçaları yukarı ve geriye gösterin; geçişlerde dokunmayın.","ne_zaman_degil":"Geçişler sırasında, yorgunluk belirtileri belirginse, gebelikte ve izin yoksa dokunmayın."},"kolay":"Chaturanga'yı dizler yerde yapın, Savaşçı I yerine alçak hamle seçin ve seri sayısını azaltın.","zor":"Savaşçı I'de 3 nefes kalın ya da vinyasaları atlayarak bağlayın.","dikkat":"Kalp-damar sorunları ya da baş dönmesi tarif eden öğrenci tempoyu düşürsün. Bilek, omuz veya dizde ağrı varsa öğrencinin doktoruna ya da fizyoterapistine danışmasını önerin.","s":24,"fig":false},{"n":20,"bolum":1,"ad":"Ayakta öne eğilme (Uttanasana)","aile":"Öne eğilme","seviye":"Başlangıç","yogunluk":[2,4,6],"calisan":["Kuadriseps","Erector spinae"],"dengeleyen":["Hamstringler","Gastroknemius ve soleus","Tibialis anterior"],"uzayan":["Hamstringler","Gastroknemius ve soleus","Erector spinae"],"ozet":"Kalça ekleminden öne katlanmayı ve omurgayı yerçekimiyle bırakmayı öğretir. Akışlarda sakinleştirici bir geçiş ve hamstringleri tanıma pozudur.","asamalar":{"giris":"Dağ pozunda elleri kalçalara alın. Nefes alarak omurgayı uzatın, nefes vererek dizleri yumuşatıp kalçalardan öne katlanın.","kalis":"Kalçalar ayak bileklerinin üzerinde, ağırlık ayağın ortasında kalır; gövde uyluklara doğru bırakılır, boyun serbesttir. 5–8 nefes kalın.","cikis":"Dizleri bükün, elleri kalçalara alın ve nefes alarak sırtı uzun tutarak yukarı kalkın."},"hata":{"ne":"Dizleri kilitleyip bel bölgesine asılı kalmak.","neden":"Hamstringler kısa olduğunda pelvis öne dönmez ve gövde ağırlığı bel omurlarına yüklenir.","yonlendirme":"Dizler yumuşak, kalçalardan eğilin."},"soylenecekler":["Dizlerinizi bükün, karnınız uyluklarınıza yaklaşsın.","Başınızı bırakın, hafifçe evet hayır sallayın.","Kalçalarınızı ayak bileklerinizin üzerinde tutun."],"eller":{"nereye":"İki el sakrumun üst kısmına ya da iki el kalçaların arkasına.","nasil":"Kalçaları ayak bileklerinin üzerine doğru, hafifçe öne yönlendirin; sırttan aşağı bastırmayın.","ne_zaman_degil":"Bel ağrısı, yüksek tansiyon ya da baş dönmesi tarif ediliyorsa ve izin yoksa dokunmayın."},"kolay":"Dizleri belirgin biçimde bükün, elleri bloklara koyun ya da karşı dirsekleri tutun.","zor":"Ayak başparmaklarını işaret ve orta parmakla tutun ya da avuçları ayak tabanlarının altına yerleştirin.","dikkat":"Bel hassasiyetinde dizler bükülü kalsın ve kalkış yavaş yapılsın. Tansiyon ya da baş dönmesi varsa baş yüksekte kalsın; ağrı sürerse öğrencinin doktoruna ya da fizyoterapistine danışmasını önerin.","s":25,"fig":true},{"n":21,"bolum":2,"ad":"Ağaç (Vrksasana)","aile":"Denge","seviye":"Başlangıç","yogunluk":[2,3,5],"calisan":["Gluteus medius ve minimus","Tibialis anterior","Gastroknemius ve soleus"],"dengeleyen":["Addüktörler","Transversus abdominis","Pelvik taban"],"uzayan":["Addüktörler"],"ozet":"Tek ayak üzerinde dik ve sakin durmayı, pelvisi seviyeli tutmayı öğretir. Sınıfta odak ve denge çalışmasına güvenli bir giriştir.","asamalar":{"giris":"Dağ pozunda ağırlığı bir ayağa verin. Nefes alarak diğer ayağın tabanını iç bileğe, iç baldıra ya da iç uyluğa yerleştirin; dizi yana açın.","kalis":"Destek bacağın kalçası dışa kaymaz, pelvis seviyelidir; ayak tabanı ve bacak birbirine eşit güçle bastırır. Eller göğüs önünde ya da yukarıda, 5–8 nefes kalın.","cikis":"Nefes vererek elleri indirin, kaldırılan ayağı yavaşça yere bırakın ve diğer tarafa geçin."},"hata":{"ne":"Ayağı dizin yanına bastırmak.","neden":"Diz eklemi yana doğru hareket için yapılmamıştır; tabanın yan baskısı eklemin iç ve dış bağlarına yük bindirir.","yonlendirme":"Üstünde ya da altında, asla dizin üzerinde değil."},"soylenecekler":["Ayağınızı ya baldırınıza ya uyluğunuza yerleştirin, dizinize değil.","Ayağınız ve bacağınız birbirine eşit güçle bastırsın.","Bakışınızı önünüzdeki sabit bir noktaya verin."],"eller":{"nereye":"Bir el destek tarafındaki kalçanın dış yanına, diğer el açılan dizin dış yüzüne.","nasil":"Kalçayı orta hatta doğru hafifçe toplayın; dizin açılmasını yalnızca yönlendirin, aşağı bastırmayın.","ne_zaman_degil":"Öğrenci düşme korkusu yaşıyorsa ya da izin vermediyse dokunmayın; denge pozunda habersiz temas düşmeye yol açabilir."},"kolay":"Ayağı bileğe koyup parmakları yerde tutun (kickstand) ya da bir eli duvara yaslayın.","zor":"Kolları yukarı uzatıp gözleri kapatın ya da yarım lotus ağaç deneyin (diz rahatsa).","dikkat":"Ayak bileği ya da diz sorunu olanlar ayağı alçakta tutsun. Baş dönmesi tarif eden öğrenci duvar yanında çalışsın; ağrıda öğrencinin doktoruna ya da fizyoterapistine danışmasını önerin.","s":27,"fig":true},{"n":22,"bolum":2,"ad":"Savaşçı III (Virabhadrasana III)","aile":"Denge","seviye":"Orta","yogunluk":[5,6,8],"calisan":["Gluteus maximus","Hamstringler","Erector spinae","Gluteus medius ve minimus"],"dengeleyen":["Transversus abdominis","Gastroknemius ve soleus","Oblikler"],"uzayan":["Hamstringler"],"ozet":"Tek bacak üzerinde gövdeyle arka bacağı yere paralel tek bir çizgide tutmayı öğretir. Arka zincir gücü ve kalça kontrolü için güçlü bir denge pozudur.","asamalar":{"giris":"Yüksek hamleden ağırlığı ön ayağa aktarın. Nefes vererek gövdeyi öne uzatın ve arka bacağı kaldırarak gövdeyle aynı çizgiye getirin.","kalis":"Pelvis yere paralel ve kare kalır, kaldırılan bacağın parmakları yere bakar; omurga uzun, boyun nötr. 5 nefes kalın.","cikis":"Nefes vererek kaldırılan bacağı bükerek yere indirin, nefes alarak gövdeyi yükseltip Dağ pozuna dönün."},"hata":{"ne":"Kaldırılan bacağın kalçasının tavana açılması.","neden":"Bacağı yükseltme isteğiyle kalça dışa döner ve gluteus medius pelvisi seviyeli tutmayı bırakır.","yonlendirme":"Kalça kemikleri yere bakar, ayak parmakları da."},"soylenecekler":["Arka ayak parmaklarınızı yere doğru çevirin.","Başınızın tepesinden arka topuğunuza tek bir çizgi uzatın.","Destek dizinizi kilitlemeyin, hafifçe yumuşak tutun."],"eller":{"nereye":"Bir el kaldırılan bacağın kalçasının üstüne, diğer el destek tarafının kalçasına.","nasil":"Kaldırılan kalçayı hafifçe yere doğru, pelvisi seviyeli olacak biçimde yönlendirin; bacağı yukarı kaldırmayın.","ne_zaman_degil":"Denge kaybı yaşanıyorsa, düşme riski varsa, hamstring zorlanması tarif ediliyorsa ya da izin yoksa dokunmayın."},"kolay":"Elleri bloklara ya da duvara koyun, kaldırılan bacağı daha alçakta tutun.","zor":"Kolları kulakların yanından ileri uzatın ya da destek bacağı nefesle bükülüp uzatın.","dikkat":"Bel ya da diz hassasiyetinde eller destekte kalsın. Tansiyon ya da baş dönmesi tarif eden öğrenci süreyi kısa tutsun; ağrıda öğrencinin doktoruna ya da fizyoterapistine danışmasını önerin.","s":28,"fig":true},{"n":23,"bolum":2,"ad":"Yarım ay (Ardha Chandrasana)","aile":"Denge","seviye":"Orta","yogunluk":[4,6,7],"calisan":["Gluteus medius ve minimus","Kuadriseps","Oblikler"],"dengeleyen":["Tibialis anterior","Transversus abdominis","Serratus anterior"],"uzayan":["Addüktörler","Hamstringler"],"ozet":"Tek bacak üzerinde pelvis ve göğsü yana açarak dengede durmayı öğretir. Kalça dış kaslarının gücünü ve açık bir göğüs hattını birlikte çalıştırır.","asamalar":{"giris":"Üçgen pozundan ön dizi bükün, ön eli ayağın yaklaşık bir karış önüne bloğa koyun. Nefes alarak arka bacağı kalça yüksekliğine kaldırıp destek bacağı uzatın.","kalis":"Kalçalar üst üste dizilir, göğüs yana açıktır; kaldırılan bacak aktif ve ayak bilek bükülüdür. Üst kol tavana uzanır, 5 nefes kalın.","cikis":"Nefes vererek destek dizini bükün ve kaldırılan bacağı kontrollü biçimde geri indirip Üçgen ya da Savaşçı II'ye dönün."},"hata":{"ne":"Gövdenin yere doğru çökmesi ve göğsün kapanması.","neden":"Gluteus medius ve oblikler yeterince çalışmadığında beden ağırlığı alt ele yüklenir ve gövde yere döner.","yonlendirme":"Arka duvara yaslanıyormuş gibi açın."},"soylenecekler":["Sırtınızla arkadaki bir duvara yaslanıyormuş gibi açılın.","Alt eliniz bloğa hafifçe değsin, ağırlık destek bacağınızda.","Kaldırdığınız topukla geriye itin."],"eller":{"nereye":"Bir el üst kalçanın yanına, diğer el sırtın üst kısmına (kürek kemikleri arası).","nasil":"Üst kalçayı hafifçe geriye, göğsü açacak yönde yönlendirin; öğrenci dengesini sizin üzerinize yaslamasın.","ne_zaman_degil":"Denge kaybında, ayak bileği hassasiyetinde ve izin olmadığında dokunmayın."},"kolay":"Sırtı duvara yaslayarak çalışın ve alt eli yüksek bloğa koyun.","zor":"Kaldırılan bacağın ayağını üst elle tutarak şeker kamışı (Ardha Chandra Chapasana) varyasyonuna geçin.","dikkat":"Boyun hassasiyetinde bakış yere ya da öne yönelsin. Ayak bileği veya kalçada ağrı varsa öğrencinin doktoruna ya da fizyoterapistine danışmasını önerin.","s":29,"fig":true},{"n":24,"bolum":2,"ad":"Kartal (Garudasana)","aile":"Denge","seviye":"Orta","yogunluk":[3,5,6],"calisan":["Kuadriseps","Addüktörler","Gluteus medius ve minimus"],"dengeleyen":["Tibialis anterior","Transversus abdominis","Gastroknemius ve soleus"],"uzayan":["Rhomboidler","Orta ve alt trapezius","Piriformis"],"ozet":"Kol ve bacakları sararak orta hatta toparlanmayı ve dar bir tabanda dengeyi öğretir. Omuz arkasını açarken odaklanmayı da çalıştırır.","asamalar":{"giris":"Dizleri hafifçe bükün. Nefes alarak bir bacağı diğerinin üzerinden çaprazlayın, kolları da karşı taraftan çaprazlayıp dirsekleri birbirine sarın.","kalis":"Kalçalar geriye oturur, gövde dik ve kalçalar düzdür; dirsekler omuz yüksekliğinde ve önde. 5 nefes kalın, nefesi sırtın üst kısmına yönlendirin.","cikis":"Nefes vererek kolları ve bacakları çözün, Dağ pozunda bir nefes durup diğer tarafa geçin."},"hata":{"ne":"Üst ayağı alt baldıra zorla kancalamak.","neden":"Kalça dış rotatorları kısa olduğunda kancalama zorlandığında rotasyon diz eklemine aktarılır.","yonlendirme":"Kanca şart değil, uyluklar sıkı."},"soylenecekler":["Ayak parmaklarınızı yere ya da bloğa koymanız tamamen geçerli.","Uyluklarınızı birbirine sıkın, kalçalarınız geriye otursun.","Dirseklerinizi kaldırıp ellerinizi yüzünüzden uzaklaştırın."],"eller":{"nereye":"Bir el destek tarafındaki kalçanın dış yanına, diğer el kürek kemiklerinin arasına.","nasil":"Kalçayı orta hatta toparlayacak şekilde hafifçe yönlendirin, sırta yalnızca genişleme yönü verin.","ne_zaman_degil":"Diz ya da omuz ağrısı, düşme korkusu ya da izin olmadığında dokunmayın."},"kolay":"Üst ayağın parmaklarını yere koyun (kickstand) ve kolları sarmak yerine karşı omuzları tutun.","zor":"Sarılı haldeyken gövdeyi öne katlayıp dirsekleri dize yaklaştırın.","dikkat":"Diz hassasiyetinde ayak kancası kullanılmasın. Omuz ağrısında kollar yalnızca karşı omuzları tutsun; ağrı sürerse öğrencinin doktoruna ya da fizyoterapistine danışmasını önerin.","s":30,"fig":false},{"n":25,"bolum":2,"ad":"Dansçı (Natarajasana)","aile":"Denge","seviye":"Orta","yogunluk":[5,7,8],"calisan":["Gluteus maximus","Hamstringler","Erector spinae","Gluteus medius ve minimus"],"dengeleyen":["Tibialis anterior","Transversus abdominis","Gastroknemius ve soleus"],"uzayan":["Kuadriseps","İliopsoas","Büyük ve küçük pektoral"],"ozet":"Tek bacak üzerinde geriye eğilmeyi ve ayağı elle iterek göğüs önünü açmayı öğretir. Denge, arka zincir gücü ve ön hat uzamasını bir araya getirir.","asamalar":{"giris":"Dağ pozunda bir dizi bükün ve aynı taraftaki elle ayak bileğinin iç tarafını tutun. Nefes alarak diğer kolu öne uzatın, nefes vererek ayağı ele doğru iterken gövdeyi hafifçe öne eğin.","kalis":"Kaldırılan diz kalça genişliğinde kalır, pelvis yere yakın biçimde seviyeli; göğüs açılır, bel ezilmez. 5 nefes kalın.","cikis":"Nefes alarak gövdeyi dikleştirin, nefes vererek ayağı bırakın ve dizi yavaşça yere indirin."},"hata":{"ne":"Kaldırılan dizin yana açılması.","neden":"Ayağı yükseltme isteğiyle kalça dış rotasyona geçer ve pelvis yana döner.","yonlendirme":"Diz kalça hizasında, ayak ele doğru iter."},"soylenecekler":["Ayağınızı elinize doğru itin, eliniz ayağı çekmesin.","Kaldırdığınız diziniz kalçanızın hizasında kalsın.","Göğsünüzü öne uzanan elinize doğru açın."],"eller":{"nereye":"Bir el kaldırılan bacağın dizinin dış yanına, diğer el destek tarafındaki kalçaya.","nasil":"Dizi orta hatta doğru hafifçe yönlendirin; bacağı yukarı kaldırmayın ya da geriye çekmeyin.","ne_zaman_degil":"Bel ağrısı, düşme korkusu, omuz instabilitesi ya da izin olmadığında dokunmayın."},"kolay":"Ayağı tutmak için kemer kullanın ve öndeki eli duvara yaslayın.","zor":"Ayağı iki elle baş üzerinden tutun (tam Natarajasana).","dikkat":"Bel hassasiyetinde geriye eğilme küçük tutulsun. Omuz ya da diz ağrısında kemer kullanılsın ve öğrencinin doktoruna ya da fizyoterapistine danışmasını önerin.","s":31,"fig":false},{"n":26,"bolum":2,"ad":"Ayakta el ayak başparmağına (Utthita Hasta Padangusthasana)","aile":"Denge","seviye":"Orta","yogunluk":[4,6,8],"calisan":["İliopsoas","Kuadriseps","Gluteus medius ve minimus"],"dengeleyen":["Tibialis anterior","Transversus abdominis","Erector spinae"],"uzayan":["Hamstringler","Gastroknemius ve soleus"],"ozet":"Dik bir omurgayla tek bacağı öne kaldırıp tutmayı öğretir. Kalça fleksörü gücü ile hamstring uzamasını dengede birleştirir.","asamalar":{"giris":"Dağ pozunda ağırlığı bir ayağa verin. Nefes alarak diğer dizi göğse çekin ve aynı taraftaki el parmaklarıyla ayak başparmağını tutun, nefes vererek bacağı öne uzatın.","kalis":"Destek bacak uzun, pelvis seviyelidir; omurga dik kalır, omuzlar kalçaların üzerindedir. Bacak gerektiği kadar bükülü, 5 nefes kalın.","cikis":"Nefes vererek dizi bükün, ayağı bırakın ve bacağı yavaşça yere indirip diğer tarafa geçin."},"hata":{"ne":"Bacağı kaldırmak için sırtı yuvarlayıp destek bacağı bükmek.","neden":"Hamstringler kısa olduğunda pelvis arkaya devrilir ve beden yüksekliği omurgayı bükerek arar.","yonlendirme":"Önce uzun omurga, sonra bacak."},"soylenecekler":["Kaldırdığınız dizinizi bükmekten çekinmeyin.","Göğsünüzü kaldırın, omuzlarınız kalçalarınızın üzerinde.","Destek kalçanızı orta hatta toplayın."],"eller":{"nereye":"Bir el destek tarafının kalçasına, diğer el sırtın orta kısmına.","nasil":"Kalçayı orta hatta toparlayacak yönde, sırtı ise dikleşecek yönde hafifçe yönlendirin; bacağı yukarı kaldırmayın.","ne_zaman_degil":"Hamstring zorlanması, bel ağrısı, düşme riski ya da izin olmadığında dokunmayın."},"kolay":"Ayağa kemer takın ya da dizi bükülü tutup eli dizin üzerine koyun; destek için duvar kullanın.","zor":"Uzanan bacağı yana açın, bakışı karşı omza çevirin ve 5 nefes daha kalın.","dikkat":"Bel hassasiyetinde diz bükülü kalsın. Arka uyluğunda zorlanma geçmişi olan öğrenciler kemer kullansın; ağrıda öğrencinin doktoruna ya da fizyoterapistine danışmasını önerin.","s":32,"fig":false},{"n":27,"bolum":2,"ad":"Ayakta split (Urdhva Prasarita Eka Padasana)","aile":"Denge","seviye":"Orta","yogunluk":[5,7,8],"calisan":["Gluteus maximus","Hamstringler","Kuadriseps"],"dengeleyen":["Gluteus medius ve minimus","Tibialis anterior","Transversus abdominis"],"uzayan":["Hamstringler","İliopsoas","Gastroknemius ve soleus"],"ozet":"Ayakta öne eğilmede bir bacağı yukarı uzatarak bacakların arasında derin bir uzama yaratmayı öğretir. Denge, esneklik ve kalça kontrolünü birlikte gerektirir.","asamalar":{"giris":"Ayakta öne eğilmeden ağırlığı bir ayağa verin ve elleri yere ya da bloklara koyun. Nefes alarak diğer bacağı yukarı kaldırın.","kalis":"Kalçalar yere doğru kare kalır, kaldırılan bacağın dizi yere bakar; gövde destek bacağa yaklaşır. 5 nefes kalın.","cikis":"Nefes vererek kaldırılan bacağı kontrollü biçimde indirin, iki ayakla Ayakta öne eğilmede bir nefes durun."},"hata":{"ne":"Bacağı yükseltmek için kalçanın tavana açılması.","neden":"Yükseklik arandığında kalça dış rotasyona geçer ve pelvis kareliğini kaybeder.","yonlendirme":"Yükseklik değil, kare kalça."},"soylenecekler":["Kaldırdığınız bacağın dizi ve parmakları yere baksın.","Yükseklik değil, iki kalça aynı hizada.","Destek dizinizi hafif yumuşatmakta özgürsünüz."],"eller":{"nereye":"Bir el kaldırılan bacağın kalçasına, diğer el destek tarafının kalçasına.","nasil":"Kaldırılan kalçayı hafifçe aşağı yönlendirerek pelvisi kare tutun; bacağı yukarı itmeyin.","ne_zaman_degil":"Hamstring zorlanması, yüksek tansiyon, baş dönmesi ya da izin olmadığında dokunmayın."},"kolay":"Elleri yüksek bloklara koyun ve kaldırılan bacağı daha alçakta tutun; destek dizi bükülü.","zor":"Destek bileğini karşı elle tutun ve gövdeyi bacağa yaklaştırın.","dikkat":"Başın kalbin altında kalması nedeniyle tansiyon ya da baş dönmesi tarif eden öğrenci kısa kalsın. Hamstring ağrısında öğrencinin doktoruna ya da fizyoterapistine danışmasını önerin.","s":33,"fig":false},{"n":28,"bolum":2,"ad":"Yan plank (Vasisthasana)","aile":"Kol dengesi","seviye":"Orta","yogunluk":[4,6,7],"calisan":["Oblikler","Serratus anterior","Deltoid","Gluteus medius ve minimus"],"dengeleyen":["Rotator manşet","Quadratus lumborum","Transversus abdominis"],"uzayan":[],"ozet":"Tek el ve ayakların dış kenarı üzerinde yan düzlemde bedeni tek bir çizgide tutmayı öğretir. Omuz stabilitesi ve yan gövde gücü için temel pozdur.","asamalar":{"giris":"Plank'ten ağırlığı sağ ele verin ve ayakların dış kenarına dönün. Nefes alarak kalçaları yukarı kaldırıp sol kolu tavana uzatın.","kalis":"Destek eli omzun hafifçe önünde, omuz kulaktan uzak; kalça çökmez, baştan topuklara düz bir çizgi oluşur. 3–5 nefes kalın.","cikis":"Nefes vererek üst eli yere indirin ve plank'e dönün, ardından diğer tarafa geçin."},"hata":{"ne":"Kalçanın yere doğru sarkması.","neden":"Yan gövde kasları ve gluteus medius yorulduğunda pelvis yerçekimine teslim olur ve yük omuza biner.","yonlendirme":"Kalça yukarı, baştan topuğa tek çizgi."},"soylenecekler":["Alt elinizle yeri itin, omzunuzu kulağınızdan uzaklaştırın.","Kalçanızı tavana doğru kaldırın.","Başınızın tepesinden topuklarınıza tek bir çizgi uzatın."],"eller":{"nereye":"Bir el alt taraftaki kalçanın yanına, hafifçe.","nasil":"Kalçayı yukarı doğru çok hafif yönlendirerek çizgiyi gösterin; ağırlık taşımayın.","ne_zaman_degil":"Bilek ya da omuz ağrısı, omuz instabilitesi ya da izin olmadığında dokunmayın."},"kolay":"Alt dizi yere indirin ya da ön kol üzerinde çalışın.","zor":"Üst bacağı kaldırın ya da üst eliyle ayak başparmağını tutup bacağı yukarı uzatın.","dikkat":"Bilek ve omuz hassasiyetinde ön kol varyasyonu seçilsin. Ağrı tarif edilirse öğrencinin doktoruna ya da fizyoterapistine danışmasını önerin.","s":34,"fig":false},{"n":29,"bolum":2,"ad":"Tekne (Navasana)","aile":"Denge","seviye":"Orta","yogunluk":[4,6,8],"calisan":["Rektus abdominis","İliopsoas","Kuadriseps"],"dengeleyen":["Transversus abdominis","Erector spinae","Oblikler"],"uzayan":["Hamstringler"],"ozet":"Oturma kemikleri üzerinde dengede kalırken omurgayı uzun ve karın merkezini aktif tutmayı öğretir. Sınıfın güç bölümünde merkez çalışması için kullanılır.","asamalar":{"giris":"Dizler bükülü oturun ve elleri uylukların arkasına koyun. Nefes alarak göğsü kaldırın, hafifçe geriye yaslanıp ayakları yerden kaldırın; incikler yere paralel olsun.","kalis":"Ağırlık oturma kemiklerinin hemen arkasında, omurga uzun, göğüs açık; kollar yere paralel öne uzanır. Nefes akmaya devam eder, 5 nefes kalın.","cikis":"Nefes vererek ayakları yere indirin, elleri dizlere koyun ve sırtı rahatlatın."},"hata":{"ne":"Sırtın yuvarlanıp sakrumun üzerine çökmesi.","neden":"Kalça fleksörleri ve karın kasları yetersiz kaldığında pelvis arkaya devrilir ve yük bel omurlarına geçer.","yonlendirme":"Oturma kemikleri önünde, göğüs yukarı."},"soylenecekler":["Göğsünüzü kaldırın, sırtınız uzun.","Dizlerinizi bükülü tutmak tamamen geçerli.","Nefesinizi tutmayın; karnınız aktif, nefesiniz akıyor."],"eller":{"nereye":"Bir el sırtın orta kısmına (kürek kemiklerinin altı), düz avuçla.","nasil":"Sırta hafifçe yukarı ve öne doğru uzama yönü verin; öğrenciyi taşımayın.","ne_zaman_degil":"Bel ağrısı, gebelik, yakın zamanda karın ameliyatı geçirmiş olma ya da izin olmadığında dokunmayın."},"kolay":"Ayakları yerde tutun ya da ellerle uylukların arkasını tutmaya devam edin.","zor":"Bacakları düzleştirip V şekli oluşturun ya da nefesle yarım tekneye inip geri kalkın.","dikkat":"Gebelikte ve yakın tarihli karın ameliyatı sonrasında bu poz yerine başka bir merkez çalışması seçilsin. Bel ağrısında öğrencinin doktoruna ya da fizyoterapistine danışmasını önerin.","s":35,"fig":false},{"n":30,"bolum":2,"ad":"Karga (Bakasana)","aile":"Kol dengesi","seviye":"Orta","yogunluk":[5,7,8],"calisan":["Serratus anterior","Triceps brachii","Rektus abdominis","İliopsoas"],"dengeleyen":["Rotator manşet","Addüktörler","Transversus abdominis"],"uzayan":[],"ozet":"Kollarda dengeyi, karın merkezini toplayarak ve ağırlığı ellerin üzerine aktararak kurmayı öğretir. Kol dengelerine giriş ve özgüven çalışması için kullanılır.","asamalar":{"giris":"Çömelin, elleri omuz genişliğinde yere koyun ve parmakları açın. Dizleri üst kollara yerleştirin, nefes vererek ağırlığı öne aktarıp ayakları sırayla yerden kaldırın.","kalis":"Sırt yuvarlak ve karın içeri toplanır, dirsekler bileklerin üzerinde; bakış ellerin önünde. 3–5 nefes kalın.","cikis":"Nefes vererek ayakları kontrollü biçimde yere indirin, elleri kaldırıp çömelmede bilekleri gevşetin."},"hata":{"ne":"Başı düşürüp öne dalmak.","neden":"Ağırlık öne aktarılırken karın merkezi toplanmazsa baş ağırlık merkezini aşar ve beden öne devrilir.","yonlendirme":"Bakış ileride, sırt yuvarlak."},"soylenecekler":["Bakışınızı ellerinizin önüne, yere verin.","Sırtınızı yuvarlayın, karnınızı içeri toplayın.","Önce bir ayak, sonra diğeri; acele yok."],"eller":{"nereye":"Öğrencinin önünde diz çökerek, iki el omuzların ön yüzüne çok hafifçe.","nasil":"Öğrenci öne fazla kaçarsa omuzları hafifçe destekleyin; ağırlığı taşımayın ya da kaldırmayın.","ne_zaman_degil":"Bilek ağrısı, omuz instabilitesi, gebelik ya da izin olmadığında dokunmayın."},"kolay":"Ayakları blok üzerine koyarak başlayın ve yüzün önüne yastık yerleştirin; ayakları tek tek kaldırın.","zor":"Kolları düzleştirerek Kakasana'dan Bakasana'ya geçin ya da Chaturanga'ya geri atlayın.","dikkat":"Bilek hassasiyetinde ağırlık parmak tabanlarına dağıtılsın ve süre kısa tutulsun. Gebelikte yapılmasın; bilek veya omuz ağrısında öğrencinin doktoruna ya da fizyoterapistine danışmasını önerin.","s":36,"fig":true},{"n":31,"bolum":2,"ad":"Parmak ucunda sandalye","aile":"Denge","seviye":"Orta","yogunluk":[4,6,7],"calisan":["Kuadriseps","Gastroknemius ve soleus","Gluteus maximus"],"dengeleyen":["Tibialis anterior","Transversus abdominis","Addüktörler"],"uzayan":[],"ozet":"Parmak tabanları üzerinde derin bir çömelmeyle dik gövdeyi korumayı öğretir. Ayak bileği stabilitesi, bacak gücü ve odaklanma için kullanılır.","asamalar":{"giris":"Ayaklar birleşik durun ve topukları kaldırın. Nefes vererek dizleri bükerek kalçaları yavaşça topuklara doğru indirin, elleri göğüs önünde birleştirin.","kalis":"Topuklar birbirine değer, ağırlık başparmak tabanında; dizler birbirine yakın ve gövde diktir. 5 nefes kalın.","cikis":"Nefes alarak ayaklara basıp yavaşça yükselin, topukları yere indirin ve Dağ pozunda durun."},"hata":{"ne":"Topukların yana kayıp ayak bileklerinin dışa yuvarlanması.","neden":"Baldır ve tibialis anterior arasında denge kurulamadığında ayak bileği dış kenara devrilir.","yonlendirme":"Topuklar birbirine değer, ağırlık başparmak tabanında."},"soylenecekler":["Topuklarınızı birbirine bastırın.","Ağırlığınızı başparmak tabanınıza verin.","Gövdeniz dik, bakışınız sabit bir noktada."],"eller":{"nereye":"İki el kalçaların yanına, öğrencinin arkasında durarak.","nasil":"Kalçaları dikey olarak ortada tutacak biçimde çok hafif destekleyin; aşağı bastırmayın.","ne_zaman_degil":"Diz ağrısı, ayak bileği instabilitesi, düşme korkusu ya da izin olmadığında dokunmayın."},"kolay":"Topukların altına katlanmış battaniye koyun ya da bir eli duvara yaslayın; daha az bükülün.","zor":"Kolları yukarı uzatın ya da bu pozdan dizleri yana açarak Tanrıça'ya, oradan yukarı geçin.","dikkat":"Diz ya da ayak bileği hassasiyetinde çömelme sığ tutulsun. Ağrı tarif edilirse öğrencinin doktoruna ya da fizyoterapistine danışmasını önerin.","s":37,"fig":false},{"n":32,"bolum":2,"ad":"Dönen yarım ay (Parivrtta Ardha Chandrasana)","aile":"Denge","seviye":"İleri","yogunluk":[5,7,8],"calisan":["Gluteus maximus","Oblikler","Gluteus medius ve minimus","Multifidus"],"dengeleyen":["Tibialis anterior","Transversus abdominis","Kuadriseps"],"uzayan":["Hamstringler"],"ozet":"Tek bacak üzerinde dengede kalırken gövdeyi destek bacağa doğru döndürmeyi öğretir. Burgu, denge ve arka zincir gücünü aynı anda gerektiren ileri seviye bir pozdur.","asamalar":{"giris":"Savaşçı III'ten karşı eli omzun altına bloğa koyun. Nefes alarak omurgayı uzatın, nefes vererek göğsü destek bacak tarafına çevirip üst kolu tavana uzatın.","kalis":"Pelvis yere paralel ve seviyeli kalır, kaldırılan bacak aktif; dönüş göğüs kafesinden gelir. 3–5 nefes kalın.","cikis":"Nefes vererek üst eli bloğa ya da kalçaya indirin, kaldırılan bacağı yavaşça yere bırakın ve Ayakta öne eğilmeye geçin."},"hata":{"ne":"Kaldırılan bacağın dışa dönüp ayağın tavana bakması.","neden":"Burgu derinleşirken pelvis de döner ve kaldırılan bacak kalçayla birlikte dışa açılır.","yonlendirme":"Arka ayak parmakları yere bakar."},"soylenecekler":["Kaldırdığınız ayağın parmakları yere baksın.","Önce uzayın, sonra göğsünüzü çevirin.","Alt eliniz bloğa değsin, ağırlık destek bacağınızda."],"eller":{"nereye":"Bir el kaldırılan bacağın kalçasına, diğer el destek tarafının kalçasına.","nasil":"Kalçaları seviyeli tutacak yönde çok hafif yönlendirin; burguyu derinleştirmek için çevirmeyin.","ne_zaman_degil":"Bel veya sakroiliak ağrısı, gebelik, düşme riski ya da izin olmadığında dokunmayın."},"kolay":"Alt eli yüksek bloğa koyun, üst eli kalçada tutun ve bakışı yerde bırakın.","zor":"Üst kolu tavana uzatıp bakışı yukarı çevirin ve 5 nefes kalın.","dikkat":"Gebelikte bu kapalı burgu yapılmasın. Bel veya ayak bileğinde ağrı varsa, ayrıca dengede zorlanan öğrencilerde duvar kullanılsın; öğrencinin doktoruna ya da fizyoterapistine danışmasını önerin.","s":38,"fig":false},{"n":33,"bolum":3,"ad":"Oturarak öne eğilme (Paschimottanasana)","aile":"Oturarak","seviye":"Başlangıç","yogunluk":[2,4,6],"calisan":["Hamstringler","Erector spinae","Kuadriseps"],"dengeleyen":["Gastroknemius ve soleus","Transversus abdominis"],"uzayan":["Hamstringler","Gastroknemius ve soleus","Erector spinae"],"ozet":"Kalça eklemlerinden öne katlanmayı ve sırtın uzunluğunu korumayı öğretir. Dersin sakinleşme bölümünde bacakların arka zincirine dikkat çekmek için kullanılır.","asamalar":{"giris":"Asa pozunda (Dandasana) oturma kemiklerinin üzerine yerleşin; nefes alarak omurgayı uzatın, nefes vererek pelvisi öne devirip gövdeyi kalçalardan öne katlayın.","kalis":"Göğüs kemiği ayaklara doğru uzanır, pelvis öne devrik kalır, boyun omurganın devamıdır. Her nefes alışta uzayın, her nefes verişte biraz daha yumuşayın; 5–10 nefes kalın.","cikis":"Nefes alarak elleri bacaklar üzerinde geri yürütün ve omurgayı omur omur dik oturuşa getirin; nefes vererek dizleri hafifçe bükün."},"hata":{"ne":"Kendini ayaklara doğru çekip sırtı kamburlaştırmak.","neden":"Hamstringler kısa olduğunda pelvis geriye devrilir ve hareket kalça yerine bel omurlarından gelir.","yonlendirme":"Bir battaniyenin üstüne oturun ve sırtı uzatın."},"soylenecekler":["Oturma kemiklerinizi hissedin ve onların biraz önüne gelin.","Göğsünüz ayaklarınıza doğru uzansın, burnunuz dizlere değil.","Dizleri bükmek serbest; uzun sırt, düz bacaktan daha önemli."],"eller":{"nereye":"Sakrumun üst kenarı ve bel bölgesinin iki yanı.","nasil":"Pelvisin öne devrilmesine eşlik edecek şekilde sakrumu hafifçe öne ve aşağı yönlendirin; asla sırtın ortasından aşağı bastırmayın.","ne_zaman_degil":"Öğrenci onay vermediğinde, bel ya da hamstring bölgesinde ağrı bildirdiğinde veya hamilelikte."},"kolay":"Katlanmış battaniyeye oturun, dizleri bükün ve ayak tabanlarına bir kayış dolayın.","zor":"Dizler düz, elleri ayakların ötesinde birleştirin ve karnı uyluklara yaklaştırın; sırt uzun kalsın.","dikkat":"Bel fıtığı öyküsü, siyatik tipi ağrı ya da hamstring zorlanması bildiren öğrencide dizleri bükülü tutun ve derinliği azaltın; ağrı sürüyorsa öğrencinin doktoruna ya da fizyoterapistine danışmasını önerin. Hamilelikte bacakları açarak karna yer bırakın.","s":40,"fig":true},{"n":34,"bolum":3,"ad":"Baş dize (Janu Sirsasana)","aile":"Öne eğilme","seviye":"Başlangıç","yogunluk":[2,4,6],"calisan":["Hamstringler","Erector spinae","Oblikler"],"dengeleyen":["Kuadriseps","Quadratus lumborum"],"uzayan":["Hamstringler","Addüktörler","Quadratus lumborum"],"ozet":"Tek bacak üzerinde öne eğilmeyi ve gövdeyi uzanan bacağın ortasına hizalamayı öğretir. İki taraf ayrı çalışıldığı için asimetrileri fark ettirmede işe yarar.","asamalar":{"giris":"Sağ bacak uzanır, sol ayak tabanı sağ iç uyluğa yerleşir. Nefes alarak gövdeyi sağ bacağa doğru çevirip uzatın, nefes vererek kalçadan öne katlanın.","kalis":"Göbek ve göğüs kemiği uzanan bacağın ortasına bakar, bükülü dizin tarafındaki bel uzun kalır. 5–8 nefes kalın, her nefes alışta uzayın.","cikis":"Nefes alarak gövdeyi kaldırın, nefes vererek bükülü bacağı uzatın ve diğer tarafa geçin."},"hata":{"ne":"Gövdeyi bükülü dizin tarafına çökertip uzanan bacağa yan yan eğilmek.","neden":"Bükülü bacağın kalçası dışa döndüğünde pelvis o yöne açılır ve gövde merkezden kayar.","yonlendirme":"Göbek deliği uzanan dizin ortasına baksın."},"soylenecekler":["Bükülü dizinizin altına destek koymak serbest.","Önce gövdenizi uzanan bacağınıza çevirin, sonra eğilin.","İki yan beliniz aynı uzunlukta kalsın."],"eller":{"nereye":"Bükülü bacak tarafındaki kalçanın arkası ve aynı taraftaki kaburgaların yanı.","nasil":"Kalçayı hafifçe geriye ve aşağı sabitlerken kaburgaları uzanan bacağa doğru yönlendirin; çekmeyin, yalnızca eşlik edin.","ne_zaman_degil":"Bükülü dizde ağrı ya da menisküs sorunu bildirildiğinde veya öğrenci dokunulmak istemediğinde."},"kolay":"Battaniyeye oturun, uzanan dizin altına rulo battaniye koyun ve ayağa kayış dolayın.","zor":"Uzanan bacağın ayağını iki elle kavrayın ve alnı kaval kemiğine yaklaştırın; sırt uzun kalsın.","dikkat":"Diz ağrısı bildiren öğrencide bükülü dizi blokla destekleyin; dizde sıkışma hissi sürerse öğrencinin doktoruna ya da fizyoterapistine danışmasını önerin.","s":41,"fig":false},{"n":35,"bolum":3,"ad":"Geniş bacaklı oturarak öne eğilme (Upavistha Konasana)","aile":"Öne eğilme","seviye":"Orta","yogunluk":[3,5,7],"calisan":["Addüktörler","Hamstringler","Erector spinae"],"dengeleyen":["Kuadriseps","Transversus abdominis"],"uzayan":["Addüktörler","Hamstringler"],"ozet":"Bacaklar geniş açıdayken pelvisi öne devirmeyi öğretir; iç uylukların ve hamstringlerin uzamasını sabırla keşfetmek için kullanılır.","asamalar":{"giris":"Bacakları rahatça açabildiğiniz kadar açın, dizkapakları ve ayak parmakları tavana baksın. Nefes alarak oturma kemiklerine yerleşin, nefes vererek ellerinizi öne yürütün.","kalis":"Pelvis öne devrilir, bel kavisi korunur, dizkapakları tavana dönük kalır. 8–10 nefes kalın; her nefes verişte bir parmak kadar ilerleyin.","cikis":"Nefes alarak elleri geri yürütüp gövdeyi dikleştirin; nefes vererek elleri dizlerin altına koyun ve bacakları yavaşça birleştirin."},"hata":{"ne":"Bacakları fazla açıp dizlerin içe dönmesine izin vermek.","neden":"Addüktörler gerildikçe femur içe döner ve gerilim dizin iç tarafına kayar.","yonlendirme":"Dizkapakları tavana bakar."},"soylenecekler":["Bacaklarınızı biraz daraltın, sırtınız daha uzun kalsın.","Elleriniz öne yürürken göğsünüz de öne gelsin.","Derinlik değil, rahat bir nefes arıyoruz."],"eller":{"nereye":"Sakrumun üstü ve kalçaların arka tarafı.","nasil":"Pelvisin öne devrilmesine yardım edecek kadar hafif, öne doğru bir yönlendirme verin; asla omuzlardan bastırmayın.","ne_zaman_degil":"Kasık ya da iç uylukta zorlanma bildirildiğinde, hamilelikte ya da öğrenci onay vermediğinde."},"kolay":"Yüksek bir battaniyeye oturun, dizleri hafifçe bükün ve elleri önünüzdeki bloklara koyun.","zor":"Elleri ayak başparmaklarına uzatın, karnı ve göğsü yere yaklaştırın.","dikkat":"Kasık zorlanması ya da dizin iç tarafında ağrı bildiren öğrencide açıyı daraltın; ağrı geçmezse öğrencinin doktoruna ya da fizyoterapistine danışmasını önerin.","s":42,"fig":false},{"n":36,"bolum":3,"ad":"Öne eğilen kelebek (Baddha Konasana)","aile":"Öne eğilme","seviye":"Başlangıç","yogunluk":[2,3,5],"calisan":["Erector spinae","Gluteus medius ve minimus"],"dengeleyen":["Transversus abdominis","Pelvik taban"],"uzayan":["Addüktörler","Erector spinae"],"ozet":"Ayak tabanları birleşikken kalçadan öne eğilmeyi öğretir; iç uylukların ve sırtın uzunluğuna dikkat çeker, dersin başı ya da sonu için uygundur.","asamalar":{"giris":"Ayak tabanlarını birleştirip topukları rahat bir mesafeye çekin, ellerinizle ayakları tutun. Nefes alarak omurgayı uzatın, nefes vererek kalçalardan öne eğilin.","kalis":"Göğüs ayaklara doğru uzanır, dizler kendi ağırlığıyla aşağı iner, omuzlar kulaklardan uzaktır. 8–10 nefes kalın.","cikis":"Nefes alarak gövdeyi kaldırın; nefes vererek dizleri ellerinizle birleştirin ve bacakları uzatın."},"hata":{"ne":"Dizleri yere değdirmek için dirseklerle uyluklara bastırmak.","neden":"Kalça eklemi dış rotasyonun sonuna gelince basınç diz eklemine ve kasığa aktarılır.","yonlendirme":"Dizler kendi ağırlığıyla insin."},"soylenecekler":["Ayak tabanlarınızı bir kitabın sayfaları gibi açabilirsiniz.","Başınız değil, göğsünüz ayaklarınıza gidiyor.","Dizlerinizin yüksekliği önemli değil, olduğu yerde kalsın."],"eller":{"nereye":"Kürek kemiklerinin arası ve sakrum.","nasil":"Bir elle sakrumu yere doğru sabitleyin, diğerini sırta düz koyup uzamaya eşlik edin; aşağı bastırmayın.","ne_zaman_degil":"Kasık ya da diz ağrısı varsa, hamilelikte ya da öğrenci dokunulmak istemediğinde."},"kolay":"Battaniyeye oturun, dizlerin altına blok koyun ve topukları kasıktan uzaklaştırın.","zor":"Topukları kasığa yaklaştırın ve alnı ayaklara indirin; sırt uzun kalsın.","dikkat":"Diz ya da kasık ağrısı bildiren öğrencide dizleri blokla destekleyin ve öne eğilmeyi sınırlayın; hamilelikte gövdeyi dik tutun. Ağrı sürerse öğrencinin doktoruna ya da fizyoterapistine danışmasını önerin.","s":43,"fig":false},{"n":37,"bolum":3,"ad":"Yarım öne eğilme (Ardha Uttanasana)","aile":"Öne eğilme","seviye":"Başlangıç","yogunluk":[2,3,4],"calisan":["Erector spinae","Multifidus","Orta ve alt trapezius"],"dengeleyen":["Kuadriseps","Transversus abdominis"],"uzayan":["Hamstringler","Gastroknemius ve soleus"],"ozet":"Ayakta öne eğilmeden düz sırtla yarıya yükselmeyi öğretir; güneşe selamda sırt kaslarını devreye sokan geçiş pozudur.","asamalar":{"giris":"Ayakta öne eğilmede elleri kaval kemiklerine ya da bloklara koyun. Nefes alarak göğsü öne uzatın ve omurgayı yere paralel hâle getirin.","kalis":"Baş, göğüs ve pelvis tek çizgide; bel ne kamburlaşır ne aşırı çukurlaşır, bakış bir adım öndedir. 3–5 nefes kalın.","cikis":"Nefes vererek gövdeyi yeniden ayakta öne eğilmeye bırakın ya da elleri bele alıp düz sırtla ayağa kalkın."},"hata":{"ne":"Başı yukarı kaldırıp boynu arkaya sıkıştırmak.","neden":"Göğsü açma niyeti sırttan değil boyundan gelince boyun omurları uzamak yerine geriye kırılır.","yonlendirme":"Uzun ense, bakış yere çapraz."},"soylenecekler":["Elleriniz kaval kemiğinizde, göğsünüz öne uzansın.","Kuyruk sokumunuzdan başınızın tepesine kadar düz bir çizgi var.","Dizleri bükmek düz sırtı kolaylaştırır."],"eller":{"nereye":"Sakrum ve kürek kemiklerinin arası.","nasil":"Sakrumu hafifçe geriye, göğüs bölgesini öne yönlendirerek iki uç arasında uzamayı hissettirin.","ne_zaman_degil":"Bel ağrısı bildirildiğinde ya da öğrenci onay vermediğinde."},"kolay":"Elleri yüksek bloklara ya da duvara koyun ve dizleri bükün.","zor":"Parmak uçlarını yere koyun ya da kolları kulak hizasında öne uzatarak düz sırtı koruyun.","dikkat":"Bel ağrısı ya da baş dönmesi yaşayan öğrencide elleri yüksek desteğe koyun ve kısa kalın; şikâyet sürüyorsa öğrencinin doktoruna ya da fizyoterapistine danışmasını önerin.","s":44,"fig":false},{"n":38,"bolum":3,"ad":"Bez bebek","aile":"Öne eğilme","seviye":"Başlangıç","yogunluk":[1,3,4],"calisan":["Kuadriseps","Hamstringler"],"dengeleyen":["Gastroknemius ve soleus","Tibialis anterior"],"uzayan":["Erector spinae","Hamstringler","Rhomboidler"],"ozet":"Dizler yumuşak, dirsekler tutulu olarak ayakta öne asılmayı öğretir; aktif bir esneme değil, sırtı ve boynu bırakma anıdır.","asamalar":{"giris":"Ayaklar kalça genişliğinde, dizleri cömertçe bükün. Nefes vererek gövdeyi uylukların üzerine bırakın ve karşı dirsekleri tutun.","kalis":"Karın uyluklara yakın, baş ve boyun tamamen asılı, ağırlık ayak tabanının ön kısmında. Hafifçe sağa sola sallanarak 5–10 nefes kalın.","cikis":"Elleri bırakın, dizleri daha çok bükün ve nefes alarak omur omur yuvarlanarak yükselin; baş en son gelsin."},"hata":{"ne":"Dizleri düzleyip ağırlığı topuklara atmak.","neden":"Dizler kilitlenince hamstringler gerilir, pelvis geriye kayar ve yükü bel bölgesi taşır.","yonlendirme":"Dizler bükük, karın uyluklarda."},"soylenecekler":["Başınızı evet ve hayır der gibi hafifçe sallayın.","Ağırlığınızı biraz öne, ayak parmaklarınıza doğru verin.","Burada yapacak bir şey yok, sadece asılın."],"eller":{"nereye":"Sakrumun iki yanı ya da kürek kemiklerinin üstü.","nasil":"Avuçlarla çok hafif bir ağırlık bırakarak bırakma hissini destekleyin; aşağı itmeyin.","ne_zaman_degil":"Yüksek tansiyon, baş dönmesi ya da göz içi basıncı sorunu bildirildiğinde ve onay yoksa."},"kolay":"Dirsekleri tutmak yerine ön kolları uylukların üstüne koyun.","zor":"Elleri topukların arkasına koyun ve dizleri biraz daha uzatın; karın uyluklardan ayrılmasın.","dikkat":"Yüksek tansiyon, baş dönmesi ya da glokom bildiren öğrencide başı kalp seviyesinin üstünde tutan yarım öne eğilmeyi önerin ve yavaşça kalkmalarını hatırlatın.","s":45,"fig":false},{"n":39,"bolum":3,"ad":"Yavru köpek (Uttana Shishosana)","aile":"Öne eğilme","seviye":"Başlangıç","yogunluk":[2,4,5],"calisan":["Serratus anterior","Deltoid","Orta ve alt trapezius"],"dengeleyen":["Transversus abdominis","Kuadriseps"],"uzayan":["Latissimus dorsi","Büyük ve küçük pektoral","Triceps brachii"],"ozet":"Kalçalar dizlerin üstünde kalırken göğsü yere doğru eritmeyi öğretir; omuzları ve üst sırtı açan, çocuk pozu ile aşağı bakan köpek arasında bir köprüdür.","asamalar":{"giris":"Dört ayak pozisyonundan elleri birkaç karış öne yürütün, kalçaları dizlerin tam üstünde tutun. Nefes vererek göğsü yere doğru indirin, alnı ya da çeneyi mata koyun.","kalis":"Kalçalar dizlerin üstünde, kollar omuz genişliğinde ve aktif, bel aşırı çukurlaşmaz. 5–8 nefes kalın; nefesi kaburgaların arkasına yönlendirin.","cikis":"Nefes alarak elleri geri yürütün ve dört ayak pozisyonuna dönün ya da kalçaları topuklara indirip çocuk pozunda dinlenin."},"hata":{"ne":"Göğsü indirmek için bel bölgesini çukurlaştırmak.","neden":"Omuz eklemindeki hareket sınırlı olduğunda açılma göğüs omurgası yerine bel omurlarından telafi edilir.","yonlendirme":"Kaburgalar içeri, göğüs yere."},"soylenecekler":["Kalçalarınız dizlerinizin üstünde kalsın.","Avuçlarınızla mata bastırın, dirsekleri yerden kaldırın.","Göğsünüz yumuşak bir şekilde yere erisin."],"eller":{"nereye":"Kalça kemiklerinin üstü ya da iki kürek kemiğinin arası.","nasil":"Kalçaları hafifçe geriye yönlendirerek omurgada uzama hissettirin; göğsü yere bastırmayın.","ne_zaman_degil":"Omuz ağrısı, omuz çıkığı öyküsü ya da diz ağrısı bildirildiğinde ve onay yoksa."},"kolay":"Ellerin altına bloklar, dizlerin altına katlanmış battaniye koyun.","zor":"Avuçları birleştirip dirsekleri bükün, başparmakları ensenin arkasına koyarak omuz açılımını artırın.","dikkat":"Omuz ağrısı ya da hareket kısıtlılığı bildiren öğrencide elleri bloklara koyun ve kolları açın; dizlerde hassasiyet varsa destek ekleyin. Ağrı sürerse öğrencinin doktoruna ya da fizyoterapistine danışmasını önerin.","s":46,"fig":false},{"n":40,"bolum":3,"ad":"Çocuk pozu (Balasana)","aile":"Restoratif","seviye":"Başlangıç","yogunluk":[1,1,2],"calisan":["Diyafram","Transversus abdominis"],"dengeleyen":["Pelvik taban","Addüktörler"],"uzayan":["Erector spinae","Quadratus lumborum","Kuadriseps"],"ozet":"Ders boyunca istenen her an dönülebilecek dinlenme pozudur; öğrenciye nefesi sırtın arka tarafına yönlendirmeyi öğretir.","asamalar":{"giris":"Dizler yerde, ayak başparmakları birbirine değer. Nefes vererek kalçaları topuklara doğru indirin, gövdeyi uylukların üzerine ya da arasına bırakın ve alnı yere koyun.","kalis":"Alın yerde ya da blokta, kollar önde veya bedenin yanında, omuzlar yumuşak. Nefes alışta sırtın genişlediğini hissedin; 1–3 dakika kalın.","cikis":"Elleri omuzların altına getirin ve nefes alarak omur omur dik oturuşa ya da dört ayak pozisyonuna yükselin."},"hata":{"ne":"Kalçalar topuklara inmediği hâlde alnı zorla yere değdirmeye çalışmak.","neden":"Diz ve ayak bileği bükülmesi sınırlı olduğunda ağırlık boyna ve omuzlara aktarılır.","yonlendirme":"Yer gelmiyorsa, yeri yükseltin."},"soylenecekler":["Dizlerinizi istediğiniz kadar açabilirsiniz.","Nefesinizi sırtınıza, böbreklerinizin bulunduğu bölgeye gönderin.","Bu poz her zaman sizin için burada; istediğiniz an dönün."],"eller":{"nereye":"Sakrumun üstü, avuç içi düz.","nasil":"Nefes verişte çok hafif bir ağırlık bırakarak sakrumu topuklara doğru yönlendirin, nefes alışta elinizi gevşetin.","ne_zaman_degil":"Diz ağrısında, hamilelikte ya da öğrenci dinlenirken temas istemediğinde; dinlenme pozunda önce mutlaka sözlü izin alın."},"kolay":"Kalçalarla topukların arasına katlanmış battaniye, alnın altına blok ya da gövdenin altına uzunlamasına bolster koyun.","zor":"Kolları öne uzatıp avuçlarla aktif bastırarak omuzlarda ve yan hatta uzama yaratın.","dikkat":"Diz ağrısı bildiren öğrencide dizlerin arkasına battaniye koyun ya da sırtüstü dizler göğüste varyasyonunu önerin; hamilelikte dizleri geniş açıp karna yer bırakın.","s":47,"fig":true},{"n":41,"bolum":3,"ad":"Sırtüstü el ayak başparmağına (Supta Padangusthasana)","aile":"Sırtüstü","seviye":"Başlangıç","yogunluk":[2,4,6],"calisan":["Kuadriseps","İliopsoas","Rektus abdominis"],"dengeleyen":["Transversus abdominis","Gluteus medius ve minimus"],"uzayan":["Hamstringler","Gastroknemius ve soleus"],"ozet":"Sırt yerdeyken ve pelvis nötr kalırken hamstringleri tek tek çalışmayı öğretir; bel bölgesi destekte kaldığı için kontrollü bir arka bacak uzaması sunar.","asamalar":{"giris":"Sırtüstü uzanın, sağ ayak tabanına bir kayış dolayın. Nefes alarak sağ bacağı tavana doğru kaldırın; sol bacak yerde uzun kalsın.","kalis":"Pelvis yerde düz, yerdeki bacağın uyluğu mata bastırır, omuzlar gevşek. Kalkan bacağı dizde hafif bükülü bile olsa uzun tutun; 5–10 nefes kalın.","cikis":"Nefes vererek kayışı gevşetin, dizi bükün ve ayağı yere indirin; diğer tarafa geçin."},"hata":{"ne":"Bacağı yaklaştırmak için kalçayı yerden kaldırmak.","neden":"Hamstringler sınıra geldiğinde pelvis geriye devrilir ve hareket bel omurlarına kayar.","yonlendirme":"Pelvis yerde, bacak bir kayış boyu uzakta."},"soylenecekler":["Kayışı çekmeden, uzun kollarla tutun.","Yerdeki bacağınızın uyluğunu mata bastırın.","Kalkan bacak ne kadar yüksek değil, ne kadar uzun?"],"eller":{"nereye":"Yerdeki bacağın uyluğunun önü ve kalkan bacağın topuğu.","nasil":"Yerdeki uyluğu hafifçe aşağı sabitleyin; kalkan bacağı öğrencinin kontrolünde bırakın, yalnızca destek olun, itmeyin.","ne_zaman_degil":"Hamstring zorlanması ya da siyatik tipi ağrı bildirildiğinde veya öğrenci izin vermediğinde."},"kolay":"Yerdeki dizi bükün, ayak tabanı yerde kalsın; kalkan bacakta dizi yumuşak tutun.","zor":"Kayışı bırakıp ayak başparmağını iki parmakla tutun ya da bacağı yana açarak ikinci varyasyona geçin.","dikkat":"Siyatik tipi ağrı ya da bel fıtığı öyküsü bildiren öğrencide bacağı alçakta, dizi bükülü tutun; uyuşma veya karıncalanma olursa pozdan çıkın ve öğrencinin doktoruna ya da fizyoterapistine danışmasını önerin.","s":48,"fig":false},{"n":42,"bolum":3,"ad":"Yarım split (Ardha Hanumanasana)","aile":"Öne eğilme","seviye":"Başlangıç","yogunluk":[2,4,6],"calisan":["Hamstringler","Erector spinae","Kuadriseps"],"dengeleyen":["Gluteus medius ve minimus","Transversus abdominis"],"uzayan":["Hamstringler","Gastroknemius ve soleus"],"ozet":"Alçak hamleden ön bacağı uzatarak, kalçalar geride kalırken öne katlanmayı öğretir; split için temel hazırlık pozudur.","asamalar":{"giris":"Alçak hamlede arka dizi yere koyun, elleri ön ayağın iki yanına ya da bloklara alın. Nefes vererek kalçaları arka dizin üstüne geri götürün ve ön bacağı uzatın.","kalis":"Kalçalar arka dizin üstünde, ön ayak bileği bükülü, sırt uzun; gövde ön bacağın üzerine katlanır. 5–8 nefes kalın.","cikis":"Nefes alarak ön dizi bükün, kalçaları öne getirip alçak hamleye dönün ya da elleri omuzların altına alıp dört ayak pozisyonuna geçin."},"hata":{"ne":"Kalçaları arka dizin önünde bırakıp ön bacağa yığılmak.","neden":"Kalça diz hizasından öne kaydığında hamstringler uzamaz; ağırlık ön dize ve bel bölgesine biner.","yonlendirme":"Kalça arka dizin tam üstünde."},"soylenecekler":["Ön ayak parmaklarınızı kendinize doğru çekin.","Kalçanızı geri, göğsünüzü öne gönderin.","Ön dizi bükmek serbest; sırtın uzunluğu öncelik."],"eller":{"nereye":"Arka bacak tarafındaki kalça kemiğinin önü ve sakrum.","nasil":"Kalçayı hafifçe geriye, arka dizin üstüne yönlendirin; gövdeyi öne itmeyin.","ne_zaman_degil":"Hamstring zorlanması ya da diz ağrısı varsa ve onay yoksa."},"kolay":"Arka dizin altına katlanmış battaniye, ellerin altına iki yüksek blok koyun.","zor":"Blokları kaldırın, ön kollarınızı yere indirip gövdeyi kaval kemiğine yaklaştırın.","dikkat":"Diz kapağında basınç hisseden öğrencide arka dizi battaniyeyle destekleyin; hamstringlerde keskin bir his olursa pozdan çıkın, sürerse öğrencinin doktoruna ya da fizyoterapistine danışmasını önerin.","s":49,"fig":false},{"n":43,"bolum":3,"ad":"Split (Hanumanasana)","aile":"Öne eğilme","seviye":"İleri","yogunluk":[5,7,9],"calisan":["Kuadriseps","Gluteus medius ve minimus","Transversus abdominis"],"dengeleyen":["Addüktörler","Pelvik taban"],"uzayan":["Hamstringler","İliopsoas","Kuadriseps"],"ozet":"Ön bacakta hamstringleri, arka bacakta kalça fleksörlerini aynı anda uzunluğun sonuna götürür; pelvisi kare tutarak ve derinliği bloklarla ayarlayarak sabırla çalışılır.","asamalar":{"giris":"Yarım split'ten ön topuğu ileri, arka dizi geri kaydırın; elleri iki yandaki bloklara koyun. Nefes vererek pelvisi yavaşça yere doğru indirin.","kalis":"Pelvis öne bakar ve kare kalır; arka bacağın dizkapağı yere, ön bacağın dizkapağı tavana bakar. Gövde dik ya da hafif öne eğik, 5 nefes kalın.","cikis":"Ellerle bloklara bastırın, nefes alarak ön dizi bükün ve kalçaları arka dizin üstüne çekin; alçak hamleden çıkın."},"hata":{"ne":"Yere inmek için pelvisi yana açıp arka bacağı dışa döndürmek.","neden":"İliopsoas ve hamstringler sınıra geldiğinde beden pelvisi döndürerek kolay yolu arar.","yonlendirme":"Kalça kemikleri öne, yer kendi gelsin."},"soylenecekler":["Ön uyluğunuzun altına blok ya da bolster koyun.","Arka bacağınızın ayak üstü düz bir şekilde mata bassın.","Burada acele yok; her nefes verişte bir milim."],"eller":{"nereye":"Arka bacak tarafındaki kalça kemiği.","nasil":"Kalça kemiğini öne çevirerek pelvisin kare kalmasına yardım edin; aşağı bastırmayın.","ne_zaman_degil":"Hipermobil öğrencilerde, hamstring ya da kasık zorlanmasında ve hamilelikte; derin pozlarda asla aşağı itmeyin."},"kolay":"Ön uyluğun altına bolster, ellerin altına yüksek bloklar koyun ya da yarım split'te kalın.","zor":"Desteği kaldırın, kolları yukarı uzatın ve hafifçe geriye eğilerek arka bacağın kalça fleksörlerini açın.","dikkat":"Hamstring ya da kasık zorlanması, kalça eklemi sorunu bildiren öğrencide yarım split'te kalın; hipermobil öğrencilerde derinliği destekle sınırlayın. Ağrı varsa öğrencinin doktoruna ya da fizyoterapistine danışmasını önerin.","s":50,"fig":false},{"n":44,"bolum":3,"ad":"Tırtıl","aile":"Restoratif","seviye":"Başlangıç","yogunluk":[1,3,4],"calisan":["Diyafram","Rektus abdominis"],"dengeleyen":["Pelvik taban","Transversus abdominis"],"uzayan":["Erector spinae","Hamstringler","Gastroknemius ve soleus"],"ozet":"Yin yoga tarzında, kas gücü kullanmadan, bacaklar uzanmışken öne kıvrılmaktır; omurganın arka tarafına uzun süreli ve pasif bir uzama sunar.","asamalar":{"giris":"Bacaklar önde uzanmış oturun, isterseniz dizlerin altına rulo koyun. Nefes vererek gövdeyi yuvarlayarak bacakların üzerine bırakın, başı asılı bırakın.","kalis":"Sırt yuvarlak, kaslar gevşek, eller bacakların yanında dinlenir. Nefes yavaş ve doğal; 3–5 dakika kalın ve ara sıra rahatlığınızı kontrol edin.","cikis":"Elleri yere bastırın ve nefes alarak çok yavaş, omur omur yuvarlanarak dik oturuşa gelin; ardından bir süre sırtüstü uzanıp dinlenin."},"hata":{"ne":"Pasif kalması gereken pozda ayaklara uzanıp kendini çekmek.","neden":"Aktif çekiş kasları kasar ve uzun tutuşun amacı olan gevşemeyi engeller.","yonlendirme":"Uzanmayın, bırakın asılın."},"soylenecekler":["Burada hiçbir şey yapmanıza gerek yok.","Başınızın altına bolster ya da blok koyabilirsiniz.","Hissin şiddeti 10 üzerinden 4'ü geçmesin."],"eller":{"nereye":"Sırtın ortası, kürek kemiklerinin hemen altı.","nasil":"Avucu düz koyun; ağırlık vermeden yalnızca sıcaklık ve farkındalık için temas edin.","ne_zaman_degil":"Bel fıtığı öyküsü ya da osteoporoz bildirildiğinde veya öğrenci uzun tutuşta temas istemediğinde."},"kolay":"Dizleri bükün, uylukların üstüne bolster yatırın ve gövdeyi bolster'a bırakın.","zor":"Destek kullanmadan, dizler uzun, 5 dakikaya kadar kalın.","dikkat":"Bel fıtığı öyküsü, siyatik tipi belirtiler ya da osteoporoz bildiren öğrencide yuvarlak sırtla uzun tutuş yerine dizleri bükülü, destekli varyasyonu önerin; gerekirse öğrencinin doktoruna ya da fizyoterapistine danışmasını önerin.","s":51,"fig":false},{"n":45,"bolum":3,"ad":"Oturarak yana eğilme (Parivrtta Janu Sirsasana)","aile":"Oturarak","seviye":"Orta","yogunluk":[3,5,7],"calisan":["Oblikler","Erector spinae"],"dengeleyen":["Transversus abdominis","Rotator manşet"],"uzayan":["Latissimus dorsi","Quadratus lumborum","Hamstringler"],"ozet":"Göğsü tavana açık tutarken uzanan bacağa doğru yana eğilmeyi öğretir; bedenin yan hattını, özellikle üstteki kaburgaları ve beli uzatır.","asamalar":{"giris":"Sağ bacak yana uzanır, sol ayak kasığa yaklaşır. Nefes vererek sağ ön kolu sağ bacağın iç tarafına indirin, nefes alarak sol kolu kulak hizasından sağ ayağa doğru uzatın.","kalis":"Göğüs tavana döner, üst kol kulağın yanında uzanır, iki oturma kemiği yerde kalır. 5–8 nefes kalın; nefes alışta üst kaburgalara alan açın.","cikis":"Nefes alarak üst kolu yukarı uzatıp gövdeyi dikleştirin, nefes vererek kolu indirin ve taraf değiştirin."},"hata":{"ne":"Göğsü yere çevirip pozu öne eğilmeye dönüştürmek.","neden":"Yan hat ve hamstringler gerildikçe gövde kolay yol olan öne katlanmaya kayar.","yonlendirme":"Üst omuz geriye, göğüs tavana."},"soylenecekler":["Alttaki ön kolunuz bacağınızın iç tarafına yaslansın.","Üst kolunuzu omzunuzdan değil, kaburgalarınızdan uzatın.","Bükülü dizin tarafındaki oturma kemiğinizi yere bastırın."],"eller":{"nereye":"Üstteki omzun arkası ve bükülü bacak tarafındaki kalça kemiği.","nasil":"Kalçayı yere sabitlerken omzu hafifçe geriye açın; derinleştirmek için aşağı bastırmayın.","ne_zaman_degil":"Omuz ya da boyun ağrısında, diz sorununda veya onay yoksa."},"kolay":"Battaniyeye oturun, alttaki eli bir bloğa koyun ve üst eli belde tutun.","zor":"Üst elle uzanan ayağın dış kenarını, alt elle iç kenarını tutun ve göğsü tavana çevirin.","dikkat":"Boyun hassasiyetinde bakışı yere ya da öne verin; omuz ağrısında üst eli belde tutun. Ağrı sürerse öğrencinin doktoruna ya da fizyoterapistine danışmasını önerin.","s":52,"fig":false},{"n":46,"bolum":3,"ad":"Tavşan (Sasangasana)","aile":"Öne eğilme","seviye":"Orta","yogunluk":[3,5,6],"calisan":["Rektus abdominis","Oblikler","Orta ve alt trapezius"],"dengeleyen":["Rhomboidler","Transversus abdominis"],"uzayan":["Erector spinae","Multifidus","Üst trapezius"],"ozet":"Başın tepesi yerdeyken omurgayı tam fleksiyona getirmeyi öğretir; sırtın arka tarafını omur omur açar ve baş aşağı pozlara yumuşak bir giriş olabilir.","asamalar":{"giris":"Topuklarınızın üstünde oturun ve topukları ellerinizle kavrayın. Nefes vererek çeneyi göğse yaklaştırın, alnı dizlerin önüne, başın tepesini yere koyun.","kalis":"Alın dizlere yakın, ağırlığın çoğu dizlerde ve kollarda, başta değil. Nefes alarak kalçaları kaldırın ve sırtı yuvarlayın; 3–5 nefes kalın.","cikis":"Nefes vererek kalçaları topuklara indirin, alnı yere koyup çocuk pozunda biraz kalın, sonra yavaşça doğrulun."},"hata":{"ne":"Ağırlığı başın tepesine yüklemek.","neden":"Kollar topukları yeterince çekmediğinde gövdenin ağırlığı boyun omurlarına aktarılır.","yonlendirme":"Baş yere değer, ağırlık kollarda."},"soylenecekler":["Topuklarınızı sıkıca kavrayın.","Alnınız dizlerinize olabildiğince yakın olsun.","Boynunuzda baskı hissederseniz kalçalarınızı indirin."],"eller":{"nereye":"Sakrum ve kalçaların üstü.","nasil":"Kalçaların yükselişini hafifçe yönlendirin; ağırlığı başa doğru asla itmeyin.","ne_zaman_degil":"Boyun sorununda, yüksek tansiyonda, baş dönmesinde, hamilelikte ya da onay yoksa."},"kolay":"Başın altına katlanmış battaniye koyun ve kalçaları yarı yükseklikte tutun.","zor":"Kalçaları tam yükseltin, kolları düz tutup topukları çekerek omurgayı daha da yuvarlayın.","dikkat":"Boyun sorunu, yüksek tansiyon, glokom ya da baş dönmesi bildiren öğrencide başın yere yüklenmediği çocuk pozunu önerin; hamilelikte uygulamayın. Şikâyet varsa öğrencinin doktoruna ya da fizyoterapistine danışmasını önerin.","s":53,"fig":false},{"n":47,"bolum":4,"ad":"Kedi ve inek (Marjaryasana-Bitilasana)","aile":"Geriye eğilme","seviye":"Başlangıç","yogunluk":[1,2,3],"calisan":["Erector spinae","Rektus abdominis","Serratus anterior"],"dengeleyen":["Transversus abdominis","Deltoid","Rotator manşet"],"uzayan":["Rektus abdominis","Erector spinae"],"ozet":"Omurgayı nefesle eşzamanlı olarak fleksiyon ve ekstansiyon arasında hareket ettirmeyi öğretir; dersin başında sırtı ısıtmak ve nefes-hareket bağlantısını kurmak için idealdir.","asamalar":{"giris":"Bilekler omuzların, dizler kalçaların altında dört ayak pozisyonuna gelin. Nefes alarak pelvisi öne devirip göğsü açın (inek), nefes vererek kuyruk sokumunu içeri alıp sırtı yuvarlayın (kedi).","kalis":"Hareket pelvisten başlar ve omur omur başa ulaşır; eller ve dizler sabit kalır. Nefesin hızında 5–10 tur yapın.","cikis":"Omurgayı nötr, düz bir sırta getirin, birkaç nefes kalın ve kalçaları topuklara indirip dinlenin."},"hata":{"ne":"Hareketi yalnızca başla ve boyunla yapmak.","neden":"Göğüs omurgası sert olduğunda en hareketli bölgeler olan boyun ve bel hareketi üstlenir.","yonlendirme":"Kuyruk sokumu başlatır, baş en son gelir."},"soylenecekler":["Nefes alın, göğüs öne; nefes verin, göbek omurgaya.","Kedi pozunda kürek kemiklerinizin arasını genişletin.","Nefesinizin hızında hareket edin, nefesi beklemeyin."],"eller":{"nereye":"Kürek kemiklerinin arası ve sakrum.","nasil":"İki eli hafifçe koyarak öğrencinin hareketi hangi bölgeden başlattığını hissetmesine yardım edin; yönlendirin ama hareket ettirmeyin.","ne_zaman_degil":"Bilek ya da diz ağrısında, hamileliğin ileri döneminde ya da onay yoksa."},"kolay":"Dizlerin altına katlanmış battaniye koyun; bilek hassasiyetinde ön kollara inin ya da sandalyede oturarak yapın.","zor":"Pelvise daireler çizdirerek omurgayı yana ve dairesel hareketlerle keşfedin.","dikkat":"Bilek ağrısında yumruk ya da ön kol varyasyonunu önerin; bel hassasiyetinde inek fazını küçük tutun. Hamilelikte inek fazında karnı aşağı sarkıtmayın. Ağrı varsa öğrencinin doktoruna ya da fizyoterapistine danışmasını önerin.","s":55,"fig":true},{"n":48,"bolum":4,"ad":"Sfenks (Salamba Bhujangasana)","aile":"Geriye eğilme","seviye":"Başlangıç","yogunluk":[1,3,4],"calisan":["Erector spinae","Orta ve alt trapezius","Serratus anterior"],"dengeleyen":["Gluteus maximus","Transversus abdominis"],"uzayan":["Rektus abdominis","İliopsoas","Büyük ve küçük pektoral"],"ozet":"Ön kolların desteğiyle düşük yoğunluklu bir sırt ekstansiyonu öğretir; geriye eğilmelere hazırlık ya da yin dersinde uzun tutuş için uygundur.","asamalar":{"giris":"Yüzüstü uzanın, dirsekleri omuzların altına, ön kolları paralel olarak öne koyun. Nefes alarak göğsü ileri ve yukarı kaydırın; kasık yerde kalsın.","kalis":"Dirsekler omuz altında, omuzlar kulaklardan uzak, ense uzun; bacaklar kalça genişliğinde ve gevşek. 5–10 nefes, yin tarzında 2–3 dakika kalın.","cikis":"Nefes vererek göğsü indirin, alnı kollarınızın üstüne koyun ve kalçaları hafifçe sağa sola sallayın."},"hata":{"ne":"Omuzları kulaklara doğru çöktürmek.","neden":"Serratus anterior aktif olmadığında gövde kürek kemiklerinin arasına düşer.","yonlendirme":"Ön kollarla yere bastırın, göğüs öne."},"soylenecekler":["Ön kollarınızı mata bastırın ve göğsünüzü ileri çekin.","Kasığınız yerde, kalçalarınız yumuşak.","Belde sıkışma varsa dirseklerinizi biraz öne alın."],"eller":{"nereye":"Kürek kemiklerinin alt uçları.","nasil":"Kürek kemiklerini hafifçe aşağı, bele doğru yönlendirin; göğsü yukarı çekmeyin.","ne_zaman_degil":"Bel ağrısı bildirildiğinde, hamilelikte ya da onay yoksa."},"kolay":"Dirsekleri omuzların biraz önüne koyun ya da göğsün altına katlanmış battaniye yerleştirin.","zor":"Ön kollarla aktif bastırıp göğsü daha ileri taşıyın ve bacakları yerden hafifçe kaldırın.","dikkat":"Bel hassasiyetinde yüksekliği azaltın ve dirsekleri öne alın; hamilelikte yüzüstü pozlar yerine dört ayakta bir göğüs açma önerin. Ağrı varsa öğrencinin doktoruna ya da fizyoterapistine danışmasını önerin.","s":56,"fig":false},{"n":49,"bolum":4,"ad":"Kobra (Bhujangasana)","aile":"Geriye eğilme","seviye":"Başlangıç","yogunluk":[2,4,5],"calisan":["Erector spinae","Gluteus maximus","Orta ve alt trapezius"],"dengeleyen":["Hamstringler","Transversus abdominis"],"uzayan":["Rektus abdominis","Büyük ve küçük pektoral","İliopsoas"],"ozet":"Göğsü kolların değil sırt kaslarının gücüyle kaldırmayı öğretir; güneşe selamda yukarı bakan köpeğin daha kontrollü alternatifidir.","asamalar":{"giris":"Yüzüstü uzanın, elleri omuzların altına koyun, dirsekler gövdeye yakın olsun. Ayak üstlerini yere bastırın ve nefes alarak göğsü sırt kaslarıyla kaldırın.","kalis":"Kasık yerde, dirsekler hafif bükülü ve geride, omuzlar aşağıda. Ense uzun, bakış ileride; 3–5 nefes kalın.","cikis":"Nefes vererek göğsü yavaşça yere indirin, alnı yere koyun ve bir nefes dinlenin."},"hata":{"ne":"Kollarla itip bel bölgesini ezmek.","neden":"Sırt kasları yeterince devreye girmediğinde gövdeyi kollar kaldırır ve ekstansiyon en hareketli bölge olan bel omurlarında toplanır.","yonlendirme":"Göğüs ellerle değil, sırtla yükselir."},"soylenecekler":["Ellerinizi bir an yerden kaldırın; ne kadar yükselebiliyorsanız kobranız o kadar.","Ayak üstlerinizi, özellikle küçük parmak tarafını yere bastırın.","Dirsekleriniz geriye, kaburgalarınıza doğru."],"eller":{"nereye":"Kürek kemiklerinin alt uçları ve sakrum.","nasil":"Kürek kemiklerini aşağıya, sakrumu topuklara doğru hafifçe yönlendirerek belde uzunluk yaratın.","ne_zaman_degil":"Bel ağrısı bildirildiğinde, hamilelikte ya da onay yoksa."},"kolay":"Alçak kobra: elleri hafifçe yerden kaldırıp yalnızca sırt kaslarıyla göğsü birkaç santim yükseltin.","zor":"Elleri biraz daha öne alın ve kasık yerde kalacak şekilde göğsü daha yukarı taşıyın.","dikkat":"Bel ağrısı bildiren öğrencide alçak kobrada kalın; bilek hassasiyetinde ellere verilen ağırlığı azaltın. Hamilelikte yüzüstü yerine dört ayakta göğüs açma önerin. Ağrı varsa öğrencinin doktoruna ya da fizyoterapistine danışmasını önerin.","s":57,"fig":true},{"n":50,"bolum":4,"ad":"Yukarı bakan köpek (Urdhva Mukha Svanasana)","aile":"Geriye eğilme","seviye":"Orta","yogunluk":[4,5,6],"calisan":["Triceps brachii","Erector spinae","Kuadriseps","Serratus anterior"],"dengeleyen":["Gluteus maximus","Rotator manşet"],"uzayan":["Rektus abdominis","İliopsoas","Büyük ve küçük pektoral"],"ozet":"Yalnızca eller ve ayak üstleri yerdeyken göğsü kolların arasından öne açmayı öğretir; vinyasa akışının ana geriye eğilmesidir ve güçlü kollar ile aktif bacaklar ister.","asamalar":{"giris":"Yüzüstü pozisyondan ya da Chaturanga'dan eller bel hizasında. Nefes alarak kolları düzleyin, ayak üstlerine geçin ve uylukları yerden kaldırın.","kalis":"Bilekler omuzların altında, uyluklar havada, kuadriseps aktif; göğüs kolların arasından öne, omuzlar geride ve aşağıda. 1–3 nefes kalın.","cikis":"Nefes vererek kalçaları geri ve yukarı kaldırın, ayak parmaklarının üstünden aşağı bakan köpeğe geçin ya da dizleri yere indirin."},"hata":{"ne":"Omuzları kulaklara gömüp kollarda asılı kalmak.","neden":"Serratus anterior ve alt trapezius aktif olmadığında gövde omuz kuşağının arasına düşer.","yonlendirme":"Yeri itin, göğüs kolların arasından öne."},"soylenecekler":["Uyluklarınız yerden kalksın, bacaklarınız uyanık.","Avuçlarınızla yeri geriye doğru sürükler gibi bastırın.","Kısa kalın; bir nefes yeterli."],"eller":{"nereye":"Öğrencinin önünde durarak iki omuz başı.","nasil":"Omuzları hafifçe geriye ve aşağı yönlendirin; gövdeyi yukarı çekmeyin.","ne_zaman_degil":"Bilek, omuz ya da bel ağrısında, hamilelikte ya da onay yoksa."},"kolay":"Kobrada kalın ya da dizleri yerde bırakarak yarım yukarı bakan köpek yapın.","zor":"Kalış süresini 5 nefese uzatın ve her nefes verişte bacakları daha aktif tutarak göğsü öne taşıyın.","dikkat":"Bilek, omuz ya da bel ağrısı bildiren öğrencide kobra önerin; hamilelikte uygulamayın. Ağrı sürerse öğrencinin doktoruna ya da fizyoterapistine danışmasını önerin.","s":58,"fig":false},{"n":51,"bolum":4,"ad":"Çekirge (Salabhasana)","aile":"Geriye eğilme","seviye":"Başlangıç","yogunluk":[3,5,6],"calisan":["Erector spinae","Gluteus maximus","Hamstringler","Orta ve alt trapezius"],"dengeleyen":["Multifidus","Addüktörler"],"uzayan":["Rektus abdominis","Büyük ve küçük pektoral"],"ozet":"Hiç kol desteği olmadan sırtın arka zincirini güçlendirmeyi öğretir; daha derin geriye eğilmelerden önce sırt kaslarını uyandırmak için kullanılır.","asamalar":{"giris":"Yüzüstü uzanın, kollar bedenin yanında, avuçlar yere dönük. Nefes alarak göğsü, kolları ve bacakları aynı anda yerden kaldırın.","kalis":"Kasık ve alt karın yerde, bacaklar uzun ve kalça genişliğinde, ense omurganın devamı; bakış yere çapraz. 3–5 nefes kalın, 2–3 tekrar yapın.","cikis":"Nefes vererek önce bacakları, sonra göğsü yavaşça yere indirin; başı bir yana çevirip kalçaları sallayarak gevşeyin."},"hata":{"ne":"Yükseklik için başı geriye atıp boynu sıkıştırmak.","neden":"Sırt kasları yeterince güçlü değilse kaldırma hareketi boyun ekstansiyonuyla telafi edilir.","yonlendirme":"Ense uzun, bakış yere çapraz."},"soylenecekler":["Yükseklik değil, uzunluk arıyoruz.","Ayak parmaklarınızla arka duvara uzanın.","Kürek kemiklerinizi birbirine ve aşağıya yaklaştırın."],"eller":{"nereye":"Bileklerin üstü ya da topukların arkası.","nasil":"Uzanma yönünü hissettirmek için bilekleri ya da topukları hafifçe geriye doğru çekin; yukarı kaldırmayın.","ne_zaman_degil":"Bel ağrısında, hamilelikte ya da onay yoksa."},"kolay":"Yalnızca göğsü ya da yalnızca bir bacağı kaldırın; kasığın altına katlanmış battaniye koyun.","zor":"Elleri arkada kenetleyip kolları sırttan uzaklaştırın ya da kolları öne uzatarak süpermen varyasyonunu yapın.","dikkat":"Bel ağrısı bildiren öğrencide tek bacak ya da yalnızca göğüs varyasyonunu önerin; hamilelikte yüzüstü pozları uygulamayın. Ağrı varsa öğrencinin doktoruna ya da fizyoterapistine danışmasını önerin.","s":59,"fig":false},{"n":52,"bolum":4,"ad":"Yay (Dhanurasana)","aile":"Geriye eğilme","seviye":"Orta","yogunluk":[5,6,8],"calisan":["Kuadriseps","Gluteus maximus","Erector spinae","Hamstringler"],"dengeleyen":["Rotator manşet","Rhomboidler"],"uzayan":["Büyük ve küçük pektoral","Rektus abdominis","İliopsoas"],"ozet":"Bacakların ellere geriye doğru bastırmasıyla bütün bedeni bir yay gibi açmayı öğretir; kolları pasif bırakıp gücü bacaklardan üretmeyi gösterir.","asamalar":{"giris":"Yüzüstü uzanın, dizleri bükün ve elleri ayak bileklerinin dış tarafına götürün. Nefes alarak ayakları ellere doğru geriye bastırın; göğüs ve uyluklar yerden kalksın.","kalis":"Dizler kalça genişliğini aşmaz, kollar düz ve gevşek, ağırlık karın üzerindedir. Nefes karında kısıtlanır, sakin kalın; 3–5 nefes.","cikis":"Nefes vererek uylukları ve göğsü yere indirin, ayak bileklerini bırakın, bacakları uzatıp alnı ellerin üstüne koyun."},"hata":{"ne":"Kollarla ayakları çekip dizleri yanlara açmak.","neden":"Güç bacakların itmesinden değil kolların çekmesinden gelince omuzlar öne çekilir ve dizlerin hizası kaybolur.","yonlendirme":"Ayaklar ellere bastırır, eller çekmez."},"soylenecekler":["Ayaklarınızla ellerinize doğru geriye tekme atın.","Dizleriniz kalça genişliğinde kalsın.","Nefes kısa gelirse yüksekliği azaltın."],"eller":{"nereye":"Diz kapaklarının hemen üstü, uyluğun dış yanları.","nasil":"Dizlerin kalça genişliğinde kalmasına yardım etmek için iki yandan hafifçe içeri yönlendirin; yukarı kaldırmayın.","ne_zaman_degil":"Bel ya da diz ağrısında, hamilelikte, yemekten hemen sonra ya da onay yoksa."},"kolay":"Ayak bileklerine kayış dolayıp kayıştan tutun ya da tek bacaklı yarım yay yapın.","zor":"Ellerinizi ters tutuşa (başparmaklar dışa) çevirin ve dirsekleri yukarı yönlendirin.","dikkat":"Bel ya da diz ağrısı bildiren öğrencide yarım yay ya da çekirge önerin; hamilelikte uygulamayın. Ağrı sürerse öğrencinin doktoruna ya da fizyoterapistine danışmasını önerin.","s":60,"fig":false},{"n":53,"bolum":4,"ad":"Köprü (Setu Bandha Sarvangasana)","aile":"Geriye eğilme","seviye":"Orta","yogunluk":[3,5,7],"calisan":["Gluteus maximus","Hamstringler","Erector spinae"],"dengeleyen":["Addüktörler","Transversus abdominis"],"uzayan":["İliopsoas","Kuadriseps","Büyük ve küçük pektoral"],"ozet":"Ayaklarla yere basarak pelvisi kaldırmayı ve kalça ekstansiyonunu gluteuslarla üretmeyi öğretir; çark öncesi hazırlık olarak ya da destekli hâliyle restoratif olarak kullanılır.","asamalar":{"giris":"Sırtüstü uzanın, dizleri bükün, ayaklar kalça genişliğinde ve topuklar parmak uçlarına yakın olsun. Nefes alarak ayaklarla yere basın ve pelvisi omur omur kaldırın.","kalis":"Dizler kalça genişliğinde ve ayak bileklerinin üstünde; ağırlık omuzlarda ve ayaklarda, boyunda değil. Baş düz kalır; 5–8 nefes kalın.","cikis":"Nefes vererek omurgayı üst sırttan başlayarak omur omur yere indirin; en son sakrum yere değsin."},"hata":{"ne":"Pelvis yükselirken dizler açılır.","neden":"Addüktörler devreye girmediğinde ve kalçanın dış rotatörleri baskın çalıştığında dizler yükselişte dışa kaçar.","yonlendirme":"Dizler kalça genişliğinde."},"soylenecekler":["Ayak tabanlarınızın dört köşesiyle yere basın.","Başınızı çevirmeyin; bakışınız tavanda.","Dizlerinizin arasında bir blok tutuyormuş gibi hissedin."],"eller":{"nereye":"Dizlerin dış tarafı ya da destek için sakrumun altı.","nasil":"Dizleri hafifçe birbirine doğru yönlendirin; pelvisi yukarı çekmeyin.","ne_zaman_degil":"Boyun ağrısında, hamileliğin ileri döneminde ya da onay yoksa."},"kolay":"Sakrumun altına blok koyup destekli köprüde dinlenin.","zor":"Tek bacaklı köprü: pelvis seviyesini koruyarak bir bacağı tavana uzatın.","dikkat":"Boyun hassasiyetinde omuzların altına katlanmış battaniye koyun ve başı çevirmeyin; diz ağrısında topukları biraz uzaklaştırın. Ağrı varsa öğrencinin doktoruna ya da fizyoterapistine danışmasını önerin.","s":61,"fig":true},{"n":54,"bolum":4,"ad":"Çark (Urdhva Dhanurasana)","aile":"Geriye eğilme","seviye":"İleri","yogunluk":[6,8,9],"calisan":["Triceps brachii","Gluteus maximus","Erector spinae","Deltoid"],"dengeleyen":["Rotator manşet","Serratus anterior","Addüktörler"],"uzayan":["Büyük ve küçük pektoral","Rektus abdominis","İliopsoas"],"ozet":"Eller ve ayaklarla yere basarak bütün ön hattı açan tam geriye eğilmedir; omuz esnekliği, kalça ekstansiyonu ve kol gücünü birlikte gerektirdiği için dersin zirvesinde, yeterli ısınmadan sonra öğretilir.","asamalar":{"giris":"Sırtüstü, dizler bükülü, ayaklar kalça genişliğinde; elleri parmaklar omuzlara bakacak şekilde kulakların yanına koyun. Nefes alarak önce pelvisi kaldırıp başın tepesine gelin, bir nefes daha alarak kolları düzleyin.","kalis":"Ayaklar paralel, dizler kalça genişliğinde, dirsekler omuz genişliğinde; ağırlık eller ve ayaklar arasında paylaşılır. 3–5 nefes kalın.","cikis":"Çeneyi göğse yaklaştırın, nefes vererek dirsekleri bükün ve önce üst sırtı, sonra pelvisi omur omur yere indirin; dizleri göğse çekin."},"hata":{"ne":"Dirsekleri yanlara açıp başın tepesinde kalmak.","neden":"Omuz fleksiyonu ve triceps gücü yetersiz olduğunda dirsekler dışa kaçar ve kollar düzlenemez.","yonlendirme":"Dirsekler paralel, göğüs arka duvara."},"soylenecekler":["Önce başınızın tepesine gelin, dirsekleri paralel tutun, sonra itin.","Ayaklarınız paralel; ayak parmaklarınız dışa kaçmasın.","Göğsünüzü ellerinizin arasından arka duvara gönderin."],"eller":{"nereye":"Öğrencinin baş tarafında durarak kürek kemiklerinin altı.","nasil":"Yalnızca öğrenci istediğinde ve hazırlık pozlarını yaptıysa kürek kemiklerinin altını hafifçe yukarı yönlendirin; asla bütün ağırlığı kaldırmayın.","ne_zaman_degil":"Bilek, omuz, bel ya da boyun ağrısında, hamilelikte, öğrenci başının tepesinde dengesizse ya da onay yoksa."},"kolay":"Köprüde kalın ya da elleri duvara dayalı iki bloğa koyarak çark çalışın.","zor":"Ayakları ellere doğru yürütün ya da pelvis seviyesini koruyarak bir bacağı tavana uzatın.","dikkat":"Bilek, omuz, bel ya da boyun ağrısı bildiren öğrencide köprü önerin; yüksek tansiyonda ve hamilelikte uygulamayın. Ağrı sürerse öğrencinin doktoruna ya da fizyoterapistine danışmasını önerin.","s":62,"fig":false},{"n":55,"bolum":4,"ad":"Deve (Ustrasana)","aile":"Geriye eğilme","seviye":"Orta","yogunluk":[5,6,8],"calisan":["Gluteus maximus","Erector spinae","Hamstringler"],"dengeleyen":["Rektus abdominis","Addüktörler"],"uzayan":["Kuadriseps","İliopsoas","Büyük ve küçük pektoral"],"ozet":"Dizler üzerindeyken kalçalar öne kalarak göğsü geriye açmayı öğretir; ön uyluklar ve göğüs için güçlü bir açılım sunar ve kademeli bir girişle öğretilmelidir.","asamalar":{"giris":"Dizler kalça genişliğinde, kalçalar dizlerin üstünde; elleri sakruma koyun. Nefes alarak göğüs kemiğini yükseltin, nefes vererek elleri birer birer topuklara indirin.","kalis":"Kalçalar dizlerin üstünde kalır, göğüs yukarı, bel uzun; boyun nötr ya da hafifçe geride. 3–5 nefes kalın.","cikis":"Elleri sakruma geri getirin, çeneyi göğse yaklaştırın ve nefes alarak göğüsle yükselin; ardından çocuk pozunda dinlenin."},"hata":{"ne":"Kalçaları topuklara doğru geri bırakmak.","neden":"İliopsoas ve kuadriseps kısa olduğunda pelvis geriye kaçar ve ekstansiyon bel omurlarına yığılır.","yonlendirme":"Kalçalar dizlerin üstünde, göğüs yukarı."},"soylenecekler":["Önce yukarı, sonra geriye.","Ellerinizi topuklara indirmek zorunda değilsiniz; sakrumda kalabilirler.","Başınızı geriye bırakmadan önce göğsünüz açılsın."],"eller":{"nereye":"Sakrum ve göğüs kafesinin arka alt kısmı.","nasil":"Öğrencinin arkasında durup kaburgaların arkasını hafifçe yukarı yönlendirin ve kalçaların öne kalmasına eşlik edin; aşağı itmeyin.","ne_zaman_degil":"Bel ya da boyun ağrısında, baş dönmesinde, hamilelikte ya da onay yoksa."},"kolay":"Ayak parmaklarını yere dikerek topukları yükseltin ya da topukların yanına bloklar koyun.","zor":"Ayak üstlerini yere düz koyun ve elleri topuklarda tutarken göğsü daha da yukarı taşıyın.","dikkat":"Bel ya da boyun ağrısı bildiren öğrencide eller belde hazırlıkta kalın; baş dönmesi olursa çıkışı yavaş yapın. Hamilelikte uygulamayın. Şikâyet sürerse öğrencinin doktoruna ya da fizyoterapistine danışmasını önerin.","s":63,"fig":false},{"n":56,"bolum":4,"ad":"Eller belde deve hazırlığı","aile":"Geriye eğilme","seviye":"Başlangıç","yogunluk":[2,4,5],"calisan":["Gluteus maximus","Erector spinae","Orta ve alt trapezius"],"dengeleyen":["Rektus abdominis","Transversus abdominis"],"uzayan":["Kuadriseps","İliopsoas"],"ozet":"Deve pozunun ilk aşamasıdır: eller belde, kalçalar önde, göğüs yukarıda; öğrenciye geriye eğilmeyi belden değil üst sırttan başlatmayı öğretir.","asamalar":{"giris":"Dizler kalça genişliğinde, kalçalar dizlerin üstünde. Elleri parmaklar aşağı bakacak şekilde sakruma koyun; nefes alarak dirsekleri birbirine yaklaştırıp göğsü yükseltin.","kalis":"Kalçalar önde, dizlerin üstünde; göğüs yukarı ve hafif geride, çene hafifçe içeride. Bel uzun kalır; 5 nefes kalın.","cikis":"Nefes vererek gövdeyi dik pozisyona getirin, elleri indirin ve kalçaları topuklara bırakın."},"hata":{"ne":"Göğsü kaldırmadan bel bölgesinden geriye kırılmak.","neden":"Göğüs omurgasının ekstansiyonu sınırlı olduğunda bükülme bel omurlarında toplanır.","yonlendirme":"Dirsekler birbirine, göğüs tavana."},"soylenecekler":["Ellerinizle sakrumu aşağı, kuyruk sokumuna doğru kaydırın.","Dirseklerinizi arkada birbirine yaklaştırın.","Burada kalmak da tam bir deve pozudur."],"eller":{"nereye":"Kürek kemiklerinin hemen altı.","nasil":"Avuçlarla üst sırtı hafifçe yukarı ve öne yönlendirerek göğsün açılmasına eşlik edin.","ne_zaman_degil":"Diz ya da bel ağrısında veya onay yoksa."},"kolay":"Dizlerin altına katlanmış battaniye koyun ve geriye eğilmeyi çok küçük tutun.","zor":"Bir kolu yukarı ve geriye uzatarak tek elle aynı taraftaki topuğa uzanın.","dikkat":"Diz hassasiyetinde dizlerin altına destek koyun; bel ağrısında hareketi yalnızca göğsü yükseltmekle sınırlayın. Ağrı varsa öğrencinin doktoruna ya da fizyoterapistine danışmasını önerin.","s":64,"fig":false},{"n":57,"bolum":4,"ad":"Balık (Matsyasana)","aile":"Geriye eğilme","seviye":"Başlangıç","yogunluk":[2,4,5],"calisan":["Erector spinae","Orta ve alt trapezius","Rhomboidler"],"dengeleyen":["Kuadriseps","Triceps brachii"],"uzayan":["Büyük ve küçük pektoral","Sternokleidomastoid","Rektus abdominis"],"ozet":"Sırtüstü pozisyonda göğüs kafesini yukarı açmayı öğretir; omuz duruşunun karşı pozu olarak ya da bloklarla destekli bir göğüs açılımı olarak kullanılır.","asamalar":{"giris":"Sırtüstü uzanın, elleri avuçlar aşağı bakacak şekilde kalçaların altına yerleştirin. Nefes alarak ön kollarla yere bastırın, göğsü yükseltin ve başın tepesini hafifçe yere bırakın.","kalis":"Ağırlık ön kollarda ve dirseklerde, başta çok az ağırlık var; bacaklar uzun ve aktif. 5 nefes kalın, nefes göğse dolsun.","cikis":"Ön kollarla bastırarak başı yerden kaldırın, çeneyi göğse yaklaştırın ve nefes vererek sırtı yavaşça yere indirin."},"hata":{"ne":"Bütün ağırlığı başa ve boyna vermek.","neden":"Ön kollar ve sırt kasları göğsü taşımadığında yük boyun omurlarına biner.","yonlendirme":"Göğüs yukarı, baş hafif."},"soylenecekler":["Dirseklerinizi yere bastırın ve göğsünüzü tavana açın.","Başınızın altında bir kâğıt varmış gibi, ona ağırlık vermeyin.","Boynunuzda baskı varsa başınızı bir bloğa koyun."],"eller":{"nereye":"Başın arkası ya da kürek kemiklerinin altındaki blok.","nasil":"Başın arkasını avuçla destekleyerek boyna binen yükü azaltın; göğsü yukarı çekmeyin.","ne_zaman_degil":"Boyun ağrısında, baş dönmesinde ya da onay yoksa."},"kolay":"Kürek kemiklerinin altına bir blok, başın altına bir blok koyarak destekli balık yapın.","zor":"Bacakları yerden 45 derece kaldırın ve kolları uyluklara paralel uzatın.","dikkat":"Boyun sorunu bildiren öğrencide başı destekleyin ya da başın yerde dinlendiği destekli varyasyonu önerin; yüksek tansiyonda ve baş dönmesinde dikkatli olun. Ağrı varsa öğrencinin doktoruna ya da fizyoterapistine danışmasını önerin.","s":65,"fig":false},{"n":58,"bolum":4,"ad":"Bloklarla deve","aile":"Geriye eğilme","seviye":"Başlangıç","yogunluk":[3,5,6],"calisan":["Gluteus maximus","Erector spinae","Triceps brachii"],"dengeleyen":["Rektus abdominis","Addüktörler"],"uzayan":["Kuadriseps","İliopsoas","Büyük ve küçük pektoral"],"ozet":"Topukların yanına yerleştirilen bloklar sayesinde deve pozunu daha kısa bir mesafeyle öğretir; kalçaları dizlerin üstünde tutmayı öğrenmenin en güvenli yoludur.","asamalar":{"giris":"Dizler kalça genişliğinde; iki bloğu en yüksek hâlinde ayak bileklerinin dış tarafına koyun. Elleri sakruma alın, nefes alarak göğsü yükseltin, nefes vererek elleri tek tek bloklara indirin.","kalis":"Kalçalar dizlerin üstünde, kollar düz ve blokları itiyor, göğüs yukarı; boyun nötr. 5 nefes kalın.","cikis":"Elleri tek tek sakruma geri getirin, nefes alarak göğüsle yükselin ve çocuk pozunda dinlenin."},"hata":{"ne":"Bloklara ulaşmak için kalçaları geriye oturtmak.","neden":"Ön uyluk ve kalça fleksörleri sınıra geldiğinde pelvis geriye kaçar.","yonlendirme":"Kalçalar ileride, bloklar size gelsin."},"soylenecekler":["Blokları ellerinizle itin, göğsünüz yükselsin.","Gerekirse blokları bir kat daha yükseltin.","Uyluklarınız yere dik kalsın."],"eller":{"nereye":"Uylukların önü, kalçaların hemen altı.","nasil":"Uylukları hafifçe öne yönlendirerek kalçaların dizlerin üstünde kalmasına yardım edin.","ne_zaman_degil":"Diz ya da bel ağrısında, hamilelikte ya da onay yoksa."},"kolay":"Blokları duvara dayayın ya da daha yüksek bir destek, örneğin sandalye kullanın.","zor":"Blokları en alçak seviyeye indirin ve zamanla bloksuz, topuklara geçin.","dikkat":"Diz ağrısında dizlerin altına battaniye koyun; bel ya da boyun ağrısında eller belde varyasyona dönün. Hamilelikte uygulamayın. Ağrı sürerse öğrencinin doktoruna ya da fizyoterapistine danışmasını önerin.","s":66,"fig":false},{"n":59,"bolum":4,"ad":"Camatkarasana, yan plank'tan","aile":"Geriye eğilme","seviye":"Orta","yogunluk":[4,6,7],"calisan":["Gluteus medius ve minimus","Gluteus maximus","Deltoid","Serratus anterior"],"dengeleyen":["Rotator manşet","Oblikler"],"uzayan":["Büyük ve küçük pektoral","İliopsoas","Kuadriseps"],"ozet":"Yan plank'tan bir ayağı geriye basarak göğsü tavana çevirmeyi öğretir; destek omzunun stabilitesini ön hattın açılımıyla birleştiren akıcı bir geriye eğilmedir.","asamalar":{"giris":"Sağ el üzerinde yan plank'a gelin. Nefes alarak üst bacağı dizden büküp ayağı alt bacağın arkasına basın ve kalçayı yükseltin.","kalis":"Destek eli omzun hafif önünde, parmaklar aktif; kalça yüksek, göğüs tavana açık, üst kol başın üstünden uzanır. 3–5 nefes kalın.","cikis":"Nefes vererek kalçayı indirin, üst eli yere getirin ve aşağı bakan köpeğe dönün; diğer tarafa geçin."},"hata":{"ne":"Destek omzuna çökmek.","neden":"Serratus anterior ve rotator manşet aktif değilse gövdenin ağırlığı omuz eklemine asılır.","yonlendirme":"Yeri itin, omuz kulaktan uzak."},"soylenecekler":["Avucunuzun tamamıyla, özellikle işaret parmağının köküyle yere basın.","Kalçanızı tavana kaldırın, göğsünüz kendiliğinden açılsın.","Üst kolunuz uzun bir yay çizsin."],"eller":{"nereye":"Kalça kemiğinin yanı.","nasil":"Kalçanın yükselişine eşlik etmek için hafifçe yukarı yönlendirin; omzun kontrolü öğrencide kalsın.","ne_zaman_degil":"Bilek ya da omuz ağrısında, omuz çıkığı öyküsünde, hamilelikte ya da onay yoksa."},"kolay":"Alt dizi yere koyup yarım yan plank'tan küçük bir göğüs açılımıyla başlayın.","zor":"Tek bacaklı aşağı bakan köpekten dönerek akışla girin ve pozdan çarka geçmeyi deneyin.","dikkat":"Bilek ya da omuz ağrısı, omuz çıkığı öyküsü bildiren öğrencide yarım yan plank varyasyonunu önerin; hamilelikte uygulamayın. Ağrı varsa öğrencinin doktoruna ya da fizyoterapistine danışmasını önerin.","s":67,"fig":false},{"n":60,"bolum":4,"ad":"Geriye uzanan alçak hamle","aile":"Geriye eğilme","seviye":"Başlangıç","yogunluk":[3,5,6],"calisan":["Kuadriseps","Gluteus maximus","Erector spinae"],"dengeleyen":["Gluteus medius ve minimus","Addüktörler","Transversus abdominis"],"uzayan":["İliopsoas","Kuadriseps","Rektus abdominis"],"ozet":"Alçak hamlede kolları yukarı uzatıp göğsü geriye açarak arka bacağın kalça fleksörlerini uzatmayı öğretir; derin geriye eğilmelerden önce iyi bir ısınmadır.","asamalar":{"giris":"Sağ ayak önde, sol diz yerde alçak hamleye gelin. Nefes alarak kolları yukarı uzatın, nefes vererek pelvisi hafifçe öne kaydırın ve göğsü geriye açın.","kalis":"Ön diz ayak bileğinin üstünde, arka uyluk uzun, alt karın hafif aktif; göğüs yukarı, bel uzun. 5 nefes kalın.","cikis":"Nefes vererek elleri ön ayağın iki yanına indirin, arka ayak parmaklarını dikip aşağı bakan köpeğe geçin; diğer tarafa geçin."},"hata":{"ne":"Göğsü açmadan belden geriye kırılmak.","neden":"Kalça fleksörleri kısa olduğunda pelvis öne devrilir ve geriye eğilme bel omurlarında yoğunlaşır.","yonlendirme":"Kuyruk sokumu aşağı, göğüs yukarı."},"soylenecekler":["Arka dizinizin altına battaniye koyabilirsiniz.","Kuyruk sokumunuzu yere doğru uzatın, kasığınızın önü açılsın.","Kollarınız yukarıda, ön kaburgalarınız içeride."],"eller":{"nereye":"Arka bacak tarafındaki kalça kemiğinin önü ve sakrum.","nasil":"Sakrumu hafifçe aşağı yönlendirirken kalça kemiğini öne çevirin; pelvisi öne itmeyin.","ne_zaman_degil":"Diz ya da bel ağrısında veya onay yoksa."},"kolay":"Elleri ön uyluğa ya da iki bloğa koyun ve göğsü yalnızca dikleştirin.","zor":"Arka dizi bükün ve arka ayağı aynı taraftaki elle tutarak ön uyluk uzamasını artırın.","dikkat":"Diz hassasiyetinde arka dizin altına destek koyun; bel ağrısı bildiren öğrencide geriye eğilmeyi küçük tutun ve elleri belde tutmasını önerin. Ağrı varsa öğrencinin doktoruna ya da fizyoterapistine danışmasını önerin.","s":68,"fig":false},{"n":61,"bolum":4,"ad":"Ters masa (Ardha Purvottanasana)","aile":"Geriye eğilme","seviye":"Başlangıç","yogunluk":[3,4,6],"calisan":["Gluteus maximus","Hamstringler","Triceps brachii","Orta ve alt trapezius"],"dengeleyen":["Rotator manşet","Rhomboidler","Kuadriseps"],"uzayan":["Büyük ve küçük pektoral","Deltoid","İliopsoas"],"ozet":"Eller ve ayaklar üzerinde pelvisi kaldırarak masa gibi düz bir gövde oluşturmayı öğretir; öne eğilmeler ve Chaturanga sonrası omuzların önünü açan bir karşı pozdur.","asamalar":{"giris":"Dizler bükülü oturun, elleri kalçaların arkasına parmaklar öne bakacak şekilde koyun. Nefes alarak ellere ve ayaklara basın ve pelvisi dizlerle aynı seviyeye kaldırın.","kalis":"Bilekler omuzların, dizler ayak bileklerinin üstünde; gövde yere paralel bir masa gibi. Ense uzun, baş nötr ya da hafif geride; 5 nefes kalın.","cikis":"Nefes vererek pelvisi yavaşça yere indirin, elleri bırakın ve bilekleri sallayarak gevşetin."},"hata":{"ne":"Kalçayı yükseltemeyip pelvisi aşağı sarkıtmak.","neden":"Gluteus maximus aktif olmadığında kalça ekstansiyonu tamamlanmaz ve yük omuzlara biner.","yonlendirme":"Kalçaları sıkın, göbek tavana."},"soylenecekler":["Ayak tabanlarınızla yere basın.","Göğsünüzü çenenize doğru kaldırın.","Boynunuzda rahatsızlık varsa çenenizi hafifçe içeride tutun."],"eller":{"nereye":"Sakrumun altı.","nasil":"Avuçla sakrumu hafifçe yukarı destekleyerek pelvisin olması gereken seviyeyi gösterin; kaldırmayın.","ne_zaman_degil":"Bilek ya da omuz ağrısında, boyun sorunlarında ya da onay yoksa."},"kolay":"Parmakları yanlara çevirin ya da yumruklar üzerinde destek alın ve kısa süre kalın.","zor":"Bir bacağı yere paralel uzatarak tek bacaklı ters masa yapın.","dikkat":"Bilek ya da omuz ağrısı bildiren öğrencide kısa tutuş ya da köprü önerin; boyun hassasiyetinde başı geriye bırakmayın. Ağrı varsa öğrencinin doktoruna ya da fizyoterapistine danışmasını önerin.","s":69,"fig":false},{"n":62,"bolum":4,"ad":"Ters plank (Purvottanasana)","aile":"Geriye eğilme","seviye":"Orta","yogunluk":[4,6,7],"calisan":["Gluteus maximus","Hamstringler","Triceps brachii","Kuadriseps"],"dengeleyen":["Rotator manşet","Orta ve alt trapezius","Addüktörler"],"uzayan":["Büyük ve küçük pektoral","Deltoid","Tibialis anterior"],"ozet":"Bacaklar düz, ayak tabanları yere uzanırken bütün ön hattı tek bir çizgide kaldırmayı öğretir; oturarak öne eğilmenin doğal karşı pozudur.","asamalar":{"giris":"Bacaklar önde uzanmış oturun, elleri kalçaların arkasına parmaklar ayaklara bakacak şekilde koyun. Nefes alarak ellere ve topuklara basın ve pelvisi yukarı kaldırın.","kalis":"Bilekler omuzların altında, bacaklar düz ve birleşik, ayak tabanları yere doğru; kalçalar omuzlarla aynı çizgide. 3–5 nefes kalın.","cikis":"Nefes vererek pelvisi yavaşça yere indirin ve kısa bir oturarak öne eğilmeyle sırtı dengeleyin."},"hata":{"ne":"Kalçaları düşürüp gövdeyi bir V harfi gibi bükmek.","neden":"Gluteuslar ve hamstringler kalçayı tam ekstansiyonda tutamadığında pelvis aşağı sarkar.","yonlendirme":"Ayak tabanları yere, göbek tavana."},"soylenecekler":["Ayak tabanlarınızı mata doğru uzatın.","Kalçalarınızı omuzlarınızla aynı çizgiye getirin.","Ellerinizle yeri itin, göğsünüz açılsın."],"eller":{"nereye":"Sakrumun altı ve omuz başlarının önü.","nasil":"Sakrumu hafifçe yukarı destekleyin, omuzları geriye yönlendirin; ağırlığı siz taşımayın.","ne_zaman_degil":"Bilek, omuz ya da boyun sorunlarında, hamilelikte ya da onay yoksa."},"kolay":"Ters masa ile başlayın ya da ellerin altına bloklar koyun.","zor":"Pelvis seviyesini koruyarak bir bacağı tavana kaldırın.","dikkat":"Bilek ya da omuz ağrısı bildiren öğrencide ters masa önerin; boyun sorunlarında başı geriye bırakmayın, çene içeride kalsın. Ağrı sürerse öğrencinin doktoruna ya da fizyoterapistine danışmasını önerin.","s":70,"fig":false},{"n":63,"bolum":5,"ad":"Oturarak burgu (Ardha Matsyendrasana)","aile":"Burgu","seviye":"Başlangıç","yogunluk":[2,4,5],"calisan":["Oblikler","Multifidus"],"dengeleyen":["Erector spinae","Transversus abdominis"],"uzayan":["Piriformis","Gluteus medius ve minimus"],"ozet":"Oturarak yapılan klasik burgu; omurganın önce uzayıp sonra dönmesini öğretir. Derste öne eğilmelerden sonra sırtı nötrlemek için iyi bir geçiştir.","asamalar":{"giris":"Sağ ayağı sol dizin dışına basın, iki oturma kemiğini yere yerleştirin. Nefes alarak omurgayı tepeye doğru uzatın, nefes vererek göbekten başlayarak sağa dönün.","kalis":"Pelvis sabit ve iki oturma kemiği eşit ağırlıkta kalsın; her nefes alışta biraz uzayın, her verişte burguyu koruyun. 5–8 nefes kalın.","cikis":"Nefes alarak önce başı, sonra göğsü ve en son göbeği merkeze getirin; bacakları uzatıp diğer tarafa geçmeden önce bir nefes dinlenin."},"hata":{"ne":"Kolu kaldıraç yapıp burguyu zorlamak.","neden":"Kol dizi ittiğinde dönüş göğüs kafesinden değil omuzdan gelir ve bel omurlarına, dönmeye en az uygun bölgeye fazla yük biner.","yonlendirme":"Önce uzayın, sonra dönün."},"soylenecekler":["Oturma kemiklerinizi yere köklendirin, başınızın tepesini tavana uzatın.","Dönüş göbekten başlasın, göğüs takip etsin, baş en son gelsin.","Kolunuz sadece burguyu tutsun; sizi döndürmesin."],"eller":{"nereye":"Bir el kürek kemikleri arasında omurganın arkasına, diğer el dönülen taraftaki omzun önüne.","nasil":"Arkadaki elle yukarı doğru hafif bir uzama yönü verin, öndeki elle omzu sadece açılmaya davet edin; dönüşü siz derinleştirmeyin.","ne_zaman_degil":"Öğrenci izin vermediyse, belde ya da sırtta ağrı tarif ediyorsa veya hamileyse dokunmayın."},"kolay":"Altta kalan bacağı uzatın ve oturma kemiklerinin altına katlanmış battaniye koyun; kol dizi kucaklasın.","zor":"Alttaki kolu dizin dışından geçirip arkadan uzanan elle bağlayın (yarı bağlı burgu); göğsü açık tutun.","dikkat":"Bel fıtığı öyküsü, yakın zamanda karın ameliyatı ya da hamilelikte burguyu sığ tutun veya açık burguya geçin; ağrı varsa öğrencinin doktoruna ya da fizyoterapistine danışmasını önerin.","s":72,"fig":true},{"n":64,"bolum":5,"ad":"Basit oturarak burgu","aile":"Burgu","seviye":"Başlangıç","yogunluk":[1,3,4],"calisan":["Oblikler","Multifidus"],"dengeleyen":["Erector spinae","Diyafram"],"uzayan":["Rhomboidler","Quadratus lumborum"],"ozet":"Bağdaş oturuşta yapılan en sade burgu; yeni öğrencilere dönüşün göğüs kafesinden geldiğini hissettirmek için idealdir. Ders açılışında ısınma olarak kullanılabilir.","asamalar":{"giris":"Bağdaş kurun, sağ eli sol dizin üstüne, sol eli arkada yere koyun. Nefes alarak omurgayı uzatın, nefes vererek sola doğru yavaşça dönün.","kalis":"Omuzlar kulaklardan uzak, çene yere paralel kalsın; nefes alırken göğüs kafesini yanlara genişletin. Her yönde 5 nefes kalın.","cikis":"Nefes alarak merkeze dönün, bacakların çaprazını değiştirin ve diğer tarafı tekrarlayın."},"hata":{"ne":"Çeneyle dönmeye çalışıp boynu zorlamak.","neden":"Göğüs kafesi hareket etmediğinde dönüş en esnek bölge olan boyna kayar ve boyun kasları gerilir.","yonlendirme":"Göğsünüz dönsün, baş sadece eşlik etsin."},"soylenecekler":["Kendinizi biraz daha uzun hissedene kadar bekleyin, sonra dönün.","Nefes alırken kaburgalarınızı yanlara açın.","Bakışınız yumuşak, çeneniz rahat."],"eller":{"nereye":"Öğrencinin arkasında durarak iki el iki omzun üstünde, ya da tek el dönülen taraftaki kürek kemiğinin üstünde.","nasil":"Omuzları aşağı ve geniş tutmaya yönlendiren hafif bir dokunuş yeterli; döndürme yönünde baskı uygulamayın.","ne_zaman_degil":"İzin yoksa, öğrenci boyunda ağrı belirtiyorsa veya baş dönmesi yaşıyorsa dokunmayın."},"kolay":"Oturma kemiklerinin altına blok ya da battaniye koyun; sırtı duvara yaslayarak dönün.","zor":"Elleri başın arkasında birleştirip dirsekleri açık tutarak kol desteği olmadan dönün.","dikkat":"Boyun hassasiyeti olan öğrencilerde başı merkezde bırakın; ağrı varsa öğrencinin doktoruna ya da fizyoterapistine danışmasını önerin.","s":73,"fig":false},{"n":65,"bolum":5,"ad":"Marichi pozu (Marichyasana III)","aile":"Burgu","seviye":"Orta","yogunluk":[3,5,7],"calisan":["Oblikler","Multifidus","Rotator manşet"],"dengeleyen":["Erector spinae","Transversus abdominis"],"uzayan":["Gluteus maximus","Büyük ve küçük pektoral"],"ozet":"Bir bacak uzun, diğer diz bükülü oturarak yapılan derin burgu. Kalça ile göğüs kafesi arasındaki ayrışmayı ve kontrollü dönüşü öğretir.","asamalar":{"giris":"Sol bacağı uzatın, sağ ayağı sağ oturma kemiğinin önüne basın. Nefes alarak sol kolu yukarı uzatın, nefes vererek sol dirseği sağ dizin dışına yerleştirip sağa dönün.","kalis":"Uzun bacağın ayak parmakları tavana baksın, pelvis geriye devrilmesin; her nefes alışta uzayın, verişte göğsü açın. 5 nefes kalın.","cikis":"Nefes alarak bağı ya da kolu bırakın, önce göğsü sonra başı merkeze getirin ve iki bacağı uzatarak bir nefes dinlenin."},"hata":{"ne":"Pelvisi geriye devirip sırtı yuvarlamak.","neden":"Hamstringler ve kalça arkası kısa olduğunda pelvis arkaya devrilir ve bel omurları dönüş için yuvarlanır.","yonlendirme":"Önce oturma kemikleri, sonra dönüş."},"soylenecekler":["Uzun bacağınızın topuğunu ileri itin.","Dirseğiniz dizi tutsun, itmesin.","Göğsünüzün önü genişlesin, omuzlarınız geri yerleşsin."],"eller":{"nereye":"Bir el sakrumun hemen üstünde, diğer el dönülen tarafın kürek kemiğinin dış kenarında.","nasil":"Sakrumdaki elle hafifçe öne-yukarı yön verin; kürek kemiğindeki el omzun geri yerleşmesini sadece hatırlatsın.","ne_zaman_degil":"İzin yoksa, öğrenci bağı zorluyorsa, omuzda ya da belde ağrı varsa veya hamileyse dokunmayın."},"kolay":"Oturma kemiklerinin altına battaniye koyun ve dizi kucaklayarak dönün; bağ yapmayın.","zor":"Kolları dizin etrafından ve sırtın arkasından bağlayın, göğsü açık tutarak bakışı arka omzun üzerinden götürün.","dikkat":"Omuz instabilitesi olan öğrencide bağı atlayın; bel ya da kalçada ağrı varsa öğrencinin doktoruna ya da fizyoterapistine danışmasını önerin.","s":74,"fig":false},{"n":66,"bolum":5,"ad":"Sırtüstü burgu (Supta Matsyendrasana)","aile":"Burgu","seviye":"Başlangıç","yogunluk":[1,3,4],"calisan":["Oblikler","Diyafram"],"dengeleyen":["Transversus abdominis","Büyük ve küçük pektoral"],"uzayan":["Gluteus medius ve minimus","Büyük ve küçük pektoral","Quadratus lumborum"],"ozet":"Sırtüstü yatarak yer çekimine bırakılan pasif burgu. Dersin sonunda kapanışa geçmeden önce omurgayı rahatlatmak için kullanılır.","asamalar":{"giris":"Sırtüstü yatın, sağ dizi göğse çekin. Nefes vererek sağ dizi sol tarafa doğru indirin, sağ kolu omuz hizasında yana açın.","kalis":"Sağ omzu yere yakın tutun, dizi zorla yere bastırmayın; uzun ve sakin nefeslerle 8–10 nefes ya da 1 dakika kalın.","cikis":"Nefes alarak dizi tavana getirin, bacağı uzatın ve diğer tarafa geçmeden önce iki bacak uzun bir nefes dinlenin."},"hata":{"ne":"Dizi yere değdirmek için omzu yerden kaldırmak.","neden":"Göğüs ve omuz önü kısa olduğunda dizi aşağı indirmek, karşı omzu yerden kopartarak telafi edilir.","yonlendirme":"Omuz yerde kalsın, diz nerede kalırsa orası doğru."},"soylenecekler":["Dizinizin altına blok koyabilirsiniz, bu yere bırakmayı kolaylaştırır.","Her nefes verişte göğsünüzün yere biraz daha yerleştiğini hissedin.","Burada hiçbir şey yapmanız gerekmiyor, sadece nefes alın."],"eller":{"nereye":"Açılan kolun omzunun önü ya da bükülü dizin dış yüzü.","nasil":"Omzun önüne çok hafif, yere doğru sabit bir ağırlık bırakın; dizi aşağı bastırmayın.","ne_zaman_degil":"İzin yoksa, öğrencide kalça protezi, sakroiliak hassasiyet ya da hamilelik varsa dokunmayın."},"kolay":"Bükülü dizin altına blok ya da yastık koyun; iki dizi birlikte bükülü bırakın.","zor":"Üstteki bacağı düz uzatıp karşı elle ayağı tutun, bakışı açılan kola çevirin.","dikkat":"Hamilelikte sırtüstü kalışı kısa tutun veya yan yatışa geçin; belde ağrı varsa öğrencinin doktoruna ya da fizyoterapistine danışmasını önerin.","s":75,"fig":false},{"n":67,"bolum":5,"ad":"Dönen hamle (Parivrtta Anjaneyasana)","aile":"Burgu","seviye":"Orta","yogunluk":[3,5,7],"calisan":["Oblikler","Kuadriseps","Gluteus maximus"],"dengeleyen":["Gluteus medius ve minimus","Transversus abdominis","Addüktörler"],"uzayan":["İliopsoas"],"ozet":"Alçak hamlede ellerin göğüs önünde birleştiği ayakta burgu. Dengeyi, kalça stabilitesini ve dönüşü bir arada çalışır.","asamalar":{"giris":"Sağ ayak önde alçak hamleye gelin, arka diz yerde. Elleri göğüs önünde birleştirin; nefes alarak uzayın, nefes vererek sol dirseği sağ dizin dışına götürün.","kalis":"Öndeki diz bileğin üstünde, pelvis kare kalsın; avuçları birbirine bastırarak göğsü açın. 5 nefes kalın.","cikis":"Nefes alarak gövdeyi merkeze getirin, elleri öndeki ayağın iki yanına koyup arka dizi bırakın ve diğer tarafa geçin."},"hata":{"ne":"Öndeki dizin içe çökmesi.","neden":"Dönüş sırasında öndeki kalçanın dış rotatorları ve gluteus medius ve minimus gevşerse diz içe kayar.","yonlendirme":"Diz ayak bileğinin üstünde, uyluk sabit."},"soylenecekler":["Arka dizinizin altını yumuşak tutun, battaniye koyabilirsiniz.","Avuçlarınızı birbirine bastırın ve göğsünüzü başparmaklarınıza doğru açın.","Öndeki diziniz dönmesin, sadece gövde dönsün."],"eller":{"nereye":"Öndeki dizin dış yanı ve arkadaki uyluk tarafında kalça kemiğinin yanı.","nasil":"Dize çok hafif dışa yön verin, kalçaya sadece kare kalması için temas edin; gövdeyi döndürmeyin.","ne_zaman_degil":"İzin yoksa, arka dizde ağrı varsa, öğrenci dengesiz ya da hamileyse dokunmayın."},"kolay":"Elleri dirsek bağlamak yerine öndeki uyluğa koyun ve sadece göğsü hafifçe çevirin.","zor":"Arka dizi yerden kaldırarak yüksek hamlede yapın ya da kolları açarak bir eli yere, diğerini tavana uzatın.","dikkat":"Diz ya da kalça problemi olan öğrencide arka dizi iyi destekleyin; ağrı varsa öğrencinin doktoruna ya da fizyoterapistine danışmasını önerin.","s":76,"fig":false},{"n":68,"bolum":5,"ad":"Dönen yan açı (Parivrtta Parsvakonasana)","aile":"Burgu","seviye":"İleri","yogunluk":[4,6,8],"calisan":["Oblikler","Kuadriseps","Gluteus maximus"],"dengeleyen":["Addüktörler","Transversus abdominis","Gluteus medius ve minimus"],"uzayan":["İliopsoas","Gastroknemius ve soleus"],"ozet":"Geniş duruşta, gövdenin öndeki uyluğun üzerine döndüğü güçlü ayakta burgu. Bacak kuvveti, denge ve uzun bir omurgayla dönüş ister.","asamalar":{"giris":"Geniş hamlede sağ dizi bükün, arka topuğu kaldırın. Nefes alarak uzayın, nefes vererek gövdeyi sağ uyluğun üzerine döndürüp sol eli ayağın dışına ya da bloğa koyun.","kalis":"Arka bacak güçlü ve düz, öndeki diz bileğin üstünde kalsın; başın tepesinden arka topuğa kadar tek bir çizgi düşünün. 5 nefes kalın.","cikis":"Nefes alarak üst kolu indirip gövdeyi merkeze getirin, elleri yere koyun ve arka ayağı öne alarak öne eğilmede dinlenin."},"hata":{"ne":"Yere ulaşmak için sırtı yuvarlayıp göğsü uyluğa çökertmek.","neden":"Kalça fleksiyonu ve torakal rotasyon yetersizken el yere zorlanınca hareket bel bölgesinin bükülmesiyle telafi edilir.","yonlendirme":"Yer yerine blok, burgu yerine uzunluk."},"soylenecekler":["Arka topuğunuzu geriye itin ve bacağınızı aktif tutun.","Göğsünüz tavana açılsın, alttaki kolunuz sadece destek olsun.","Nefesiniz kısalırsa bir kademe geri gelin."],"eller":{"nereye":"Arka kalçanın yan yüzü ve üstteki omzun arka kısmı.","nasil":"Arka kalçaya hafif aşağı ve geri yön verin; omza sadece açılma yönünü gösterin, asla döndürme kuvveti eklemeyin.","ne_zaman_degil":"İzin yoksa, öğrenci denge kaybı yaşıyorsa, belde, dizde ya da boyunda ağrı varsa veya hamileyse dokunmayın."},"kolay":"Arka dizi yere indirin ve alttaki eli bloğa koyun; dua elleriyle dirseği dizin dışına yerleştirin.","zor":"Kolları öndeki bacağın altından ve sırtın arkasından bağlayın, bakışı tavana çevirin.","dikkat":"Yüksek tansiyon, baş dönmesi ya da hamilelikte başı aşağı tutmayın ve kısa kalın; ağrı varsa öğrencinin doktoruna ya da fizyoterapistine danışmasını önerin.","s":77,"fig":false},{"n":69,"bolum":5,"ad":"İğneye iplik geçirme","aile":"Burgu","seviye":"Başlangıç","yogunluk":[2,3,5],"calisan":["Oblikler","Rotator manşet"],"dengeleyen":["Serratus anterior","Transversus abdominis"],"uzayan":["Rhomboidler","Orta ve alt trapezius","Deltoid"],"ozet":"Dört ayak duruşundan bir kolun diğerinin altından kayarak omuz ve üst sırtın döndüğü yumuşak burgu. Masa başında çalışan öğrenciler için üst sırt hareketliliğini çalışmanın sakin bir yoludur.","asamalar":{"giris":"Dört ayak duruşuna gelin. Nefes alarak sağ kolu tavana açın, nefes vererek sağ kolu sol kolun altından kaydırıp sağ omzu ve şakağı yere bırakın.","kalis":"Kalçalar dizlerin üstünde kalsın, sol el yeri itsin; boyun rahat, ağırlık başta değil omuzda olsun. 5–8 nefes kalın.","cikis":"Sol eli yere bastırarak nefes alın, sağ kolu geri çekip dört ayağa dönün ve diğer tarafı yapın."},"hata":{"ne":"Ağırlığı başa ve boyna vermek.","neden":"Kalçalar yana kayıp üst sırt yeterince dönmediğinde gövdenin ağırlığı başa ve boyun omurlarına düşer.","yonlendirme":"Kalça dizlerin üstünde, ağırlık omuzda."},"soylenecekler":["Kaydırdığınız kolun omzunu yere yerleştirin, başınız sadece dinlensin.","Destek elinizle yeri itin ve kürek kemiğinizin açıldığını hissedin.","Nefes verirken biraz daha bırakın, ama hiçbir şeyi zorlamayın."],"eller":{"nereye":"Kalçanın yan tarafı ve yukarıda kalan kürek kemiğinin üst kenarı.","nasil":"Kalçayı dizlerin üstünde kalması için hafifçe ortalayın; kürek kemiğine çok hafif geniş bir temas yeterli.","ne_zaman_degil":"İzin yoksa, omuzda ağrı ya da yakın zamanda omuz yaralanması varsa, boyun hassasiyeti ya da hamilelikte yere yakın pozisyon rahatsız ediyorsa dokunmayın."},"kolay":"Başın altına battaniye ya da blok koyun ve kalçaları biraz geride tutun.","zor":"Üstteki kolu sırtın arkasına sarıp elle iç uyluğa uzanın ya da kolu başın üstünden ileri uzatın.","dikkat":"Diz hassasiyetinde dizlerin altına battaniye koyun; omuzda ağrı varsa öğrencinin doktoruna ya da fizyoterapistine danışmasını önerin.","s":78,"fig":false},{"n":70,"bolum":5,"ad":"Sandalyede oturarak burgu","aile":"Burgu","seviye":"Başlangıç","yogunluk":[1,3,4],"calisan":["Oblikler","Multifidus"],"dengeleyen":["Erector spinae","Transversus abdominis"],"uzayan":["Quadratus lumborum","Rhomboidler"],"ozet":"Sandalyede oturarak yapılan erişilebilir burgu. Yere oturamayan, ileri yaş ya da ofis yogası gruplarında burgunun temelini öğretmek için kullanılır.","asamalar":{"giris":"Sandalyenin ön kenarına oturun, ayaklar kalça genişliğinde yerde. Nefes alarak omurgayı uzatın, nefes vererek sağa dönüp sağ eli sandalyenin arkasına, sol eli sağ dize koyun.","kalis":"Dizler aynı hizada ve öne baksın, iki oturma kemiği sandalyede eşit kalsın; her nefes alışta uzayın. 5 nefes kalın.","cikis":"Nefes alarak merkeze dönün, elleri dizlere bırakın ve bir nefes dinlendikten sonra sola geçin."},"hata":{"ne":"Dizlerin de dönüşe katılıp yana kayması.","neden":"Pelvis sabitlenmediğinde dönüş kalçadan gelir ve omurgada burgu neredeyse hiç olmaz.","yonlendirme":"Dizler öne baksın, gövde dönsün."},"soylenecekler":["İki ayağınızı da yere basın ve dizlerinizi yan yana tutun.","Sandalyenin arkasını kendinizi döndürmek için değil, dik kalmak için tutun.","Nefes alın, uzayın; nefes verin, biraz daha dönün."],"eller":{"nereye":"Dizlerin dış yüzü ya da öğrencinin arkasında durarak kürek kemiklerinin arası.","nasil":"Dizlere yan yana kalmaları için hafif bir sabitleme verin ya da sırta yukarı doğru uzama yönü gösterin; döndürmeyin.","ne_zaman_degil":"İzin yoksa, öğrenci denge ya da baş dönmesi sorunu tarif ediyorsa veya sırtta ağrı varsa dokunmayın."},"kolay":"Elleri sadece dizlerde tutun ve dönüşü küçük bırakın.","zor":"Kolları göğüs önünde çaprazlayıp el desteği olmadan dönün ve bakışı arka omza götürün.","dikkat":"Sandalyenin sabit ve tekerleksiz olduğundan emin olun; belde ağrı varsa öğrencinin doktoruna ya da fizyoterapistine danışmasını önerin.","s":79,"fig":false},{"n":71,"bolum":5,"ad":"Dönen baş dize","aile":"Burgu","seviye":"Orta","yogunluk":[3,5,7],"calisan":["Oblikler","Latissimus dorsi"],"dengeleyen":["Quadratus lumborum","Transversus abdominis"],"uzayan":["Hamstringler","Addüktörler","Latissimus dorsi"],"ozet":"Geniş oturuşta gövdenin uzun bacağa yana eğildiği ve göğsün tavana döndüğü yan uzama-burgu. Gövdenin yan hattını ve kaburgalar arası nefesi çalışır.","asamalar":{"giris":"Sol bacağı yana uzatın, sağ ayak tabanını iç uyluğa yerleştirin. Nefes alarak sağ kolu yukarı uzatın, nefes vererek sol bacağa doğru yana eğilin ve göğsü tavana çevirin.","kalis":"Alttaki omuz bacağın içinde, göğüs tavana açık kalsın; üst kolu kulağın yanından uzatın. Sağ kaburgalara nefes alarak 5 nefes kalın.","cikis":"Nefes alarak üst kolun gücüyle gövdeyi kaldırın, merkeze gelin ve bacak değiştirmeden önce bir nefes dik oturun."},"hata":{"ne":"Göğsü yere doğru kapatıp öne eğilmeye dönüştürmek.","neden":"Hamstringler ve addüktörler kısa olduğunda gövde yana değil öne kayar ve burgu kaybolur.","yonlendirme":"Göğüs tavana, kol kulağın yanında."},"soylenecekler":["Bükülü dizinizi geriye açın ve iki oturma kemiğinizi yerde tutun.","Üst kolunuzla bir yay çizer gibi uzanın.","Ayağa ulaşmak zorunda değilsiniz; yan bedeninizin uzunluğu önemli."],"eller":{"nereye":"Yukarıdaki kaburga kafesinin yan yüzü ve bükülü bacağın kalçası.","nasil":"Kalçaya yere doğru hafif ağırlık verin, kaburgalara sadece tavana açılma yönünü gösterin.","ne_zaman_degil":"İzin yoksa, hamstring ya da kasıkta yakın zamanda zorlanma varsa veya hamileyse dokunmayın."},"kolay":"Uzun bacağın dizini bükün, alttaki dirseği uyluğa ya da bloğa yaslayın.","zor":"Alttaki elle uzun bacağın ayağını içten tutun, üst elle de ayağa uzanıp göğsü tamamen tavana çevirin.","dikkat":"Kasık ya da hamstring yaralanması öyküsünde dizleri bükülü tutun; ağrı varsa öğrencinin doktoruna ya da fizyoterapistine danışmasını önerin.","s":80,"fig":false},{"n":72,"bolum":5,"ad":"Burgulu alçak hamle","aile":"Burgu","seviye":"Başlangıç","yogunluk":[2,4,6],"calisan":["Oblikler","Kuadriseps"],"dengeleyen":["Gluteus medius ve minimus","Transversus abdominis","Serratus anterior"],"uzayan":["İliopsoas","Büyük ve küçük pektoral"],"ozet":"Arka diz yerdeyken bir elin yere, diğerinin tavana uzandığı açık burgu. Kalça önünü uzatırken göğsü açmayı yeni başlayanlara güvenli biçimde öğretir.","asamalar":{"giris":"Sağ ayak önde alçak hamleye gelin, sol eli sağ ayağın içinde yere ya da bloğa koyun. Nefes alarak sağ kolu tavana açın ve göğsü sağa çevirin.","kalis":"Pelvis hafifçe aşağı yerleşsin, öndeki diz bileğin üstünde kalsın; alttaki el yeri iterek omzu kulaktan uzaklaştırsın. 5 nefes kalın.","cikis":"Nefes vererek üst kolu indirin, iki eli öndeki ayağın yanına koyun ve arka dizi yerden kaldırmadan önce bir nefes bekleyin."},"hata":{"ne":"Alttaki omzun kulağa doğru çökmesi.","neden":"Destek kolunda serratus anterior çalışmadığında kürek kemiği göğüs kafesinden ayrılır ve omuz yükselir.","yonlendirme":"Yeri itin, omzu uzaklaştırın."},"soylenecekler":["Alttaki elinizle yeri itin, göğsünüz o elden yükselsin.","Arka kalçanızın önünde açılmayı hissedin.","Göğsünüzü üst elinize doğru çevirin, bakışınız rahat kalabilir."],"eller":{"nereye":"Arka kalçanın arka yüzü ve üst kolun omuz başı.","nasil":"Kalçaya hafif öne-aşağı yön verin; omuz başına sadece geri açılma hatırlatması yapın.","ne_zaman_degil":"İzin yoksa, arka dizde ağrı, omuz yaralanması ya da hamilelik varsa dokunmayın."},"kolay":"Alttaki eli yüksek bloğa koyun ve üst eli kalçada bırakın.","zor":"Üst kolu kulağın yanından ileri uzatın ya da arka ayağı tutarak kuadriseps uzamasını ekleyin.","dikkat":"Diz hassasiyetinde arka dizin altına katlanmış battaniye koyun; ağrı varsa öğrencinin doktoruna ya da fizyoterapistine danışmasını önerin.","s":81,"fig":false},{"n":73,"bolum":5,"ad":"Dizler bükülü sırtüstü burgu","aile":"Burgu","seviye":"Başlangıç","yogunluk":[1,2,3],"calisan":["Oblikler","Diyafram"],"dengeleyen":["Transversus abdominis","Addüktörler"],"uzayan":["Quadratus lumborum","Gluteus medius ve minimus"],"ozet":"Sırtüstü, iki dizin birlikte bir yandan diğerine indiği en sade burgu. Bel bölgesini nazikçe hareketlendirmek ve nefesi yavaşlatmak için dersin başında ya da sonunda kullanılır.","asamalar":{"giris":"Sırtüstü yatın, ayakları yere basın ve kolları yana açın. Nefes vererek iki dizi birlikte sağa indirin, başı isterseniz sola çevirin.","kalis":"Dizler ve ayaklar birlikte kalsın, iki omuz yerde dinlensin; nefes alırken karnın ve kaburgaların genişlediğini izleyin. Her yönde 5–8 nefes kalın.","cikis":"Nefes alarak karnı hafifçe içe çekin, dizleri merkeze getirin ve diğer tarafa geçmeden bir nefes bekleyin."},"hata":{"ne":"Dizleri hızla bir yandan diğerine düşürmek.","neden":"Karın derin kasları kontrolü bıraktığında bacakların ağırlığı bel omurlarını kontrolsüz biçimde döndürür.","yonlendirme":"Yavaş inin, karından geri gelin."},"soylenecekler":["Dizlerinizi bir arada tutun, aralarına blok koyabilirsiniz.","Karşı omzunuz yere yakın kalsın.","Dizlerinizi, nefesinizin hızında yavaşça taşıyın."],"eller":{"nereye":"İndirilen dizlerin dış yüzü ya da karşı omzun önü.","nasil":"Dizlerin inişine sadece eşlik edin; omza hafif ve sabit bir temasla yerde kalmasını hatırlatın.","ne_zaman_degil":"İzin yoksa, öğrencide belde ağrı, sakroiliak hassasiyet ya da hamilelik varsa dokunmayın."},"kolay":"Dizlerin altına yastık ya da blok koyun ve hareketi küçük tutun.","zor":"Dizleri kalça hizasında tutup bacakları yerden yukarıda kaldırarak kontrollü biçimde iki yana indirin.","dikkat":"Hamilelikte sırtüstü süreyi kısa tutun; belde ağrı varsa öğrencinin doktoruna ya da fizyoterapistine danışmasını önerin.","s":82,"fig":false},{"n":74,"bolum":5,"ad":"Dört ayak üzerinde burgu","aile":"Burgu","seviye":"Başlangıç","yogunluk":[2,3,5],"calisan":["Oblikler","Serratus anterior","Rotator manşet"],"dengeleyen":["Transversus abdominis","Gluteus medius ve minimus"],"uzayan":["Büyük ve küçük pektoral"],"ozet":"Dört ayak duruşundan bir kolun tavana açıldığı aktif burgu. Destek omzunun stabilitesini ve üst sırt rotasyonunu birlikte öğretir; kol dengelerine hazırlık olarak kullanılır.","asamalar":{"giris":"Eller omuzların, dizler kalçaların altında dört ayak duruşuna gelin. Nefes alarak sağ kolu yana ve tavana açın, göğsü sağa çevirin.","kalis":"Kalçalar dizlerin üstünde sabit, destek kolu yeri itiyor; dönüş üst sırttan gelsin. 3–5 nefes kalın ya da nefesle 5 kez açılıp kapanın.","cikis":"Nefes vererek kolu yere indirin, iki avucu eşit bastırın ve diğer kola geçin."},"hata":{"ne":"Kalçaları dönüşe katıp yana kaydırmak.","neden":"Torakal rotasyon kısıtlı olduğunda hareket pelvisten tamamlanır ve gövde merkezden kayar.","yonlendirme":"Kalçalar sabit, göğüs döner."},"soylenecekler":["Destek elinizin tüm parmaklarıyla yeri itin.","Kalçanızı dizlerinizin üstünde tutun, sadece göğsünüz açılsın.","Nefes alırken açın, nefes verirken geri gelin."],"eller":{"nereye":"Kalçaların iki yan tarafı.","nasil":"İki elle kalçayı hafifçe ortada tutun; öğrenci dönerken sadece sabit referans olun.","ne_zaman_degil":"İzin yoksa, destek bileğinde ya da omuzda ağrı varsa veya öğrenci dizlerde rahatsızlık tarif ediyorsa dokunmayın."},"kolay":"Açılan eli başın arkasına koyup dirseği tavana çevirin.","zor":"Açılan kolu tavana tuttuktan sonra karşı bacağı geriye uzatın ve dengede kalarak dönün.","dikkat":"Bilek hassasiyetinde ön kollara inin ya da avuç altına katlanmış mat koyun; ağrı varsa öğrencinin doktoruna ya da fizyoterapistine danışmasını önerin.","s":83,"fig":false},{"n":75,"bolum":6,"ad":"Güvercin (Eka Pada Rajakapotasana, hazırlık)","aile":"Kalça açma","seviye":"Orta","yogunluk":[3,5,7],"calisan":["Erector spinae","Gluteus medius ve minimus"],"dengeleyen":["Piriformis","İliopsoas","Transversus abdominis"],"uzayan":["Piriformis","İliopsoas","Gluteus maximus"],"ozet":"Öndeki kalçanın dış rotasyonda, arka kalçanın uzamada olduğu klasik kalça açıcı. Kalçayı açarken dizi korumayı öğretir; Rajakapotasana'ya hazırlıktır.","asamalar":{"giris":"Aşağı bakan köpekten sağ dizi sağ bileğin arkasına getirin, sol bacağı geriye uzatın. Nefes alarak elleri yere bastırıp omurgayı uzatın, pelvisi iki yanda eşit yerleştirin.","kalis":"Pelvis kare ve arka bacak düz kalsın; öndeki ayak bileği aktif, nefes verirken kalça yere biraz daha yerleşsin. Dik ya da öne eğilerek 8–10 nefes kalın.","cikis":"Nefes alarak ellerle yeri iterek yükselin, arka ayak parmaklarını kıvırın ve öndeki bacağı geri alıp aşağı bakan köpeğe dönün."},"hata":{"ne":"Ağırlığı kalça yerine öndeki dize vermek.","neden":"Kalça dış rotasyonu yetersiz olduğunda açılma dizden aranır ve diz eklemi yandan gelen gerilimi taşır.","yonlendirme":"Dizi koruyun, kalçayı açın."},"soylenecekler":["Öndeki ayağınızı esnetin, ayak bileğiniz kıvrılmasın.","Kalçanız yere değmiyorsa altına blok koyun, ağırlığınız oraya düşsün.","Dizinizde batma hissederseniz pozdan çıkın; kalçanızda yayılan bir his arıyoruz."],"eller":{"nereye":"Öndeki bacağın kalça kemiği tarafı ve arka bacağın kalçası.","nasil":"İki kalçayı aynı hizaya getirmek için hafifçe yön verin; öğrenciyi aşağı itmeyin, ağırlık vermeyin.","ne_zaman_degil":"İzin yoksa, öğrenci dizde ağrı tarif ediyorsa, kalça protezi ya da hamilelik varsa dokunmayın."},"kolay":"Öndeki kalçanın altına blok ya da battaniye koyun, ya da sırtüstü güvercin (4 pozu) ile değiştirin.","zor":"Arka dizi bükün, ayağı aynı taraftaki elle tutup göğsü açarak tek bacaklı güvercine yaklaşın.","dikkat":"Diz yaralanması, kalça protezi ya da sakroiliak hassasiyette sırtüstü varyasyonu kullanın; ağrı varsa öğrencinin doktoruna ya da fizyoterapistine danışmasını önerin.","s":85,"fig":true},{"n":76,"bolum":6,"ad":"Sırtüstü güvercin (4 pozu)","aile":"Kalça açma","seviye":"Başlangıç","yogunluk":[2,3,5],"calisan":["İliopsoas","Transversus abdominis"],"dengeleyen":["Diyafram","Erector spinae"],"uzayan":["Piriformis","Gluteus maximus","Gluteus medius ve minimus"],"ozet":"Sırtüstü yatarak bir ayak bileğinin karşı dizin üstüne yerleştiği kalça açıcı. Dizi korumaya ihtiyaç duyan ya da yere oturmakta zorlanan öğrenciler için güvercinin güvenli karşılığıdır.","asamalar":{"giris":"Sırtüstü yatın, iki ayağı yere basın. Sağ ayak bileğini sol dizin üstüne koyun; nefes vererek sol ayağı yerden kaldırıp sol uyluğun arkasını kucaklayın.","kalis":"Sakrum ve başın arkası yerde, omuzlar rahat kalsın; sağ ayak esnek, diz hafifçe dışa açık. 8–10 nefes kalın.","cikis":"Nefes alarak sol ayağı yere indirin, sağ bileği dizden alın ve bacakları uzatıp bir nefes dinlendikten sonra diğer tarafa geçin."},"hata":{"ne":"Uyluğu çekmek için başı ve omuzları yerden kaldırmak.","neden":"Kalça arkası kısa olduğunda bacağa ulaşmak için boyun ve omuz kasları devreye girer ve üst gövde gerilir.","yonlendirme":"Baş yerde; bacağa kayış ya da ayak duvarda."},"soylenecekler":["Kuyruk sokumunuzu yere yaklaştırın.","Üstteki ayağınızı esnetin, bu dizinizi korur.","Ellerinize ulaşamıyorsanız kayış kullanın; başınız yerde kalsın."],"eller":{"nereye":"Açılan bacağın iç dizinin hemen üstü, uyluk tarafı.","nasil":"Dizin üstüne, uyluk ekseninde hafif bir dışa yönlendirme yapın; aşağı bastırmayın ve dize asla doğrudan baskı uygulamayın.","ne_zaman_degil":"İzin yoksa, dizde ya da kalçada ağrı varsa, kalça protezi ya da hamilelik varsa dokunmayın."},"kolay":"Alttaki ayağı yerde ya da duvarda bırakın, sadece bileği dizin üstüne koyun.","zor":"Kalçaları hafifçe yerden kaldırıp sakrumu açın ya da kayıştan vazgeçip uyluğu göğse daha yakın çekin.","dikkat":"Hamilelikte sırtüstü kalışı kısaltın; dizde ağrı varsa öğrencinin doktoruna ya da fizyoterapistine danışmasını önerin.","s":86,"fig":false},{"n":77,"bolum":6,"ad":"Kertenkele (Utthan Pristhasana)","aile":"Kalça açma","seviye":"Orta","yogunluk":[3,5,7],"calisan":["Kuadriseps","Serratus anterior"],"dengeleyen":["Transversus abdominis","Gluteus medius ve minimus"],"uzayan":["İliopsoas","Addüktörler","Hamstringler"],"ozet":"Öndeki ayağın elin dışında olduğu derin hamle. Kalça fleksörlerini ve iç uyluğu birlikte uzatır; geriye eğilmeler ve splitler öncesinde hazırlık olarak kullanılır.","asamalar":{"giris":"Aşağı bakan köpekten sağ ayağı sağ elin dışına getirin, arka dizi yere indirin. Nefes alarak omurgayı uzatın, nefes vererek kalçayı öne-aşağı yerleştirin.","kalis":"Öndeki diz bileğin üstünde ya da biraz önünde, dışa doğru açık; göğüs öne uzanıyor, omuzlar kulaklardan uzak. Ellerde ya da ön kollarda 5–8 nefes kalın.","cikis":"Nefes alarak ellere yükselin, arka ayak parmaklarını kıvırın ve öndeki ayağı geri alarak aşağı bakan köpeğe dönün."},"hata":{"ne":"Ön kollara inmek için sırtı yuvarlayıp omuzları çökertmek.","neden":"Kalça fleksörleri ve addüktörler yeterince uzamadan gövde aşağı indirilince eksik hareket üst sırtın bükülmesiyle karşılanır.","yonlendirme":"Ellerde uzun sırt, ön kol ancak sonra."},"soylenecekler":["Arka dizinizi bir battaniyeye bırakabilirsiniz.","Öndeki dizinizi biraz dışa açın, ayağınız sağlam bassın.","Göğsünüzü ileri uzatın, aşağı inmek zorunda değilsiniz."],"eller":{"nereye":"Arka bacağın kalçasının arka yüzü ve öndeki dizin iç yanı.","nasil":"Arka kalçaya çok hafif öne yön verin, dize sadece dışa açılma hatırlatması yapın; kalçayı aşağı itmeyin.","ne_zaman_degil":"İzin yoksa, kasıkta zorlanma, diz ağrısı ya da hamilelik varsa dokunmayın."},"kolay":"Ellerin altına blok koyun ve arka dizi yerde tutun.","zor":"Arka dizi yerden kaldırıp bacağı düzleştirin, ön kollara inin ve öndeki dizi dışa açın.","dikkat":"Kasık ya da kalça eklemi hassasiyetinde eller blokta kalsın; ağrı varsa öğrencinin doktoruna ya da fizyoterapistine danışmasını önerin.","s":87,"fig":false},{"n":78,"bolum":6,"ad":"Bağlı açı (Baddha Konasana)","aile":"Kalça açma","seviye":"Başlangıç","yogunluk":[2,3,5],"calisan":["Erector spinae","İliopsoas"],"dengeleyen":["Addüktörler","Pelvik taban","Transversus abdominis"],"uzayan":["Addüktörler"],"ozet":"Ayak tabanlarının birleştiği ve dizlerin yana açıldığı oturuş. İç uyluk esnekliğini ve dik oturuşu çalışır; nefes ve pelvik taban farkındalığı için derslerde sık kullanılır.","asamalar":{"giris":"Oturup ayak tabanlarını birleştirin, dizleri yana açın. Nefes alarak oturma kemiklerine yerleşip omurgayı uzatın, elleri ayak bileklerine koyun.","kalis":"Pelvis dik, göğüs açık; dizler kendi ağırlığıyla aşağı insin. İsterseniz nefes verirken kalçalardan öne eğilin. 8–10 nefes kalın.","cikis":"Nefes alarak gövdeyi dikleştirin, elleri dizlerin dışına koyup dizleri birleştirin ve bacakları önde uzatın."},"hata":{"ne":"Dizleri ellerle aşağı bastırmak.","neden":"Addüktörler gerilimdeyken dizler zorla aşağı itildiğinde kasık ve diz iç yanı fazla yüklenir.","yonlendirme":"Dizler kendi ağırlığıyla insin."},"soylenecekler":["Oturma kemiklerinizi yere bastırın, başınızın tepesi yükselsin.","Ayaklarınızı kitap açar gibi açabilirsiniz, ama dizlerinizi itmeyin.","Öne eğilirseniz göğsünüz ayaklarınıza uzansın, başınız dizlerinize değil."],"eller":{"nereye":"Öğrencinin arkasında, iki el bel üstünde omurganın iki yanında.","nasil":"Omurganın uzaması için hafif yukarı yön verin; dizlere ya da sırta aşağı baskı uygulamayın.","ne_zaman_degil":"İzin yoksa, kasık ya da diz iç yanında ağrı varsa, pelvik bölgeyle ilgili hassasiyet ya da hamilelik varsa dokunmayın."},"kolay":"Oturma kemiklerinin altına battaniye, dizlerin altına blok koyun; ayakları kalçadan uzaklaştırın.","zor":"Ayakları kasığa yaklaştırıp kalçalardan uzun bir sırtla öne eğilin.","dikkat":"Hamilelikte öne eğilmeyi atlayın ve dik kalın; kasıkta ağrı varsa öğrencinin doktoruna ya da fizyoterapistine danışmasını önerin.","s":88,"fig":false},{"n":79,"bolum":6,"ad":"Sırtüstü bağlı açı (Supta Baddha Konasana)","aile":"Restoratif","seviye":"Başlangıç","yogunluk":[1,2,3],"calisan":["Diyafram","Pelvik taban"],"dengeleyen":["Addüktörler","İliopsoas"],"uzayan":["Addüktörler","Büyük ve küçük pektoral"],"ozet":"Sırtüstü, ayak tabanları birleşik ve dizler destekli restoratif kalça açıcı. Dersin sonunda sinir sistemini yavaşlatmak ve nefes farkındalığı için kullanılır.","asamalar":{"giris":"Sırtüstü yatın, ayak tabanlarını birleştirip dizleri yana açın ve uyluk altlarına blok yerleştirin. Nefes vererek kolları yanlara, avuçları yukarı bırakın.","kalis":"Bel doğal kavisinde, omuzlar geniş kalsın; dizler bloklarda tamamen dinlensin. Karna ve kaburgalara yayılan yavaş nefeslerle 2–5 dakika kalın.","cikis":"Nefes alarak elleri dizlerin dışına koyun, dizleri yavaşça birleştirin, ayakları yere basın ve bir yana dönüp oturuşa yükselin."},"hata":{"ne":"Destek olmadan dizleri aşağı zorlamak.","neden":"Desteksiz kalan dizlerin ağırlığı addüktörleri ve kasığı sürekli gerilimde tutar ve gevşeme yerine kas korunması oluşur.","yonlendirme":"Uyluk altına blok, bırakın gitsin."},"soylenecekler":["Dizlerinizin bloklara tamamen yerleştiğini hissedin.","Nefes alırken karnınız yükselsin, verirken sırtınız yere yayılsın.","Burada yapacak hiçbir şey yok, sadece kalın."],"eller":{"nereye":"Blokların konumu ya da omuzların önü.","nasil":"Dokunmak yerine blokları ya da battaniyeyi ayarlayarak destek verin; gerekirse omuzlara çok hafif, sabit bir temas yeterli.","ne_zaman_degil":"İzin yoksa, öğrenci gözleri kapalı derin gevşemedeyse uyarmadan, kasıkta ağrı ya da hamilelik varsa dokunmayın."},"kolay":"Sırtın altına uzunlamasına bolster ya da katlanmış battaniye koyun, başın altını destekleyin.","zor":"Blokları alçaltın ya da kaldırın; tamamen pasif bir uzamada kalışı uzatın.","dikkat":"Hamilelikte gövdeyi eğimli bolster üstünde yükseltin; kasıkta ya da belde ağrı varsa öğrencinin doktoruna ya da fizyoterapistine danışmasını önerin.","s":89,"fig":true},{"n":80,"bolum":6,"ad":"Çelenk (Malasana)","aile":"Kalça açma","seviye":"Orta","yogunluk":[3,5,6],"calisan":["Tibialis anterior","Erector spinae"],"dengeleyen":["Addüktörler","Pelvik taban","Transversus abdominis"],"uzayan":["Gastroknemius ve soleus","Addüktörler","Gluteus maximus"],"ozet":"Ayaklar yere basılı derin çömelme. Ayak bileği hareketliliğini, kalça açıklığını ve çömelirken dik omurgayı birlikte öğretir.","asamalar":{"giris":"Ayakları mat genişliğinde, parmak uçları hafifçe dışa açık basın. Nefes vererek kalçaları topukların arasına indirin, avuçları göğüs önünde birleştirin.","kalis":"Topuklar yere yakın, dizler ayak parmaklarıyla aynı yöne baksın; dirsekler dizleri hafifçe açarken göğüs yükselsin. 5–8 nefes kalın.","cikis":"Elleri yere koyun, nefes alarak kalçaları yukarı kaldırıp öne eğilmeye geçin ve oradan yavaşça yuvarlanarak doğrulun."},"hata":{"ne":"Topukların yerden kalkıp ağırlığın parmak uçlarına geçmesi.","neden":"Gastroknemius ve soleus kısa olduğunda ayak bileği yeterince bükülmez ve vücut ağırlığı öne kayar.","yonlendirme":"Topuk altına battaniye, ağırlık topuklarda."},"soylenecekler":["Topuklarınız yerde değilse altına katlanmış battaniye koyun.","Dizleriniz ayak parmaklarınızla aynı yöne baksın.","Dirseklerinizle dizlerinizi hafifçe açın ve göğsünüzü kaldırın."],"eller":{"nereye":"Kürek kemiklerinin arası, omurganın iki yanı.","nasil":"Sırta yukarı doğru, göğsün yükselmesine eşlik eden hafif bir yön verin; dizleri ellerle açmayın.","ne_zaman_degil":"İzin yoksa, öğrencide diz ya da ayak bileğinde ağrı varsa veya hamilelikte denge zorlanıyorsa dokunmayın."},"kolay":"Kalçaların altına bir ya da iki blok koyun ve topukların altını battaniyeyle destekleyin.","zor":"Kolları dizlerin içinden geçirip bacakların arkasından bağlayın ya da çömelme içinde hafif bir burgu ekleyin.","dikkat":"Diz yaralanmasında derinliği azaltın ve blok kullanın; dizde ya da kasıkta ağrı varsa öğrencinin doktoruna ya da fizyoterapistine danışmasını önerin.","s":90,"fig":false},{"n":81,"bolum":6,"ad":"Ateş kütüğü (Agnistambhasana)","aile":"Kalça açma","seviye":"Orta","yogunluk":[3,5,7],"calisan":["Erector spinae","Tibialis anterior"],"dengeleyen":["Transversus abdominis","Addüktörler"],"uzayan":["Piriformis","Gluteus medius ve minimus","Gluteus maximus"],"ozet":"İki kaval kemiğinin üst üste yığıldığı oturuş. Kalça dış rotatorları için yoğun bir uzamadır ve dizin korunmasına dikkat ister.","asamalar":{"giris":"Bağdaştan sol kaval kemiğini matın önüne paralel yerleştirin, sağ kaval kemiğini üstüne, sağ ayak bileği sol dizin üstüne gelecek biçimde koyun. Nefes alarak oturma kemiklerine yerleşip omurgayı uzatın.","kalis":"İki ayak da esnek ve aktif, kaval kemikleri üst üste; pelvis dik kalsın. İsterseniz nefes verirken kalçalardan öne eğilin. 8–10 nefes kalın.","cikis":"Nefes alarak gövdeyi dikleştirin, üstteki bacağı elle tutarak kaldırın ve bacakları önde uzatıp diğer tarafa geçin."},"hata":{"ne":"Ayakları gevşek bırakıp ayak bileklerini kıvırmak.","neden":"Ayak gevşek kaldığında bilek yana kıvrılır ve kalçadan gelmesi gereken rotasyon dize ve bileğe aktarılır.","yonlendirme":"Ayaklar esnek, diz güvende."},"soylenecekler":["İki ayağınızın tabanlarını aktif tutun, parmaklarınızı kendinize çekin.","Üstteki diziniz havada kalıyorsa altına blok koyun.","Dizinizde değil, kalçanızın dışında bir his arayın."],"eller":{"nereye":"Üstteki dizin altındaki blok ya da öğrencinin arkasında omurganın iki yanı.","nasil":"Gerekirse bloğu yerleştirin; sırta yalnızca uzama yönünde hafif temas edin, dizlere asla aşağı baskı yapmayın.","ne_zaman_degil":"İzin yoksa, dizde ağrı, menisküs ya da bağ yaralanması öyküsü veya kalça protezi varsa dokunmayın."},"kolay":"Üstteki ayağı alttaki uyluk yerine yere koyup basit bağdaş kurun ya da üstteki dizin altına blok yerleştirin.","zor":"Kaval kemiklerini tam üst üste tutarak kalçalardan öne eğilin ve ön kollara inin.","dikkat":"Diz ya da kalça eklemi yaralanmasında sırtüstü güvercin (4 pozu) ile değiştirin; ağrı varsa öğrencinin doktoruna ya da fizyoterapistine danışmasını önerin.","s":91,"fig":false},{"n":82,"bolum":6,"ad":"İnek yüzü (Gomukhasana)","aile":"Kalça açma","seviye":"Orta","yogunluk":[3,5,6],"calisan":["Rotator manşet","Triceps brachii"],"dengeleyen":["Erector spinae","Transversus abdominis"],"uzayan":["Gluteus medius ve minimus","Tensör fasya lata","Latissimus dorsi"],"ozet":"Dizlerin üst üste yığıldığı bacak pozisyonu ve isteğe bağlı sırt arkası kol bağı. Kalça dışını uzatırken omuz hareketliliğini de çalışır.","asamalar":{"giris":"Dört ayak duruşundan sağ dizi sol dizin önüne çaprazlayın, ayakları iki yana açıp kalçaları ayakların arasına oturtun. Nefes alarak omurgayı uzatın.","kalis":"İki oturma kemiği yerde eşit kalsın, dizler üst üste; kollar sırt arkasında bağlıysa üstteki dirsek tavana baksın. 5–8 nefes kalın.","cikis":"Nefes vererek kolları bırakın, elleri öne koyup dört ayağa gelin ve bacak çaprazını değiştirerek tekrar edin."},"hata":{"ne":"Bir oturma kemiğinin yerden kalkıp pelvisin yana yatması.","neden":"Kalça dışı kısa olduğunda bir taraf yükselir ve omurga yana doğru eğilerek bu dengesizliği telafi eder.","yonlendirme":"İki oturma kemiği yerde, gerekirse blok."},"soylenecekler":["Kalkan oturma kemiğinizin altına bir blok ya da battaniye koyun.","Ellerinize ulaşamıyorsanız aranıza kayış alın.","Göğsünüzü açık tutun, üstteki dirseğiniz başınızı itmesin."],"eller":{"nereye":"Yukarıdaki kolun dirseği ve sırt arkasında kayış tutan eller.","nasil":"Kayışı tutan ellere çok küçük bir yön verin; omzu ya da dirseği arkaya bastırmayın.","ne_zaman_degil":"İzin yoksa, omuzda ağrı ya da instabilite, dizde ağrı veya hamilelik varsa dokunmayın."},"kolay":"Kalçaların altına blok koyun, kolları sırt arkası yerine dizlerin üstünde bırakın.","zor":"Kolları sırt arkasında doğrudan bağlayın ve uzun bir sırtla kalçalardan öne eğilin.","dikkat":"Diz yaralanmasında alttaki bacağı uzun bırakın; omuzda ya da dizde ağrı varsa öğrencinin doktoruna ya da fizyoterapistine danışmasını önerin.","s":92,"fig":false},{"n":83,"bolum":6,"ad":"Kurbağa (Mandukasana)","aile":"Kalça açma","seviye":"İleri","yogunluk":[4,6,8],"calisan":["Transversus abdominis","Serratus anterior"],"dengeleyen":["Erector spinae","Pelvik taban"],"uzayan":["Addüktörler","Gluteus maximus"],"ozet":"Dizlerin geniş açıldığı ve ön kollarda kalınan yoğun iç uyluk uzaması. Kalça hareketliliği gelişmiş öğrenciler içindir ve uzun, kontrollü bir kalış ister.","asamalar":{"giris":"Dört ayak duruşundan dizleri yavaşça yanlara açın, ayak bilekleri dizlerin hizasında kalsın. Nefes vererek ön kollara inin, kalçaları dizlerin hizasına getirin.","kalis":"Bel nötr, karın hafifçe aktif; kalçalar dizlerin ne önünde ne arkasında olsun. Nefesle her verişte bir santim daha bırakarak 5–10 nefes kalın.","cikis":"Nefes alarak ellere yükselin, dizleri tek tek ortaya getirin ve çocuk pozunda dinlenin."},"hata":{"ne":"Beli çukurlaştırıp kalçaları geriye itmek.","neden":"Addüktörler gerildiğinde pelvis öne devrilerek kaçamak arar ve bel omurlarına sıkışma biner.","yonlendirme":"Göbeğinizi hafifçe omurgaya çekin."},"soylenecekler":["Dizlerinizin altına battaniye koyun.","Açılmayı dizlerinizle değil, nefesinizle derinleştirin.","Kasıkta keskin bir his olursa dizlerinizi biraz yaklaştırın."],"eller":{"nereye":"Sakrumun üstü.","nasil":"Sakruma sadece hafif bir sabit temas yaparak belin nötr kalmasını hatırlatın; kalçaları aşağı ya da geri bastırmayın.","ne_zaman_degil":"İzin yoksa, kasıkta zorlanma, diz ağrısı, kalça eklemi sorunu ya da hamilelik varsa dokunmayın."},"kolay":"Dizleri daha az açın, kalçaları biraz geride tutun ve göğsün altına bolster koyun.","zor":"Ön kolları ileri uzatıp göğsü yere yaklaştırın, dizleri kademeli olarak açın.","dikkat":"Kasık ya da kalça eklemi yaralanması öyküsünde dizlerin açısını küçük tutun; ağrı varsa öğrencinin doktoruna ya da fizyoterapistine danışmasını önerin.","s":93,"fig":false},{"n":84,"bolum":6,"ad":"Mutlu bebek (Ananda Balasana)","aile":"Kalça açma","seviye":"Başlangıç","yogunluk":[2,3,4],"calisan":["Latissimus dorsi","Transversus abdominis"],"dengeleyen":["Diyafram","Erector spinae"],"uzayan":["Addüktörler","Hamstringler","Gluteus maximus"],"ozet":"Sırtüstü, dizlerin koltuk altlarına doğru çekildiği oyunbaz kalça açıcı. Bel bölgesini yere yerleştirerek iç uyluk ve kalça arkasını rahatlatır.","asamalar":{"giris":"Sırtüstü yatın, dizleri göğse çekin. Nefes vererek dizleri koltuk altlarına doğru açın, ayak tabanlarını tavana çevirip ayakların dışından tutun.","kalis":"Kaval kemikleri yere dik, ayak bilekleri dizlerin üstünde kalsın; sakrum yere yakın, omuzlar ve baş yerde. İsterseniz hafifçe yana sallanarak 8–10 nefes kalın.","cikis":"Nefes alarak ayakları bırakın, dizleri birleştirip göğse çekin ve ayakları yere indirin."},"hata":{"ne":"Ayakları çekerken sakrum ve başın yerden kalkması.","neden":"Kalça arkası ve iç uyluk kısa olduğunda ayaklara ulaşmak için pelvis yukarı yuvarlanır ve omuzlar yerden kalkar.","yonlendirme":"Önce sakrum yerde, sonra ayaklar."},"soylenecekler":["Ayaklarınıza ulaşamıyorsanız kaval kemiklerinizi ya da uyluk arkalarınızı tutun.","Kuyruk sokumunuzu yere uzatın.","İsterseniz hafifçe sağa sola sallanın, sırtınıza masaj gibi gelsin."],"eller":{"nereye":"Ayak tabanları ya da öğrencinin ayak bileklerinin üstü.","nasil":"Ayakların yere doğru, dizlerin koltuk altlarına doğru gitmesine çok hafif eşlik edin; aşağı bastırmayın.","ne_zaman_degil":"İzin yoksa, kasıkta ya da belde ağrı, kalça protezi veya hamilelik varsa dokunmayın."},"kolay":"Tek bacakla yarım mutlu bebek yapın ya da ayakları kayışla tutun.","zor":"Sakrumu tamamen yerde tutarak dizleri yere daha yakına indirin ve kalışı uzatın.","dikkat":"Hamilelikte sırtüstü süreyi kısa tutun; belde ya da kasıkta ağrı varsa öğrencinin doktoruna ya da fizyoterapistine danışmasını önerin.","s":94,"fig":false},{"n":85,"bolum":6,"ad":"Ardha Matsyendrasana bacakları","aile":"Kalça açma","seviye":"Başlangıç","yogunluk":[2,3,5],"calisan":["Erector spinae","Transversus abdominis"],"dengeleyen":["Addüktörler","Multifidus"],"uzayan":["Piriformis","Gluteus medius ve minimus","Tensör fasya lata"],"ozet":"Ardha Matsyendrasana'nın bacak pozisyonunun burgusuz kullanımı. Gövde merkezde kalırken kalça dışını ve dış uyluğu uzatmayı öğretir; burguya hazırlıktır.","asamalar":{"giris":"Oturup sol bacağı katlayın, sağ ayağı sol dizin dışına basın. Nefes alarak iki elle sağ dizi kucaklayın ve omurgayı uzatın.","kalis":"İki oturma kemiği yerde, gövde öne bakıyor; sağ dizi göğsün ortasına doğru hafifçe çekin. Nefes verirken kalça dışının yumuşamasını izleyerek 8 nefes kalın.","cikis":"Nefes vererek dizi bırakın, bacakları önde uzatın ve diğer tarafa geçmeden önce bacakları hafifçe sallayın."},"hata":{"ne":"Diz çekilirken üstteki kalçanın yerden kalkması.","neden":"Piriformis ve gluteus medius ve minimus kısa olduğunda uzama pelvisin yana yatmasıyla kaçırılır.","yonlendirme":"İki oturma kemiği yerde."},"soylenecekler":["Dizinizi göğsünüzün ortasına doğru yaklaştırın.","Kalçanızın dışında yayılan bir uzama arayın.","Gövdeniz öne baksın; burgu sonra gelecek."],"eller":{"nereye":"Yerden kalkmaya eğilimli kalçanın üst yüzü.","nasil":"Kalçaya çok hafif yere doğru bir yön verin; dizi göğse doğru çekmeyin.","ne_zaman_degil":"İzin yoksa, kalçada ya da dizde ağrı, kalça protezi ya da hamilelik varsa dokunmayın."},"kolay":"Oturma kemiklerinin altına battaniye koyun ve alttaki bacağı uzun bırakın.","zor":"Dizi göğse yaklaştırırken kalçalardan öne eğilin ya da sonraki adımda burguya geçin.","dikkat":"Kalça protezinde bacağı orta hattın ötesine çaprazlamayın; ağrı varsa öğrencinin doktoruna ya da fizyoterapistine danışmasını önerin.","s":95,"fig":false},{"n":86,"bolum":6,"ad":"Kuadriseps esnetmeli alçak hamle","aile":"Kalça açma","seviye":"Orta","yogunluk":[3,5,7],"calisan":["Hamstringler","Gluteus maximus"],"dengeleyen":["Transversus abdominis","Gluteus medius ve minimus"],"uzayan":["Kuadriseps","İliopsoas"],"ozet":"Alçak hamlede arka ayağın elle tutulduğu ve uyluk önünün uzadığı varyasyon. Kalça fleksörleri ile kuadrisepsi birlikte uzatarak geriye eğilmelere hazırlar.","asamalar":{"giris":"Sağ ayak önde alçak hamleye gelin, arka dizin altına battaniye koyun. Nefes vererek arka dizi bükün ve sol eli sol ayağa uzatın.","kalis":"Pelvis hafifçe geriye yuvarlansın, kuyruk sokumu yere uzansın; topuğu kalçaya zorlamadan çekin. 5 nefes kalın.","cikis":"Nefes alarak ayağı yavaşça bırakın, iki eli öndeki ayağın yanına koyun ve diğer tarafa geçin."},"hata":{"ne":"Ayağı çekerken beli çukurlaştırmak.","neden":"Kuadriseps ve iliopsoas kısa olduğunda pelvis öne devrilir ve uzama kalça yerine belden alınır.","yonlendirme":"Kuyruk sokumu aşağı, sonra ayak."},"soylenecekler":["Arka dizinizi yumuşak bir desteğe bırakın.","Göbeğinizi hafifçe içe çekin, beliniz uzun kalsın.","Ayağınıza ulaşamıyorsanız kayış kullanın."],"eller":{"nereye":"Arka kalçanın üst yüzü ya da tutulan ayağın üstündeki kayış.","nasil":"Pelvise sadece nötr kalma hatırlatması yapın; topuğu kalçaya doğru bastırmayın.","ne_zaman_degil":"İzin yoksa, arka dizde ağrı, kuadriseps zorlanması, bel hassasiyeti ya da hamilelik varsa dokunmayın."},"kolay":"Arka ayağa kayış takın ve öndeki elle bloğa dayanın.","zor":"Kalçayı öne yerleştirip ayağı aynı taraftaki elle omuz üstünden tutun ve göğsü açın.","dikkat":"Diz yaralanmasında arka dizi iyi destekleyin veya ayağı tutmayın; ağrı varsa öğrencinin doktoruna ya da fizyoterapistine danışmasını önerin.","s":96,"fig":false},{"n":87,"bolum":6,"ad":"Skandasana","aile":"Kalça açma","seviye":"Orta","yogunluk":[3,5,7],"calisan":["Kuadriseps","Gluteus maximus"],"dengeleyen":["Addüktörler","Transversus abdominis","Tibialis anterior"],"uzayan":["Addüktörler","Hamstringler"],"ozet":"Geniş duruşta bir dize çömelirken diğer bacağın düz uzandığı yan hamle. Kalçanın yanal hareketliliğini, iç uyluğu ve bacak kuvvetini birlikte çalışır.","asamalar":{"giris":"Geniş bir duruşta ayakları hafifçe dışa açın. Nefes vererek sağ dizi bükün, kalçayı sağ topuğa doğru indirin ve sol bacağı ayak parmakları tavana bakacak biçimde uzatın.","kalis":"Bükülü dizin topuğu yerde ve diz ayak parmaklarıyla aynı yönde kalsın; göğüs yükselsin, eller göğüste ya da yerde. 3–5 nefes kalın.","cikis":"Nefes alarak bükülü bacağın topuğuyla yeri itip merkeze yükselin, ayakları paralel getirin ve diğer tarafa geçin."},"hata":{"ne":"Bükülü dizin içe çökmesi ve topuğun kalkması.","neden":"Kalça dış rotatorları ve ayak bileği hareketliliği yetersizken derin çömelmede diz içe kayar.","yonlendirme":"Diz parmakların yönünde, topuk yerde."},"soylenecekler":["Önce sadece yarıya kadar inin; derinlik sonra gelir.","Ellerinizi yere ya da bloğa koyarak dengeyi koruyun.","Uzun bacağınızın ayak parmakları tavana baksın."],"eller":{"nereye":"Bükülü bacağın dizinin dış yanı ve kalçanın arka yüzü.","nasil":"Dize dışa doğru hafif bir yön verin; öğrenciyi daha derine indirmek için bastırmayın.","ne_zaman_degil":"İzin yoksa, dizde ya da kasıkta ağrı, denge sorunu ya da hamilelik varsa dokunmayın."},"kolay":"Elleri bloklara koyun ve sadece yarım derinlikte kalın; topuğun altına battaniye yerleştirin.","zor":"Elleri göğüs önünde birleştirip destek olmadan inin ve nefesle bir yandan diğerine akın.","dikkat":"Diz yaralanması ya da kasık zorlanması öyküsünde derinliği sınırlayın; ağrı varsa öğrencinin doktoruna ya da fizyoterapistine danışmasını önerin.","s":97,"fig":false},{"n":88,"bolum":6,"ad":"Kapı (Parighasana)","aile":"Kalça açma","seviye":"Başlangıç","yogunluk":[2,4,5],"calisan":["Oblikler","Gluteus medius ve minimus"],"dengeleyen":["Quadratus lumborum","Transversus abdominis"],"uzayan":["Latissimus dorsi","Addüktörler","Hamstringler"],"ozet":"Bir diz yerde, diğer bacak yana uzanmışken yapılan yan eğilme. Gövdenin yan hattını ve iç uyluğu uzatır; nefesin kaburgalar arasına yayılmasını hissettirir.","asamalar":{"giris":"Dizler üzerinde durun, sağ bacağı yana uzatıp ayağı yere basın. Nefes alarak sol kolu yukarı kaldırın, nefes vererek sağ bacağa doğru yana eğilin.","kalis":"Kalça yerdeki dizin üstünde dik kalsın, göğüs öne değil yana açılsın; üstteki kola doğru kaburgalara nefes alın. 5 nefes kalın.","cikis":"Nefes alarak üst kolla gövdeyi kaldırın, uzun bacağı geri getirin ve iki diz üzerinde bir nefes bekleyip diğer tarafa geçin."},"hata":{"ne":"Kalçaları geriye itip gövdeyi öne kapatmak.","neden":"Yan beden ve iç uyluk kısa olduğunda yan eğilme yerine kalça bükülür ve gövde öne düşer.","yonlendirme":"Kalça dizin üstünde, göğüs yana açık."},"soylenecekler":["Yerdeki dizinizin altına battaniye koyun.","Kalçanızı biraz öne itin ve gövdenizi iki cam arasında düşünün.","Üst kolunuzu uzun tutun, omzunuz kulağınızdan uzak kalsın."],"eller":{"nereye":"Yerdeki dizin tarafında kalçanın yanı ve üst kolun dirseği.","nasil":"Kalçaya dizin üstüne gelmesi için hafif bir yön verin; üst kola sadece uzama hissi verin, aşağı çekmeyin.","ne_zaman_degil":"İzin yoksa, dizde ağrı, omuzda yaralanma ya da hamilelik varsa dokunmayın."},"kolay":"Uzun bacağın dizini hafifçe bükün ve üst eli belde bırakın.","zor":"Uzun bacağın ayağını yere düz basın, üst kolu başın üstünden uzun bacağa doğru uzatıp avuçları birleştirin.","dikkat":"Diz hassasiyetinde dizin altına çift battaniye koyun; ağrı varsa öğrencinin doktoruna ya da fizyoterapistine danışmasını önerin.","s":98,"fig":false},{"n":89,"bolum":6,"ad":"Burgulu kertenkele","aile":"Kalça açma","seviye":"Orta","yogunluk":[3,5,7],"calisan":["Oblikler","Kuadriseps"],"dengeleyen":["Serratus anterior","Transversus abdominis","Gluteus medius ve minimus"],"uzayan":["İliopsoas","Addüktörler","Büyük ve küçük pektoral"],"ozet":"Kertenkele pozunda göğsün öndeki bacağa doğru açıldığı varyasyon. Kalça açılmasına göğüs rotasyonu ekleyerek dersin bu bölümünde bütünleştirici bir pozdur.","asamalar":{"giris":"Sağ ayak sağ elin dışında kertenkele pozuna gelin, arka diz yerde. Nefes alarak sağ eli yerden kaldırın, nefes vererek göğsü sağa açın ve sağ kolu tavana uzatın.","kalis":"Sol el yeri iterek omzu kulaktan uzaklaştırsın, öndeki diz bileğin üstünde kalsın; dönüş göğüsten gelsin. 5 nefes kalın.","cikis":"Nefes vererek sağ eli yere indirin, kertenkeleye geri gelin ve arka ayak parmaklarını kıvırarak aşağı bakan köpeğe dönün."},"hata":{"ne":"Göğsü açarken öndeki dizin içe kapanması.","neden":"Gövde dönerken öndeki kalçanın dış rotatorları gevşerse diz ayakla birlikte içe kayar.","yonlendirme":"Diz dışa, göğüs yukarı."},"soylenecekler":["Destek elinizi blokta tutabilirsiniz.","Öndeki dizinizi kendi omzunuza doğru hafifçe dışa açın.","Göğsünüzü üst elinize doğru açın, beliniz sakin kalsın."],"eller":{"nereye":"Öndeki dizin iç yanı ve üst kolun omuz başı.","nasil":"Dize dışa doğru çok hafif bir yön verin; omzu geriye çekmeyin, sadece açılma yönünü gösterin.","ne_zaman_degil":"İzin yoksa, kasıkta zorlanma, dizde ya da omuzda ağrı veya hamilelik varsa dokunmayın."},"kolay":"Destek elini yüksek bloğa koyun ve üst eli öndeki dizin üstünde bırakarak sadece göğsü çevirin.","zor":"Arka dizi bükün ve üstteki elle arka ayağı tutarak burgulu kuadriseps uzaması ekleyin.","dikkat":"Kalça eklemi ya da diz yaralanmasında derinliği sınırlayın; ağrı varsa öğrencinin doktoruna ya da fizyoterapistine danışmasını önerin.","s":99,"fig":false},{"n":90,"bolum":6,"ad":"Dizler açık çocuk pozu","aile":"Restoratif","seviye":"Başlangıç","yogunluk":[1,2,3],"calisan":["Diyafram","Pelvik taban"],"dengeleyen":["Erector spinae","Addüktörler"],"uzayan":["Addüktörler","Latissimus dorsi","Erector spinae"],"ozet":"Dizlerin geniş açıldığı ve gövdenin aralarına uzandığı dinlenme pozu. İç uyluğu nazikçe uzatırken nefesin sırta yayılmasını hissettirir; diziler arasında dinlenme için kullanılır.","asamalar":{"giris":"Dizler üzerinde durun, başparmakları birleştirip dizleri mat genişliğine açın. Nefes vererek kalçaları topuklara doğru indirin ve kolları önde uzatıp alnı yere bırakın.","kalis":"Kalçalar topuklara yaklaşsın, omuzlar rahat, alın yerde ya da blokta; nefes alırken sırtın genişlediğini izleyin. 1–3 dakika kalın.","cikis":"Nefes alarak elleri omuzların altına yürütün, omurgayı yavaşça yuvarlayarak doğrulun ve dizleri birleştirin."},"hata":{"ne":"Kalçalar topuklara değmeyince omuzları ve boynu sıkmak.","neden":"Kalça ya da diz fleksiyonu kısıtlı olduğunda ağırlık öne kayar ve omuzlar ile boyun gövdeyi taşımaya başlar.","yonlendirme":"Alnın ve kalçanın altına destek, omuzlar bıraksın."},"soylenecekler":["Alnınızın altına blok koyun, boynunuz tamamen dinlensin.","Her nefes alışta sırtınızın genişlediğini hissedin.","Kalçalarınız topuklarınıza değmiyorsa aralarına battaniye koyun."],"eller":{"nereye":"Sakrumun üstü ya da bel bölgesinin iki yanı.","nasil":"Avuçla sakruma geriye ve aşağıya doğru, nefes verişle birlikte çok hafif bir ağırlık bırakın; asla bastırmayın.","ne_zaman_degil":"İzin yoksa, dizde ağrı, belde hassasiyet ya da hamilelik varsa veya öğrenci yüzüstü dokunulmaktan rahatsızsa dokunmayın."},"kolay":"Gövdenin altına uzunlamasına bolster, kalçalarla topuklar arasına battaniye koyun.","zor":"Kolları sağa yürütüp gövdenin sol yan hattını uzatın, sonra sola geçin.","dikkat":"Diz hassasiyetinde dizlerin arkasına katlanmış battaniye koyun; hamilelikte dizleri karnın sığacağı kadar açın; ağrı varsa öğrencinin doktoruna ya da fizyoterapistine danışmasını önerin.","s":100,"fig":false},{"n":91,"bolum":7,"ad":"Duvara bacaklar (Viparita Karani)","aile":"Ters duruş","seviye":"Başlangıç","yogunluk":[1,2,3],"calisan":["Diyafram","Kuadriseps"],"dengeleyen":["Transversus abdominis","Pelvik taban"],"uzayan":["Hamstringler","Gastroknemius ve soleus"],"ozet":"Bacakların duvara yaslandığı, kalbin kalçalardan biraz yüksekte kaldığı hafif bir ters duruştur. Dersin sonunda tempoyu düşürmek ve öğrencilere nefesi gözlemleme alanı açmak için kullanılır.","asamalar":{"giris":"Bir kalçanızı duvara yaslayarak yan oturun; nefes vererek sırtüstü dönün ve bacakları duvar boyunca yukarı kaldırın. Oturma kemikleri duvara yakın, omurga yerde uzun kalır.","kalis":"Pelvis yere eşit ağırlık verir, bel doğal kavisini korur, kollar yanlarda gevşektir. Burundan yavaş nefes alıp verin; 3 ila 10 dakika kalın.","cikis":"Nefes vererek dizleri bükün, ayak tabanlarını duvara basın ve sağ yana yuvarlanın. Birkaç nefes yan yatarak bekleyin, sonra ellerle itip yavaşça oturun."},"hata":{"ne":"Hamstringler kısayken kalçaları duvara yapıştırmaya çalışmak.","neden":"Arka bacak gerginliği pelvisi geriye devirir ve bel düzleşerek sıkışır.","yonlendirme":"Kalçayı bir karış geri alın, bel yerde yumuşasın."},"soylenecekler":["Duvar bacaklarınızı taşısın, siz sadece nefesi izleyin.","Dizlerde hafif bir bükülme serbest; burada esneme aramıyoruz.","Her nefes verişte omuzlar yere biraz daha yerleşsin."],"eller":{"nereye":"Öğrencinin ayak bileklerinin hemen üstüne, bacakların duvara değdiği yere.","nasil":"Bacakları duvara doğru çok hafifçe yönlendirin ya da yalnızca yerleştirme amacıyla dokunun; aşağı bastırmayın.","ne_zaman_degil":"Onay alınmadıysa, öğrenci bacaklarda karıncalanma ya da baskı hissi bildirdiyse veya ileri hamilelikte sırtüstü yatmakta zorlanıyorsa dokunmayın."},"kolay":"Kalçaları duvardan uzaklaştırın ve dizleri bükerek ayak tabanlarını duvara basın; başın altına ince bir battaniye koyun.","zor":"Bacakları duvarda geniş bir V şeklinde açın ya da ayak tabanlarını birleştirerek bağlı açıya geçin.","dikkat":"İleri hamilelikte sırtüstü kalış rahatsızlık veriyorsa yan yatışa geçin. Göz içi basıncıyla ilgili bir durum, kontrolsüz yüksek tansiyon ya da reflü varsa süreyi kısa tutun ve öğrencinin doktoruna danışmasını önerin. Bacaklarda uyuşma olursa dizleri bükün.","s":102,"fig":false},{"n":92,"bolum":7,"ad":"Yunus (Ardha Pincha Mayurasana)","aile":"Ters duruş","seviye":"Orta","yogunluk":[3,5,6],"calisan":["Deltoid","Serratus anterior","Rotator manşet"],"dengeleyen":["Transversus abdominis","Orta ve alt trapezius"],"uzayan":["Hamstringler","Latissimus dorsi","Gastroknemius ve soleus"],"ozet":"Ön kollar üzerinde yapılan, aşağı bakan köpeğe benzer yarım ters duruştur. Omuz kuşağında güç ve stabilite kurarak ön kol duruşu ile baş duruşu hazırlığına zemin hazırlar.","asamalar":{"giris":"Dört ayak pozisyonunda ön kolları omuz genişliğinde yere koyun, dirsekler omuzların altında olsun. Nefes vererek ayak parmaklarını kıvırıp kalçaları yukarı ve geri kaldırın.","kalis":"Ön kollar yere basar, göğüs kafesi ön kollardan uzaklaşır, omurga kuyruk sokumundan başın tepesine uzanır. Baş yerden yukarıda, boyun serbest; 5 ila 8 nefes kalın.","cikis":"Nefes vererek dizleri yere indirin ve çocuk pozunda alnınızı dinlendirin."},"hata":{"ne":"Omuzların kulaklara çökmesi ve göğsün ön kollara doğru düşmesi.","neden":"Serratus anterior ve alt trapezius yeterince devreye girmediğinde kürek kemikleri sırtta yukarı kayar.","yonlendirme":"Yeri itin, göğsü dizlere doğru taşıyın."},"soylenecekler":["Ön kollarınızla yeri aktif olarak itin, sanki yerden uzaklaşıyormuş gibi.","Sırt uzun kalsın diye dizleri dilediğiniz kadar bükün.","Başınız yerden yukarıda, boynunuz rahat; bakış ayaklara doğru."],"eller":{"nereye":"Kürek kemiklerinin dış kenarına, koltuk altının hemen arkasına.","nasil":"Kürek kemiklerini hafifçe bele doğru ve dışa yönlendirerek sözlü ipucunu destekleyin; ağırlık vermeyin.","ne_zaman_degil":"Onay yoksa, omuzda ağrı ya da instabilite bildiriliyorsa, ileri hamilelikte veya baş yere düşüyorsa dokunmak yerine öğrenciyi dizlere indirin."},"kolay":"Dizleri yerde bırakarak sadece kalçayı kaldırın ya da ellerin arasına bir blok koyup başparmaklarla tutun.","zor":"Ayakları ön kollara doğru birkaç adım yürütün veya bir bacağı kalça hizasına kaldırın.","dikkat":"Omuz, boyun ya da dirsek sorunlarında bloklu varyasyona geçin. Baş kalpten aşağıda kaldığı için göz içi basıncıyla ilgili bir durum ya da kontrolsüz yüksek tansiyon varsa kalışı kısa tutun ve öğrencinin doktoruna danışmasını önerin. Hamilelikte uygunluğu öğrencinin doktoruyla birlikte değerlendirin.","s":103,"fig":false},{"n":93,"bolum":7,"ad":"Plank (Phalakasana)","aile":"Kol dengesi","seviye":"Başlangıç","yogunluk":[3,5,6],"calisan":["Rektus abdominis","Transversus abdominis","Serratus anterior","Triceps brachii"],"dengeleyen":["Gluteus maximus","Kuadriseps","Deltoid"],"uzayan":[],"ozet":"Vücudun ellerden topuklara tek bir çizgi oluşturduğu temel destek pozudur. Gövde stabilitesini ve kollar üzerinde ağırlık taşımayı öğretir; Chaturanga ve kol dengeleri için temeldir.","asamalar":{"giris":"Aşağı bakan köpekten nefes alarak omuzları bileklerin üzerine getirin. Kalçaları omuz ve topuk hizasına indirin, eller omuz genişliğinde olsun.","kalis":"Kuyruk sokumu topuklara uzanır, kaburgalar içeri toplanır, bel çukurlaşmaz. Ensenin arkası uzun, bakış ellerin biraz önünde; düzenli nefesle 5 ila 10 nefes kalın.","cikis":"Nefes vererek dizleri yere indirin ya da kalçaları geri iterek aşağı bakan köpeğe dönün."},"hata":{"ne":"Kalçaların sarkması ve belin çökmesi.","neden":"Karın duvarı ve gluteal kaslar yorulunca pelvis öne devrilir ve yük bel omurlarına biner.","yonlendirme":"Göbek omurgaya, topuklar geriye."},"soylenecekler":["Ellerden topuklara uzun bir tahta gibi olun.","Yeri itin, kürek kemikleri arasında boşluk yaratın.","Nefesi tutmayın; nefes verirken karnı biraz daha toplayın."],"eller":{"nereye":"Sakrumun üzerine ya da kürek kemiklerinin arasına, avuç düz.","nasil":"Sakrum hizasını göstermek için avucu yalnızca referans olarak koyun; öğrenci kalçayı avucunuza doğru kendi kaldırsın ya da indirsin.","ne_zaman_degil":"Onay yoksa, bilekte ya da omuzda ağrı bildiriliyorsa veya hamilelikte karın duvarında ayrılma belirtisi gözlemleniyorsa dokunmayın ve dizleri yere indirmesini önerin."},"kolay":"Dizleri yere koyarak yarım plank yapın ya da elleri bir sıranın veya duvarın üzerine yerleştirin.","zor":"Bir bacağı kalça hizasına kaldırın veya omuzları bileklerin biraz önüne taşıyın.","dikkat":"Bilek hassasiyetinde ön kol plankını tercih edin ya da avuç altına katlanmış mat koyun. Hamilelikte ve doğum sonrası dönemde karın baskısına dikkat edin; gerekirse duvar varyasyonuna geçin ve öğrencinin doktoruna ya da fizyoterapistine danışmasını önerin.","s":104,"fig":true},{"n":94,"bolum":7,"ad":"Chaturanga (Chaturanga Dandasana)","aile":"Kol dengesi","seviye":"Orta","yogunluk":[5,7,8],"calisan":["Triceps brachii","Büyük ve küçük pektoral","Serratus anterior","Deltoid"],"dengeleyen":["Rektus abdominis","Transversus abdominis","Gluteus maximus"],"uzayan":[],"ozet":"Planktan dirsekler bükülerek vücudun yere paralel indirildiği güç pozudur. Akışlarda en sık tekrarlanan geçiş olduğu için omuz başını koruyan hizalamayı öğretmek kritik önemdedir.","asamalar":{"giris":"Plankta omuzları bileklerin biraz önüne taşıyın. Nefes vererek dirsekleri geriye, gövdeye yakın bükün ve vücudu tek parça hâlinde indirin.","kalis":"Dirsekler bileklerin üzerinde, omuzlar dirsek hizasında ya da biraz yukarıda kalır; göğüs geniş, bel çökmez. 1 ila 3 nefes kalın.","cikis":"Nefes alarak yukarı bakan köpeğe ya da kobraya geçin veya dizleri ve göğsü yere indirin."},"hata":{"ne":"Omuzları dirsek hizasının altına düşürmek.","neden":"Triceps ve serratus anterior yorulduğunda omuz başı öne yuvarlanır ve yük omuzun önüne biner.","yonlendirme":"Omuzlar dirsek hizasında durur, daha aşağı değil."},"soylenecekler":["Yarıya kadar inin; daha aşağısı burada daha iyi değil.","Dirsekler kaburgaları sıyırarak geriye gitsin.","Göğüs ileri, bakış ellerin biraz önüne."],"eller":{"nereye":"Omuz başının önüne, köprücük kemiğinin hemen dışına.","nasil":"İki parmakla omuz başını hafifçe yukarı yönlendirerek omuzların dirsek hizasında kalacağı yeri işaret edin; ağırlığı taşımayın.","ne_zaman_degil":"Onay yoksa, omuz ya da bilek ağrısı varsa, hamilelikte veya öğrenci hareket hâlindeyken dokunmayın; sözlü ipucu verin."},"kolay":"Dizleri yere koyarak inin ya da göğsün altına bir blok ya da bolster koyun.","zor":"Kalışı 5 nefese çıkarın veya bir bacağı yerden kaldırarak inin.","dikkat":"Omuz önünde ağrı, bilek sorunları ya da omuz cerrahisi geçmişinde dizler yerde varyasyonla başlayın ve öğrencinin fizyoterapistine danışmasını önerin. Hamilelikte karın baskısı nedeniyle dizler yerde veya duvarda varyasyon tercih edin.","s":105,"fig":false},{"n":95,"bolum":7,"ad":"Ön kol plankı","aile":"Kol dengesi","seviye":"Başlangıç","yogunluk":[3,5,6],"calisan":["Transversus abdominis","Rektus abdominis","Serratus anterior"],"dengeleyen":["Deltoid","Gluteus maximus","Kuadriseps"],"uzayan":[],"ozet":"Ağırlığın ön kollara dağıldığı, bilekleri yüklemeden gövde gücü çalışılan plank varyasyonudur. Bilek hassasiyeti olan öğrenciler için iyi bir alternatif ve yunus pozuna hazırlıktır.","asamalar":{"giris":"Ön kolları yere koyun, dirsekler omuzların altında olsun. Nefes vererek bacakları geriye uzatıp ayak parmaklarını kıvırın ve kalçaları omuz hizasına getirin.","kalis":"Ön kollar yeri iter, kürek kemikleri sırtta geniş kalır, pelvis nötrdür. Boyun omurganın devamı; 5 ila 10 nefes ya da 20 ila 40 saniye kalın.","cikis":"Nefes vererek dizleri yere indirin ve çocuk pozunda dinlenin."},"hata":{"ne":"Kalçaları yukarı kaldırıp yükten kaçmak.","neden":"Karın kasları yorulduğunda vücut kalçaları kaldırarak gövdedeki kaldıraç kolunu kısaltır.","yonlendirme":"Kalça omuz hizasına, kuyruk sokumu topuklara."},"soylenecekler":["Dirsekleri birbirine doğru, ön kolları dışa doğru çekiyormuş gibi kucaklayın.","Göğsünüzü yerden uzaklaştırın, sırt çökmesin.","Nefes verirken göbek bölgesini hafifçe içeri toplayın."],"eller":{"nereye":"Kalçanın en üst noktasına ya da sakruma, avuç düz.","nasil":"Avucu yükseklik referansı olarak tutun; öğrenci kalçayı kendi ayarlasın, aşağı bastırmayın.","ne_zaman_degil":"Onay yoksa, bel ağrısı bildiriliyorsa veya hamilelikte karın baskısı hissediliyorsa dokunmayın; dizleri yere indirmesini önerin."},"kolay":"Dizleri yerde bırakın ya da ön kolları bir sandalye oturağına koyarak eğik yapın.","zor":"Kalçaları sağa sola hafifçe döndürün veya bir bacağı kaldırarak 3 nefes kalın.","dikkat":"Omuz sorunlarında kalışı kısa tutun. Hamilelikte ve doğum sonrası dönemde karın baskısına dikkat edin, eğik varyasyonu tercih edin ve gerekirse öğrencinin doktoruna ya da fizyoterapistine danışmasını önerin. Nefesi tutmaktan kaçının.","s":106,"fig":false},{"n":96,"bolum":7,"ad":"Destekli omuz duruşu (Salamba Sarvangasana)","aile":"Ters duruş","seviye":"İleri","yogunluk":[4,6,7],"calisan":["Erector spinae","Triceps brachii","Rektus abdominis"],"dengeleyen":["Gluteus maximus","Transversus abdominis","Rotator manşet"],"uzayan":["Üst trapezius"],"ozet":"Ağırlığın omuzlar ve üst kollar üzerinde taşındığı, bacakların dikey uzandığı ters duruştur. Boynu koruyan battaniye kurulumu ve sakin giriş-çıkış, pozun kendisi kadar önemlidir.","asamalar":{"giris":"Omuzlar katlanmış battaniyelerin kenarında, baş yerde olacak şekilde sırtüstü uzanın. Nefes vererek dizleri göğse çekin, kalçaları kaldırın ve ellerle sırtı destekleyin; bacakları tek tek yukarı uzatın.","kalis":"Ağırlık omuzlarda ve üst kollarda, boyunda değil; ense ile yer arasında küçük bir boşluk kalır. Bakış göğse sabit, nefes yumuşak; 5 ila 15 nefes kalın.","cikis":"Nefes vererek dizleri alna doğru bükün, elleri yere alın ve omurgayı omur omur, kontrollü biçimde yere indirin. Başı kaldırmadan birkaç nefes sırtüstü kalın."},"hata":{"ne":"Pozdayken başı çevirmek.","neden":"Ağırlık altındaki boyun omurları döndürüldüğünde boyun yapıları korunmasız biçimde yüklenir.","yonlendirme":"Boyun sabit, bakış sabit."},"soylenecekler":["Pozdayken başınızı hiç çevirmeyin; bakış göğsünüzde kalsın.","Ağırlık omuzlarda; boynunuzda baskı hissederseniz hemen inin.","Elleri sırtınızda kürek kemiklerine doğru yürütün, dirsekler omuz genişliğinde."],"eller":{"nereye":"Kurulum aşamasında battaniyelerin ve omuzların konumuna; pozda gerekirse yalnızca öğrencinin dirseklerinin dış yanına.","nasil":"Dirseklerin açılmasını önlemek için çok hafif bir içe yönlendirme yapın; bacakları yukarı çekmeyin, gövdeye ağırlık vermeyin ve öğrenciyi asla daha dik bir hizaya zorlamayın.","ne_zaman_degil":"Onay yoksa, boyun ağrısı ya da boyun sorunu geçmişi varsa, hamilelikte, öğrenci titriyor ya da nefesini tutuyorsa dokunmayın; yerine güvenli bir çıkış ya da duvara bacaklar önerin."},"kolay":"Duvara bacaklar pozunu ya da sakrumun altında blokla destekli köprüyü uygulayın; bir sonraki adım olarak ayakları duvara basan yarım omuz duruşu.","zor":"Bacakları açarak ya da bağlı açı formuna getirerek varyasyon yapın; yalnızca kurulum sağlam ve boyunda baskı yoksa.","dikkat":"Boyun sorunları, göz içi basıncıyla ilgili durumlar (ör. glokom), kontrolsüz yüksek tansiyon, kulak veya sinüs basıncı ve reflüde uygulamayın ya da öğrencinin doktoruna danışmasını önerin. Hamilelikte ters duruşa yeni başlanmaz; deneyimli öğrenci için de doktor onayı esastır. Battaniyesiz, düz zeminde boynu zorlamayın; menstrüasyon döneminde uygulayıp uygulamamak öğrencinin tercihidir.","s":107,"fig":true},{"n":97,"bolum":7,"ad":"Saban (Halasana)","aile":"Ters duruş","seviye":"İleri","yogunluk":[4,6,8],"calisan":["Rektus abdominis","Triceps brachii","Kuadriseps"],"dengeleyen":["Rotator manşet","Transversus abdominis"],"uzayan":["Hamstringler","Erector spinae","Üst trapezius"],"ozet":"Omuz duruşundan ayakların başın arkasındaki zemine indirildiği ters duruş ve öne eğilmedir. Arka zincirin tamamını uzatır; boynun nötr kalması için sabır ve destek gerektirir.","asamalar":{"giris":"Omuzlar battaniyelerin kenarında sırtüstü uzanın. Nefes vererek kalçaları omuzların üzerine kaldırın, ellerle sırtı destekleyin ve düz bacakları ayak parmakları yere ya da bir desteğe değene kadar başın arkasına indirin.","kalis":"Kalçalar omuzların üzerinde, omurga uzun, ağırlık omuzlarda kalır. Boğaz yumuşak, bakış göğse sabit; nefes sığlaşırsa ayakları desteğe alın. 5 ila 10 nefes kalın.","cikis":"Elleri yere koyun, nefes vererek dizleri bükün ve omurgayı yavaşça yuvarlayarak yere indirin. Başı kaldırmadan dinlenin."},"hata":{"ne":"Ayaklar yere ulaşsın diye ağırlığı boyna yüklemek.","neden":"Hamstringler ve sırt kasları kısa olduğunda gövde boyun yönüne doğru yuvarlanır ve boyun aşırı bükülür.","yonlendirme":"Ayaklar desteğe, ağırlık omuzlara."},"soylenecekler":["Ayaklarınızın yere değmesi gerekmiyor; sandalye ya da blok burada.","Başınızı hiç çevirmeyin, bakış göğsünüzde.","Boğazda baskı varsa dizleri bükün ya da çıkın."],"eller":{"nereye":"Pozu kurmadan önce sandalye ya da bloğun yerleşimine; pozda öğrencinin bedenine dokunmadan yanında durun.","nasil":"Ayakların altına desteği yerleştirin veya mesafesini ayarlayın; bacakları ya da kalçaları asla aşağı veya ileri bastırmayın.","ne_zaman_degil":"Boyun ağrısı ya da sorunu, hamilelik, bel fıtığı geçmişi bildiriliyorsa, nefes zorlanıyorsa ya da onay yoksa hiç dokunmayın."},"kolay":"Ayakları başın arkasındaki bir sandalyenin oturağına koyun ya da duvara bacaklar pozunda kalın.","zor":"Dizleri kulakların yanına indirerek kulak basınç pozuna geçin; yalnızca boyunda hiçbir baskı yoksa.","dikkat":"Boyun sorunları, göz içi basıncıyla ilgili durumlar, kontrolsüz yüksek tansiyon, reflü ve bel diski sorunlarında uygulamayın veya öğrencinin doktoruna danışmasını önerin. Hamilelikte uygulanmaz. Battaniye desteği olmadan ve dolu mideyle yapmayın.","s":108,"fig":false},{"n":98,"bolum":7,"ad":"Baş duruşu hazırlığı (Salamba Sirsasana)","aile":"Ters duruş","seviye":"Orta","yogunluk":[4,6,7],"calisan":["Deltoid","Serratus anterior","Rektus abdominis"],"dengeleyen":["Transversus abdominis","Rotator manşet","Orta ve alt trapezius"],"uzayan":["Hamstringler"],"ozet":"Ön kollar ve başın tepesi zemindeyken kalçaların omuzların üzerine taşındığı, ayakların yerde kaldığı hazırlık aşamasıdır. Amaç ağırlığı ön kollarda taşımayı ve boynu yüklememeyi öğretmektir.","asamalar":{"giris":"Dirsekleri omuz genişliğinde yere koyun, parmakları kenetleyip başın tepesini avuçların önüne yerleştirin. Nefes alarak dizleri kaldırın, ayakları omuzlara doğru küçük adımlarla yaklaştırın.","kalis":"Ön kollar güçlü biçimde yeri iter, omuzlar kulaklardan uzaklaşır, boyun uzun ve nötrdür. Başta yük hafif, kollarda ağır olmalı; 3 ila 5 nefes kalın.","cikis":"Nefes vererek dizleri yere indirin, başı kaldırmadan önce birkaç nefes çocuk pozunda dinlenin."},"hata":{"ne":"Ağırlığı başa bırakıp omuzları çökertmek.","neden":"Omuz kuşağı yeterince aktif olmadığında beden yükü boyun omurlarına aktarır.","yonlendirme":"Ön kollarla itin, başta tüy kadar ağırlık."},"soylenecekler":["Başınızın altından bir kâğıt kayabilecek kadar ağırlığı kollarınıza alın.","Ayakları yürütürken kalçalar omuzların üzerine gelsin, bacakları zıplatmayın.","Boyunda baskı hissederseniz hemen dizleri indirin."],"eller":{"nereye":"Öğrencinin yanında, kalçanın yan kısmına yakın; gerekirse yalnızca pelvisin yan tarafına.","nasil":"Dengeyi kaybederse düşmesini önleyecek kadar sabit bir el koyun; kalçayı yukarı kaldırmayın, bacakları havaya çekmeyin.","ne_zaman_degil":"Onay yoksa, boyun ağrısı ya da sorunu varsa, hamilelikte, baş dönmesi bildiriliyorsa veya öğrenci ağırlığı başa veriyorsa dokunmayın; pozu bitirmesini isteyin."},"kolay":"Başı yere koymadan yunus pozunda çalışın; ağırlık tamamen ön kollarda kalsın.","zor":"Duvar önünde, dizleri göğse çekip bir an tutabilecek kadar kalçayı omuzların üzerine taşıyın; bacakları sallamadan.","dikkat":"Boyun sorunları, göz içi basıncıyla ilgili durumlar (ör. glokom), kontrolsüz yüksek tansiyon, baş ağrısı ve reflüde uygulamayın veya öğrencinin doktoruna danışmasını önerin. Hamilelikte yeni başlanmaz. Sert zeminde değil, katlanmış mat üzerinde çalışın; asla zorlamayın.","s":109,"fig":false},{"n":99,"bolum":7,"ad":"Ön kol duruşu hazırlığı (Pincha Mayurasana)","aile":"Ters duruş","seviye":"İleri","yogunluk":[5,7,8],"calisan":["Deltoid","Serratus anterior","Rotator manşet"],"dengeleyen":["Transversus abdominis","Rektus abdominis","Gluteus maximus"],"uzayan":["Latissimus dorsi"],"ozet":"Duvar önünde ön kollar üzerinde bir bacağın yukarı uzatıldığı, ön kol duruşuna giden hazırlıktır. Omuzlarda açıklık ve gövdede kontrol gerektirir; baş yere değmez.","asamalar":{"giris":"Duvara bakan yunus pozunda parmak uçları duvardan bir karış uzakta olsun. Ayakları yaklaştırıp nefes alarak bir bacağı yukarı uzatın.","kalis":"Dirsekler omuz genişliğinde kalır, omuzlar dirseklerin üzerine yığılır, baş yerden yukarıda. Kaburgalar içeri toplanır; 3 ila 5 nefes kalın ve bacak değiştirin.","cikis":"Nefes vererek kaldırdığınız bacağı yere indirin, dizleri yere koyup çocuk pozunda dinlenin."},"hata":{"ne":"Dirseklerin dışa kayması.","neden":"Omuz eklemi sınırlı olduğunda kollar ağırlık altında açılarak yer arar.","yonlendirme":"Dirsekler omuz genişliğinde, ön kollar paralel."},"soylenecekler":["Dirseklerin arasına bir blok koyun ve onu sıkıştırın.","Göğsünüzü duvara doğru taşıyın, başınız yerden yukarıda.","Tekmeyle değil, bacağın uzunluğuyla yükselin."],"eller":{"nereye":"Dirseklerin dış yanına ya da kaldırılan bacağın baldır kısmına yakın, öğrencinin yanında.","nasil":"Dirseklerin açılmasını hafif bir içe yönlendirmeyle sınırlayın veya kalkan bacağın düşmesine karşı eli hazırda tutun; bacağı çekerek kaldırmayın.","ne_zaman_degil":"Onay yoksa, omuz instabilitesi ya da ağrısı, boyun sorunu, hamilelik veya baş dönmesi varsa dokunmayın; yunus pozunda kalmasını önerin."},"kolay":"Dirseklerin arasında blok ve kollarda kemerle yunus pozunda ayakları yürütün.","zor":"Duvar önünde iki bacağı kontrolle kaldırıp topukları duvara yaslayın; yalnızca hazırlık aşaması sağlamsa.","dikkat":"Omuz sorunları, boyun sorunları, göz içi basıncıyla ilgili durumlar ve kontrolsüz yüksek tansiyonda uygulamayın veya öğrencinin doktoruna danışmasını önerin. Hamilelikte yeni başlanmaz. Isınmamış omuzlarla ve tekme atarak girmeyin.","s":110,"fig":false},{"n":100,"bolum":7,"ad":"Duvarda el duruşu hazırlığı (Adho Mukha Vrksasana)","aile":"Ters duruş","seviye":"Orta","yogunluk":[5,7,8],"calisan":["Deltoid","Triceps brachii","Serratus anterior"],"dengeleyen":["Transversus abdominis","Rektus abdominis","Rotator manşet"],"uzayan":["Hamstringler","Latissimus dorsi"],"ozet":"Eller yerde, ayaklar duvarda kalça hizasında, vücudun L şeklini aldığı el duruşu hazırlığıdır. Kolları dik ve omuzları açık taşımayı, korkuyu kontrollü biçimde yönetmeyi öğretir.","asamalar":{"giris":"Duvara sırtınız dönük aşağı bakan köpekte, topuklar duvarın dibinde olsun. Nefes alarak bir ayağı duvara kalça yüksekliğinde basın, ardından diğerini; ayaklar duvarda geriye yürür.","kalis":"Eller omuz genişliğinde, omuzlar bileklerin üzerinde, kollar düz; kalçalar omuzların üzerine yığılır. Bakış ellerin arasına, kaburgalar içeride; 3 ila 5 nefes kalın.","cikis":"Nefes vererek ayakları tek tek duvardan indirin, dizleri yere alın ve çocuk pozunda başı dinlendirin."},"hata":{"ne":"Belin çukurlaşıp kaburgaların öne açılması.","neden":"Omuz fleksiyonu kısıtlı olduğunda beden bel omurlarını bükerek kolların yukarı açısını telafi eder.","yonlendirme":"Kaburgalar içeri, kalça omuzların üzerine."},"soylenecekler":["Parmaklarınızla yeri kavrayın, avuçların ortası hafif yukarıda.","Yeri itin; omuzlar kulaklara değil, yukarıya uzasın.","İstediğiniz an dizleri yere indirebilirsiniz."],"eller":{"nereye":"Öğrencinin yanında, pelvisin yan kısmına; kurulumda ellerin duvardan mesafesine.","nasil":"Pelvisin omuzların üzerine gelmesini hafif bir yönlendirmeyle gösterin, ayakların kaymasına karşı hazır durun; öğrenciyi yukarı kaldırmayın.","ne_zaman_degil":"Onay yoksa, bilek ya da omuz ağrısı, boyun sorunu, hamilelik veya baş dönmesi varsa dokunmayın ve pozdan çıkmasını önerin."},"kolay":"Ayakları duvarda daha alçakta tutun ya da dizleri bükülü yarım L pozunda kalın; sadece aşağı bakan köpekte omuz çalışması yapın.","zor":"L pozunda bir bacağı yukarı dikey uzatın veya duvara dönük tam el duruşuna kontrollü giriş deneyin.","dikkat":"Bilek, dirsek ya da omuz sorunlarında, göz içi basıncıyla ilgili durumlarda, kontrolsüz yüksek tansiyonda ve baş ağrısında uygulamayın veya öğrencinin doktoruna danışmasını önerin. Hamilelikte yeni başlanmaz. Duvar mesafesi önce yerde ölçülmeli, kaygan zemin kullanılmamalıdır.","s":111,"fig":false},{"n":101,"bolum":7,"ad":"Yan karga (Parsva Bakasana)","aile":"Kol dengesi","seviye":"İleri","yogunluk":[6,7,9],"calisan":["Oblikler","Triceps brachii","Serratus anterior","Büyük ve küçük pektoral"],"dengeleyen":["Rektus abdominis","Addüktörler","Deltoid"],"uzayan":[],"ozet":"Burgulu çömelmeden dizlerin yan yana bir üst kola yaslandığı kol dengesidir. Burgu gücünü ve Chaturanga tipi kol hizasını birleştirir.","asamalar":{"giris":"Dizler bitişik çömelin, nefes vererek sağa dönüp sol üst kolu sağ dış uyluğun dışına yerleştirin. Elleri omuz genişliğinde yere koyun, dirsekleri bükün ve ağırlığı ileri taşıyın.","kalis":"Dirsekler bileklerin üzerinde, omuzlar dirsek hizasında; dizler birbirine bastırır. Göğüs ileri, bakış ellerin önünde; 3 ila 5 nefes kalın.","cikis":"Nefes vererek ayakları yere indirin, çömelişe dönüp gövdeyi merkeze getirin ve diğer yana geçin."},"hata":{"ne":"Ağırlığı geride bırakıp ayakları yerden kaldırmaya çalışmak.","neden":"Kol dengesinde ağırlık merkezi ellerin üzerine taşınmadan kaldıraç oluşmaz ve beden geriye düşer.","yonlendirme":"Göğüs ileri, ayaklar kendiliğinden hafiflesin."},"soylenecekler":["Önce burgu, sonra denge; kalçalar dizlerle aynı yönde dönsün.","Dizleriniz birbirine yapışık, kaburgaları birbirine yaklaştırın.","Önünüze bir yastık koyun, düşmekten korkmadan ileri eğilin."],"eller":{"nereye":"Öğrencinin önündeki yere bir yastık ya da blok yerleştirerek; gerekirse omuzun önüne.","nasil":"Omuz başının çok aşağı düşmesini engellemek için hafif bir destek verin; kalçayı ya da bacakları kaldırmayın.","ne_zaman_degil":"Onay yoksa, bilek ya da omuz ağrısı, bel sorunu veya hamilelik varsa dokunmayın; hamilelikte burgulu kol dengesi önerilmez."},"kolay":"Ayakları bir bloğun üzerine koyun ya da kalçayı bir blokta tutarak sadece burgulu çömelişte kalın.","zor":"Üstteki bacağı düz uzatın ya da iki bacağı birlikte yana uzatarak Eka Pada Koundinyasana hazırlığına geçin.","dikkat":"Bilek, dirsek, omuz ve bel sorunlarında uygulamayı erteleyin veya öğrencinin fizyoterapistine danışmasını önerin. Hamilelikte derin burgu ve karın baskısı nedeniyle uygulanmaz. Isınmadan, Karga pozu sağlam olmadan girmeyin.","s":112,"fig":false},{"n":102,"bolum":7,"ad":"Ateş böceği hazırlığı (Tittibhasana)","aile":"Kol dengesi","seviye":"İleri","yogunluk":[6,8,9],"calisan":["Triceps brachii","Serratus anterior","İliopsoas","Kuadriseps"],"dengeleyen":["Rektus abdominis","Addüktörler","Deltoid"],"uzayan":["Hamstringler","Addüktörler"],"ozet":"Ellerin bacakların arkasından yere konduğu ve bacakların üst kollara sarıldığı kol dengesi hazırlığıdır. Kalça fleksiyonu, hamstring esnekliği ve kol gücünü birlikte gerektirir.","asamalar":{"giris":"Ayaklar kalçadan biraz geniş öne eğilin, dizleri bükün ve omuzları birer birer dizlerin arkasına yerleştirin. Elleri topukların arkasında yere koyun; nefes vererek ağırlığı geriye, ellere oturur gibi verin.","kalis":"İç uyluklar üst kolları sıkıştırır, kollar düzleşmeye çalışır, göğüs ileri uzanır. Ayaklar hafifleyebilir ya da yerde kalabilir; 3 ila 5 nefes kalın.","cikis":"Nefes vererek ayakları yere indirin, elleri bacakların arasından çıkarın ve ayakta öne eğilmede dinlenin."},"hata":{"ne":"Hamstringler hazır değilken bacakları düzleştirmek için sırtı aşırı yuvarlamak.","neden":"Hamstring esnekliği yetersizse pelvis öne devrilemez ve hareket bel omurlarından telafi edilir.","yonlendirme":"Dizler bükülü kalsın, kollar uyluklara iyice yerleşsin."},"soylenecekler":["Omuzlarınızı dizlerin arkasına mümkün olduğunca derin yerleştirin.","İç uyluklarla kolları kucaklayın, kollar bacaklar için raf olsun.","Ayakların kalkması şart değil; yükü ellerde hissetmek yeterli."],"eller":{"nereye":"Öğrencinin arkasında, kalçanın yan kısmına ya da ellerin arkasına bir blok koyarak.","nasil":"Geriye düşmeye karşı yalnızca hazırda durun; bacakları açmayın, kalçayı yukarı kaldırmayın.","ne_zaman_degil":"Onay yoksa, hamstring yırtığı geçmişi, bilek ya da omuz ağrısı, bel sorunu veya hamilelik varsa dokunmayın."},"kolay":"Ellerin altına blok koyun ve ayakları yerde bırakarak sadece kollara yaslanın.","zor":"Ayakları yerden kaldırıp bacakları öne doğru uzatarak tam Tittibhasana'ya yaklaşın.","dikkat":"Hamstring sakatlığı, bilek ve omuz sorunları ile bel diski sorunlarında uygulamayın veya öğrencinin fizyoterapistine danışmasını önerin. Hamilelikte uygulanmaz. Hamstringler iyice ısınmadan girmeyin.","s":113,"fig":false},{"n":103,"bolum":7,"ad":"Sekiz açı (Astavakrasana)","aile":"Kol dengesi","seviye":"İleri","yogunluk":[6,8,9],"calisan":["Oblikler","Triceps brachii","Büyük ve küçük pektoral","Addüktörler"],"dengeleyen":["Serratus anterior","Rektus abdominis","Deltoid"],"uzayan":["Hamstringler"],"ozet":"Bir bacağın üst kolun üzerine yerleştirildiği, bacakların çaprazlanıp yana uzatıldığı asimetrik kol dengesidir. Burgu, kalça esnekliği ve Chaturanga tipi kol gücünü bir araya getirir.","asamalar":{"giris":"Oturarak sağ bacağı sağ omuzun üzerine yerleştirin, elleri kalçaların yanına koyun. Nefes alarak kalçayı yerden kaldırın, sol ayağı sağ ayak bileğinin üzerine çaprazlayın.","kalis":"Nefes vererek dirsekleri bükün, göğsü öne ve aşağı indirin; bacaklar sağa uzanır ve sağ kolu sıkıştırır. Omuzlar dirsek hizasında, bakış ileride; 3 ila 5 nefes kalın.","cikis":"Nefes alarak göğsü kaldırın, ayakları çözüp kalçayı yere indirin ve diğer yana geçin."},"hata":{"ne":"Bacağı omuza yerleştirmek için diz eklemini zorlamak.","neden":"Kalça dış rotasyonu yetersizse hareket dizden alınır ve dize yanal yük biner.","yonlendirme":"Hareket kalçadan gelsin, diz rahat kalsın."},"soylenecekler":["Bacağı omzunuza mümkün olduğunca yukarı yerleştirin, dirseğin üzerine değil.","Ayak bileklerini çapraz kilitleyin ve kolu bacaklarla sıkıştırın.","Göğüs öne inerken dirsekler arkaya doğru bükülsün."],"eller":{"nereye":"Öğrencinin önünde, omuz başına yakın; ya da kalçanın altına bir blok yerleştirerek.","nasil":"Omzun çok aşağı düşmesini önlemek için hafif bir destek verin; bacağı omuza bastırmayın, çaprazı zorlamayın.","ne_zaman_degil":"Onay yoksa, diz ya da kalça ağrısı, bilek veya omuz sorunu, hamilelik varsa dokunmayın."},"kolay":"Ellerin altına blok koyarak kalçayı kaldırın ve bacaklar çaprazlı ama yükselmeden kalın.","zor":"Kollar düzden dirsekleri bükerek alçalın ve yeniden yükselin; kontrolle tekrar edin.","dikkat":"Diz, kalça, bilek ve omuz sorunlarında uygulamayın veya öğrencinin fizyoterapistine danışmasını önerin. Hamilelikte uygulanmaz. Kalçalar ve hamstringler ısınmadan girmeyin.","s":114,"fig":false},{"n":104,"bolum":7,"ad":"Karga'dan Chaturanga'ya geçiş","aile":"Kol dengesi","seviye":"İleri","yogunluk":[6,8,9],"calisan":["Triceps brachii","Serratus anterior","Büyük ve küçük pektoral","Rektus abdominis"],"dengeleyen":["Deltoid","Transversus abdominis","Rotator manşet"],"uzayan":[],"ozet":"Karga pozundan bacakların geriye atlanarak ya da uzatılarak doğrudan Chaturanga'ya inildiği akış geçişidir. Kol dengesindeki gücü kontrollü bir inişle birleştirmeyi öğretir.","asamalar":{"giris":"Karga pozunu kurun: dizler üst kolların arkasında, ağırlık ellerin üzerinde, bakış ileride. Nefes vererek göğsü biraz daha öne taşıyın.","kalis":"Bir anlık kalışta dirsekler bükülü kalır; bacaklar geriye uzatılırken omuzlar dirsek hizasında, gövde yere paralel tutulur. Chaturanga'da 1 ila 2 nefes kalın.","cikis":"Nefes alarak yukarı bakan köpeğe ya da kobraya geçin veya dizleri ve göğsü kontrolle yere indirin."},"hata":{"ne":"Bacakları geri atarken omuzların yere çökmesi.","neden":"İniş sırasında triceps ve serratus anterior yükü karşılayamazsa gövde omuz önüne düşer.","yonlendirme":"Dirsekler bükülü kalsın, omuzlar dirsek hizasında."},"soylenecekler":["Önce Karga'da sabitlenin, sonra bacakları teker teker geri uzatın.","Atlamak şart değil; adımlamak da aynı geçiştir.","İnerken nefesi verin, göğüs ileri bakışla birlikte uzasın."],"eller":{"nereye":"Öğrencinin yanında, omuz başının önüne yakın; gerekirse göğsün altına bir bolster yerleştirerek.","nasil":"Omuzun dirsek hizasının altına düşmesini sınırlamak için hafif bir destek verin; bacakları geriye çekmeyin.","ne_zaman_degil":"Onay yoksa, bilek ya da omuz ağrısı varsa, hamilelikte veya öğrenci hızlı bir atlama sırasındaysa dokunmayın; sözlü ipucu verin."},"kolay":"Karga'dan ayakları yere indirin, sonra adımlayarak plank ve dizler yerde Chaturanga'ya geçin.","zor":"Karga'dan iki bacağı birlikte geriye atlayın ve yere değmeden doğrudan Chaturanga'da durun.","dikkat":"Bilek, dirsek ve omuz sorunlarında, omuz cerrahisi geçmişinde uygulamayın veya öğrencinin fizyoterapistine danışmasını önerin. Hamilelikte uygulanmaz. Karga ve Chaturanga ayrı ayrı sağlam olmadan geçişe başlamayın.","s":115,"fig":false},{"n":105,"bolum":8,"ad":"Kolay oturuş (Sukhasana)","aile":"Oturarak","seviye":"Başlangıç","yogunluk":[1,2,3],"calisan":["Erector spinae","Multifidus","Diyafram"],"dengeleyen":["Transversus abdominis","Pelvik taban"],"uzayan":["Addüktörler","Piriformis"],"ozet":"Bacakların rahatça çaprazlandığı temel oturuş pozudur. Derse başlarken ve bitirirken nefes farkındalığı, niyet ve merkezlenme için kullanılır.","asamalar":{"giris":"Katlanmış bir battaniyenin kenarına oturun ve bacakları kaval kemikleri ortasından çaprazlayın. Nefes alarak oturma kemiklerine yerleşin ve omurgayı yukarı uzatın.","kalis":"Pelvis nötr, dizler kalçaların hizasında ya da altında kalır; omuzlar gevşek, çene hafif içeride. Nefesi izleyerek 1 ila 5 dakika kalın, bacak çaprazını değiştirin.","cikis":"Nefes vererek elleri yere koyun, bacakları öne uzatıp ayak bileklerini hafifçe sallayın."},"hata":{"ne":"Dizler kalçalardan yüksekteyken bel çökük oturmak.","neden":"Kalçalar ve iç uyluklar kısa olduğunda pelvis geriye devrilir ve omurga yuvarlanır.","yonlendirme":"Kalçayı yükseltin, dizler aşağı insin."},"soylenecekler":["Oturma kemiklerinizi hissedin ve başın tepesini yukarı uzatın.","Ellerinizi dizlerinize bırakın, omuzlar kulaklardan uzaklaşsın.","Bu pozda rahatlık kural; gerekiyorsa destek ekleyin."],"eller":{"nereye":"Öğrencinin arkasında, kürek kemiklerinin üstüne ya da omuz başlarına.","nasil":"Omuzları hafifçe geri ve aşağı yönlendirin veya sırtın arkasına parmak ucuyla dokunarak uzanma yönünü gösterin.","ne_zaman_degil":"Onay yoksa, öğrenci gözleri kapalıyken habersiz, ya da dizde veya kalçada ağrı bildiriliyorsa dokunmayın."},"kolay":"Daha yüksek bir destek üzerine oturun, dizlerin altına blok koyun ya da sırtı duvara yaslayın.","zor":"Destek olmadan oturun veya bir sonraki adım olarak yarım lotusa geçin.","dikkat":"Diz veya kalça ağrısında yüksek destek kullanın ya da sandalyede oturun. Bacaklarda uyuşma olursa pozisyonu değiştirin. Ağrı sürerse öğrencinin doktoruna ya da fizyoterapistine danışmasını önerin.","s":117,"fig":false},{"n":106,"bolum":8,"ad":"Kahraman (Virasana)","aile":"Oturarak","seviye":"Orta","yogunluk":[2,4,6],"calisan":["Erector spinae","Multifidus"],"dengeleyen":["Transversus abdominis","Pelvik taban"],"uzayan":["Kuadriseps","Tibialis anterior"],"ozet":"Ayakların kalçaların iki yanında olduğu, oturma kemiklerinin ayakların arasına yerleştiği diz çökerek oturuştur. Uyluk ön yüzünü ve ayak bileği önünü uzatır; destek kullanımı esastır.","asamalar":{"giris":"Dizler bitişik diz çökün, ayaklar kalçadan biraz geniş olsun. Baldır kaslarını ellerle dışa doğru yönlendirip nefes vererek ayakların arasındaki bloğa oturun.","kalis":"Ayak üstleri yerde, ayak parmakları geriye bakar; dizler kalça genişliğinde, omurga dik. Dizlerde hiçbir baskı olmadan 1 ila 3 dakika kalın.","cikis":"Nefes alarak elleri yere koyun, kalçayı kaldırıp dört ayağa gelin ve bacakları tek tek geriye uzatın."},"hata":{"ne":"Destek olmadan yere oturmaya çalışıp dizleri zorlamak.","neden":"Kuadriseps ve ayak bileği önü kısaysa yük diz ekleminin iç yapılarına biner.","yonlendirme":"Bloğu yükseltin, diz rahatsa doğru yüksekliktesiniz."},"soylenecekler":["Dizinizde en ufak bir sızı varsa desteği hemen yükseltin.","Ayak tabanlarınız tavana baksın, topuklar dışa kaçmasın.","Oturma kemiklerinizden başın tepesine uzanın."],"eller":{"nereye":"Öğrencinin arkasında, omuzların üstüne; kurulumda bloğun konumuna.","nasil":"Omuzları hafifçe geri yönlendirin veya bloğu doğru yüksekliğe ayarlayın; asla omuzlardan aşağı bastırmayın.","ne_zaman_degil":"Onay yoksa, diz ağrısı ya da diz cerrahisi geçmişi varsa veya ayak bileğinde rahatsızlık bildiriliyorsa dokunmayın."},"kolay":"Birden fazla bloğa oturun, ayak bileklerinin altına rulo battaniye koyun ya da diz arkasına ince bir havlu yerleştirin.","zor":"Destek yüksekliğini kademeli olarak azaltın veya geriye yaslanarak yarım Supta Virasana'ya geçin.","dikkat":"Diz sorunları, menisküs ya da bağ yaralanması geçmişi ve ayak bileği sorunlarında uygulamayın veya öğrencinin fizyoterapistine danışmasını önerin. Varis ya da bacaklarda dolaşım şikâyeti varsa süreyi kısa tutun. Dizde ağrı olursa hemen çıkın.","s":118,"fig":false},{"n":107,"bolum":8,"ad":"Asa (Dandasana)","aile":"Oturarak","seviye":"Başlangıç","yogunluk":[2,4,5],"calisan":["Kuadriseps","Erector spinae","İliopsoas"],"dengeleyen":["Transversus abdominis","Orta ve alt trapezius"],"uzayan":["Hamstringler","Gastroknemius ve soleus"],"ozet":"Bacakların öne düz uzatıldığı ve omurganın dik tutulduğu oturuş pozudur. Oturarak yapılan öne eğilmeler ve burgular için temel hizalamayı kurar.","asamalar":{"giris":"Oturun ve bacakları öne birlikte uzatın; kalça etlerini elle geriye ve yanlara alarak oturma kemiklerine yerleşin. Nefes alarak elleri kalçaların yanında yere bastırın.","kalis":"Ayaklar bileklerden bükülü, parmaklar yukarıda; uyluklar yere bastırır, omurga dik ve göğüs açık. 5 ila 8 nefes kalın.","cikis":"Nefes vererek elleri gevşetin, bacakları hafifçe sallayın ya da dizleri bükerek rahatlayın."},"hata":{"ne":"Pelvis geriye devrilip sırtın yuvarlanması.","neden":"Hamstringler kısaysa oturma kemiklerini öne çeker ve omurga dikliğini kaybeder.","yonlendirme":"Battaniyeye oturun, göğüs yukarı."},"soylenecekler":["Topuklarınızla öne doğru uzanın, ayak parmakları yüzünüze baksın.","Ellerle yeri itin, omurga yukarı yükselsin.","Dizler hafif bükülü olabilir; dik sırt daha önemli."],"eller":{"nereye":"Öğrencinin arkasında, kürek kemiklerinin alt ucuna ya da bel bölgesinin üzerine.","nasil":"Parmak uçlarıyla omurganın uzanma yönünü gösterin; bacakları yere bastırmayın.","ne_zaman_degil":"Onay yoksa, bel ya da hamstring ağrısı bildiriliyorsa dokunmayın."},"kolay":"Katlanmış battaniyeye oturun, dizlerin altına rulo havlu koyun ya da sırtı duvara yaslayın.","zor":"Elleri yerden kaldırıp kolları yukarı uzatın veya avuçları yere bastırarak kalçaları hafifçe kaldırmayı deneyin.","dikkat":"Bel ya da hamstring sorunlarında dizleri bükün ve yüksek destek kullanın. Ağrı sürerse öğrencinin fizyoterapistine danışmasını önerin.","s":119,"fig":false},{"n":108,"bolum":8,"ad":"Lotus ve yarım lotus (Padmasana)","aile":"Oturarak","seviye":"İleri","yogunluk":[3,5,7],"calisan":["Erector spinae","Multifidus"],"dengeleyen":["Pelvik taban","Transversus abdominis"],"uzayan":["Piriformis","Gluteus medius ve minimus","Addüktörler"],"ozet":"Ayakların karşı uyluk üzerine yerleştirildiği klasik oturuş pozudur; yarım lotusta yalnızca bir ayak yukarıdadır. Kalçada geniş dış rotasyon gerektirir ve dizleri korumak öncelik olmalıdır.","asamalar":{"giris":"Kolay oturuşta başlayın. Nefes vererek sağ dizi bükün, kaval kemiğini iki elle tutup hareketi kalçadan döndürerek sağ ayağı sol uyluğun kasığa yakın kısmına yerleştirin.","kalis":"Ayak bileği nötr, ayak dış kenarı hilal gibi bükülmez; dizler yere doğru rahat. Omurga dik, nefes sakin; 1 ila 3 dakika kalın, tarafları değiştirin.","cikis":"Nefes vererek ayağı iki elle tutup yavaşça indirin, bacakları öne uzatın ve dizleri hafifçe sallayın."},"hata":{"ne":"Ayağı uyluğa çekmek için dizi döndürmek.","neden":"Kalça dış rotasyonu yetersizse dönme diz ekleminden alınır ve menisküs zorlanır.","yonlendirme":"Kalçadan döndürün, diz sadece takip eder."},"soylenecekler":["Dizinizde bir sızı varsa geri çıkın; lotus kalçadan gelir.","Ayağı uyluğun derinine yerleştirin, ayak bileği düz kalsın.","Yarım lotus da tam bir uygulamadır."],"eller":{"nereye":"Dokunmak yerine öğrenciye kendi elleriyle kaval kemiğini nasıl tutacağını gösterin; gerekirse yükseltici battaniyeyi ayarlayın.","nasil":"Hiçbir zaman dizi aşağı bastırmayın, ayağı yukarı çekmeyin; yalnızca destek yerleştirin.","ne_zaman_degil":"Diz ya da kalça ağrısı, diz cerrahisi geçmişi, hamilelik veya onay yoksa hiç dokunmayın."},"kolay":"Yüksek bir desteğe oturup yarım lotus yapın, alttaki ayağın altına ya da yükseltilen dizin altına blok koyun.","zor":"Tam lotusta kalışı uzatın ya da bu oturuşta pranayamaya geçin; yalnızca diz tamamen rahatsa.","dikkat":"Diz, kalça ya da ayak bileği sorunlarında uygulamayın ve kolay oturuşu tercih edin; öğrencinin fizyoterapistine danışmasını önerin. Hamilelikte bağlar daha esnek olduğu için zorlamayın. Isınmadan girmeyin.","s":120,"fig":false},{"n":109,"bolum":8,"ad":"Destekli çocuk pozu","aile":"Restoratif","seviye":"Başlangıç","yogunluk":[1,2,3],"calisan":["Diyafram","Transversus abdominis"],"dengeleyen":["Pelvik taban","Multifidus"],"uzayan":["Erector spinae","Latissimus dorsi","Gluteus maximus"],"ozet":"Gövdenin uzunlamasına bir bolster üzerine bırakıldığı restoratif çocuk pozudur. Nefesin sırta yayılmasını gözlemlemek ve yoğun bir sekansın ardından dinlenmek için kullanılır.","asamalar":{"giris":"Dizler açık, ayak başparmakları birbirine değecek şekilde diz çökün ve bolsteri dizlerin arasına uzunlamasına yerleştirin. Nefes vererek gövdeyi bolsterın üzerine bırakın.","kalis":"Göğüs ve karın bolstera yaslanır, baş bir yana dönük, kollar rahat. Nefes sırtın arkasına doğru genişlesin; 2 ila 5 dakika kalın, başın yönünü yarıda değiştirin.","cikis":"Nefes alarak ellerle yeri itin, omurgayı yavaşça kaldırıp topuklarınızın üzerine oturun."},"hata":{"ne":"Destek alçak kaldığı için kalçaların havada kalması ve boynun zorlanması.","neden":"Kalça ve diz fleksiyonu sınırlı olduğunda gövde bolstera ulaşamaz ve ağırlık omuzlarda ve boyunda kalır.","yonlendirme":"Bolsterı yükseltin, gövde tamamen yaslansın."},"soylenecekler":["Desteğe ağırlığınızı tamamen bırakın, bolster sizi taşısın.","Nefes alırken sırtınızın genişlediğini hissedin.","Başınızı yarıda diğer yana çevirin."],"eller":{"nereye":"Sakrumun üzerine ya da omurganın iki yanına, kürek kemiklerinin altına, avuç düz.","nasil":"Avucu sakruma hafifçe yerleştirip ağırlık vermeden birkaç nefes kalın; bastırmayın.","ne_zaman_degil":"Onay yoksa, öğrenci gözleri kapalıyken haber vermeden, diz ya da bel ağrısı bildiriliyorsa dokunmayın."},"kolay":"Bolsterın altına blok koyarak yükseltin, kalça ile topuk arasına battaniye yerleştirin.","zor":"Bolsterı alçaltın ya da kalçaları topuklara biraz daha yaklaştırarak kalışı uzatın.","dikkat":"Diz sorunlarında diz arkasına battaniye koyun. Hamilelikte dizleri karın için yer açacak kadar geniş tutun ve desteği yüksek yapın; rahatsızlıkta öğrencinin doktoruna danışmasını önerin.","s":121,"fig":false},{"n":110,"bolum":8,"ad":"Bolster destekli balık","aile":"Restoratif","seviye":"Başlangıç","yogunluk":[1,2,4],"calisan":["Diyafram","Erector spinae"],"dengeleyen":["Transversus abdominis","Orta ve alt trapezius"],"uzayan":["Büyük ve küçük pektoral","Rektus abdominis"],"ozet":"Sırtın uzunlamasına bir bolster ya da bloklar üzerine bırakıldığı, göğsü açan restoratif pozdur. Uzun süre oturan öğrencilerde göğüs ön yüzünü yumuşak biçimde açmak için kullanılır.","asamalar":{"giris":"Bolsterın kısa kenarına sırtınızı vererek oturun. Nefes vererek dirseklere yaslanıp sırtı bolster boyunca yatırın, başı bir battaniyeyle destekleyin.","kalis":"Bolster kürek kemiklerinin altında, başın arkası destekli, çene göğüse doğru hafif. Kollar yanlara avuçlar yukarı açılır; 3 ila 5 dakika kalın.","cikis":"Nefes vererek dizleri bükün, yana dönün ve birkaç nefes bekledikten sonra ellerle itip oturun."},"hata":{"ne":"Başın destek olmadan geriye düşmesi.","neden":"Bolster yüksekken baş yere ulaşmaz ve boyun aşırı uzanmaya zorlanır.","yonlendirme":"Başın altına battaniye, çene hafif aşağı."},"soylenecekler":["Başınızın altında destek olsun, boyun rahat kalsın.","Kolları dilediğiniz kadar açın; omuzda çekme varsa avuçları karnınıza koyun.","Nefes göğsünüzün ön yüzünü yavaşça yukarı kaldırsın."],"eller":{"nereye":"Başın altındaki battaniyenin ayarına ya da omuz başlarının önüne.","nasil":"Battaniyeyi baş ve boynun altında çeneyi hafifçe aşağı getirecek kadar düzeltin; omuzları yere bastırmayın.","ne_zaman_degil":"Onay yoksa, boyun sorunu veya omuz ağrısı bildiriliyorsa, ileri hamilelikte sırtüstü kalmakta zorlanıyorsa dokunmayın."},"kolay":"Bolster yerine iki bloğu en alçak yükseklikte, biri kürek kemiklerinin altına biri başın altına gelecek şekilde kullanın; dizleri bükün.","zor":"Ayak tabanlarını birleştirerek bağlı açı bacaklarıyla kalın veya kolları başın üzerine uzatın.","dikkat":"Boyun ya da bel sorunlarında destek yüksekliğini azaltın. İleri hamilelikte gövdeyi daha dik bir eğimle destekleyin ve rahatsızlıkta öğrencinin doktoruna danışmasını önerin. Baş dönmesi olursa yavaşça çıkın.","s":122,"fig":false},{"n":111,"bolum":8,"ad":"Yapıcı dinlenme","aile":"Sırtüstü","seviye":"Başlangıç","yogunluk":[1,1,2],"calisan":["Diyafram","Transversus abdominis"],"dengeleyen":["Pelvik taban","Addüktörler"],"uzayan":["İliopsoas"],"ozet":"Sırtüstü, dizler bükülü ve birbirine yaslı, ayaklar yerde olacak şekilde dinlenme pozisyonudur. Pelvisin ve belin nötr hâline yerleşmesini gözlemlemek ve nefese dönmek için kullanılır.","asamalar":{"giris":"Sırtüstü uzanın, dizleri bükün ve ayakları kalçadan geniş yere koyun. Nefes vererek dizleri birbirine doğru düşürün, birbirine yaslansınlar.","kalis":"Pelvis ve bel yere ağır, kollar karnın üzerinde ya da yanlarda gevşek. Nefes alırken karın, verirken bel yere yerleşir; 3 ila 10 dakika kalın.","cikis":"Nefes alarak dizleri dikleştirin, yana dönün ve ellerle itip yavaşça oturun."},"hata":{"ne":"Dizleri bir arada tutmak için iç uylukları sürekli sıkmak.","neden":"Ayaklar çok dar konduğunda dizler dışa düşer ve öğrenci bunu kas gücüyle telafi eder.","yonlendirme":"Ayakları açın, dizler birbirine yaslansın."},"soylenecekler":["Dizleriniz birbirine yaslansın; hiçbir şey yapmanıza gerek yok.","Bel yere doğru eriyor, zorlamadan.","Nefes verişleri biraz daha uzun olsun."],"eller":{"nereye":"Dizlerin üzerine ya da omuz başlarına, avuç düz.","nasil":"Avucu hafifçe dizlere ya da omuzlara bırakıp yer çekimine doğru ağırlık vermeden yerleşin.","ne_zaman_degil":"Onay yoksa, öğrenci gözleri kapalıyken haber vermeden, ileri hamilelikte sırtüstü yatmakta zorlanıyorsa dokunmayın."},"kolay":"Başın altına ince bir battaniye, dizlerin arasına bir blok ya da kalın bir battaniye koyun.","zor":"Kalış süresini uzatın ve nefes verişi nefes alıştan iki kat uzun tutmayı deneyin.","dikkat":"İleri hamilelikte sırtüstü kalış rahatsızlık veriyorsa yan yatarak dinlenmeye geçin ve öğrencinin doktoruna danışmasını önerin. Bel rahatsızlığında ayakların mesafesini ayarlayın.","s":123,"fig":false},{"n":112,"bolum":8,"ad":"Sırtüstü el ayak başparmağına, yana","aile":"Sırtüstü","seviye":"Orta","yogunluk":[2,4,6],"calisan":["Kuadriseps","Oblikler"],"dengeleyen":["Gluteus medius ve minimus","Transversus abdominis","Quadratus lumborum"],"uzayan":["Addüktörler","Hamstringler"],"ozet":"Sırtüstü yatarken bir bacağın kemer yardımıyla yana açıldığı, karşı kalçanın yerde sabit tutulduğu pozdur. İç uyluk uzunluğunu pelvis kontrolüyle birlikte çalıştırır.","asamalar":{"giris":"Sırtüstü uzanın, sağ ayağın tabanına bir kemer geçirin ve bacağı yukarı uzatın. Nefes vererek sağ bacağı kemeri sağ elle tutarak yana açın, sol el sol kalçanın ön kemiğinin üzerinde.","kalis":"Sol kalça yere ağır kalır, pelvis sağa dönmez; sağ diz kapağı tavana bakar. Nefesle 5 ila 8 nefes kalın, sonra taraf değiştirin.","cikis":"Nefes alarak bacağı kemerle merkeze getirin, dizi bükün ve ayağı yere indirin."},"hata":{"ne":"Bacağı yere indirmek için karşı kalçanın yerden kalkması.","neden":"Addüktörler kısa olduğunda hareket pelvisin dönmesiyle telafi edilir.","yonlendirme":"Karşı kalça yerde, bacak bir desteğe insin."},"soylenecekler":["Sol kalçanızı yere sabitleyin; bacak ne kadar inerse o kadar.","Sağ bacağın dış kenarının altına bir blok koyabilirsiniz.","Diz kapağı tavana baksın, bacak içe dönmesin."],"eller":{"nereye":"Karşı kalçanın ön kemiği (spina iliaka anterior superior) üzerine, avuç düz.","nasil":"Karşı kalçayı hafifçe yere doğru sabitleyin; açılan bacağı aşağı bastırmayın.","ne_zaman_degil":"Onay yoksa, kasık ya da iç uyluk ağrısı, kalça sorunu, doğum sonrası pelvik kuşak ağrısı veya hamilelik varsa dokunmayın."},"kolay":"Dizi bükülü tutun ya da açılan bacağın altına blok veya bolster koyun.","zor":"Kemeri bırakıp ayak başparmağını iki parmakla tutun ya da bacağı desteksiz tutun.","dikkat":"Kasık, kalça ya da sakroiliak bölgede ağrıda hareket açıklığını küçük tutun ve öğrencinin fizyoterapistine danışmasını önerin. Hamilelikte bağlar daha esnek olduğu için desteği mutlaka kullanın ve ileri dönemde sırtüstü kalışı kısaltın.","s":124,"fig":false},{"n":113,"bolum":8,"ad":"Blok destekli köprü","aile":"Restoratif","seviye":"Başlangıç","yogunluk":[1,2,3],"calisan":["Diyafram","Gluteus maximus"],"dengeleyen":["Transversus abdominis","Pelvik taban","Addüktörler"],"uzayan":["İliopsoas","Rektus abdominis","Kuadriseps"],"ozet":"Sakrumun altına yerleştirilen bir blokla pelvisin desteklendiği pasif köprü pozudur. Kalça ön yüzünü kas eforu olmadan yumuşak biçimde açar ve dersin soğuma bölümüne uygundur.","asamalar":{"giris":"Sırtüstü dizler bükülü uzanın, ayaklar kalça genişliğinde. Nefes alarak kalçaları kaldırın ve bloğu sakrumun altına, bel omurlarına değil, kemik üzerine yerleştirin.","kalis":"Ağırlık bloğa bırakılır, kalçalar gevşer, dizler kalça genişliğinde kalır. Kollar yanlarda; 1 ila 3 dakika kalın.","cikis":"Nefes alarak kalçaları kaldırın, bloğu çıkarın ve nefes vererek omurgayı yavaşça yere indirin; dizleri göğse çekin."},"hata":{"ne":"Bloğu belin altına yerleştirmek.","neden":"Destek bel omurlarına geldiğinde bel aşırı kavislenir ve sıkışma hissi oluşur.","yonlendirme":"Blok sakrumun düz kemiğinde, belde değil."},"soylenecekler":["Bloğun üzerine tamamen bırakın, kalçalarınızı sıkmanıza gerek yok.","Dizler kalça genişliğinde; birbirine yaslamak da serbest.","Belde sıkışma varsa bloğu bir kademe alçaltın."],"eller":{"nereye":"Bloğun konumuna; gerekirse dizlerin dış yanına.","nasil":"Bloğu sakrumun altında doğru yere kaydırmasına yardım edin veya dizleri hafifçe kalça genişliğine yönlendirin; pelvise bastırmayın.","ne_zaman_degil":"Onay yoksa, bel ya da sakroiliak ağrısı, ileri hamilelik veya boyun sorunu varsa dokunmayın."},"kolay":"Bloğu en alçak yüksekliğe yatırın ya da bloğun yerine katlanmış battaniye kullanın.","zor":"Bloğu orta yüksekliğe çıkarın ve bacakları tek tek öne uzatın.","dikkat":"Bel ya da boyun sorunlarında bloğu en alçakta kullanın ve rahatsızlıkta öğrencinin fizyoterapistine danışmasını önerin. İleri hamilelikte sırtüstü kalışı kısa tutun veya yan yatarak dinlenmeye geçin.","s":125,"fig":false},{"n":114,"bolum":8,"ad":"Sırtüstü dizler göğse (Apanasana)","aile":"Sırtüstü","seviye":"Başlangıç","yogunluk":[1,2,3],"calisan":["Diyafram","Rektus abdominis"],"dengeleyen":["Transversus abdominis","Pelvik taban"],"uzayan":["Erector spinae","Gluteus maximus","Quadratus lumborum"],"ozet":"Sırtüstü dizlerin göğse çekildiği basit pozdur. Geriye eğilmelerden sonra bel bölgesini nötrlemek ve nefesin karın hareketini hissettirmek için kullanılır.","asamalar":{"giris":"Sırtüstü uzanın ve nefes vererek iki dizi göğse çekin. Elleri kaval kemiklerinin üzerine ya da diz arkalarına koyun.","kalis":"Sakrum yere yakın kalır, omuzlar ve baş yerde gevşek. Nefes alırken dizler biraz uzaklaşır, verirken yaklaşır; 5 ila 10 nefes kalın.","cikis":"Nefes alarak ayakları tek tek yere indirin ve bacakları uzatın."},"hata":{"ne":"Dizleri çekerken başı ve omuzları yerden kaldırmak.","neden":"Kollarla güç uygulandığında boyun ve omuz kasları da devreye girer ve üst gövde kalkar.","yonlendirme":"Baş yerde, omuzlar yumuşak."},"soylenecekler":["Dizlerinize sarılın, sanki kendinizi kucaklıyormuş gibi.","Nefes alırken dizler uzaklaşsın, verirken yaklaşsın.","İsterseniz yavaşça sağa sola sallanarak beli yere masaj yapın."],"eller":{"nereye":"Öğrencinin kaval kemiklerinin üzerine ya da sakrumun yere değdiği bölgeye yakın.","nasil":"Kaval kemiklerine çok hafif ağırlık vererek dizlerin göğse yaklaşmasına eşlik edin; asla bastırmayın.","ne_zaman_degil":"Onay yoksa, hamilelikte (karına baskı), diz ağrısı veya kalça protezi varsa dokunmayın."},"kolay":"Tek bacak versiyonu yapın; diğer bacak yerde bükülü ya da uzatılmış kalsın.","zor":"Burnunuzu dizlere yaklaştırmak için başı kaldırarak birkaç nefes kalın, sonra yavaşça bırakın.","dikkat":"Hamilelikte dizleri karın için yer açacak kadar geniş tutun ve baskı uygulamayın; ileri dönemde sırtüstü kalışı kısaltın. Diz sorunlarında elleri diz arkasına koyun. Kalça protezi varsa hareket açıklığını öğrencinin doktoruna danışmasını önerin.","s":126,"fig":false},{"n":115,"bolum":8,"ad":"Ceset (Savasana)","aile":"Restoratif","seviye":"Başlangıç","yogunluk":[1,1,1],"calisan":["Diyafram","Pelvik taban"],"dengeleyen":["Transversus abdominis","Multifidus"],"uzayan":[],"ozet":"Dersin sonunda bedenin tamamen bırakıldığı son dinlenme pozudur. Kas eforu yoktur; yalnızca nefesin doğal hareketi sürer ve uygulama burada toparlanır.","asamalar":{"giris":"Sırtüstü uzanın, bacakları kalçadan biraz geniş açın ve ayakların dışa düşmesine izin verin. Nefes vererek kolları gövdeden biraz uzaklaştırın, avuçlar yukarı.","kalis":"Baş ortada, çene hafif aşağı, beden simetrik. Nefesi kontrol etmeden izleyin; 5 ila 10 dakika kalın.","cikis":"Derin bir nefes alın, el ve ayak parmaklarını oynatın, dizleri bükün ve sağ yana dönün. Birkaç nefes sonra ellerle itip yavaşça oturun."},"hata":{"ne":"Belin çukurlaşması ve rahatsızlığa rağmen kıpırdamadan kalmak.","neden":"İliopsoas kısa olduğunda düz bacaklar pelvisi öne çeker ve bel yerden kalkar.","yonlendirme":"Dizlerin altına bolster, bel yere yerleşsin."},"soylenecekler":["Bedeninizin ağırlığını tamamen yere bırakın.","Nefes kendi ritminde gelsin gitsin; yönetmenize gerek yok.","Üşüyorsanız bir battaniyeyle örtünün."],"eller":{"nereye":"Omuz başlarına ya da ayak bileklerine, yalnızca önceden izin verilmişse.","nasil":"Çok hafif ve sabit bir dokunuşla birkaç nefes kalın; ani dokunuştan ve hareket ettirmekten kaçının.","ne_zaman_degil":"Önceden onay alınmadıysa hiç dokunmayın; gözleri kapalı öğrenciyi habersiz ürkütmeyin. İleri hamilelikte ve travma hassasiyeti bilinen öğrencilerde dokunmak yerine sözlü rehberlik yapın."},"kolay":"Dizlerin altına bolster, başın altına battaniye, gözlerin üzerine göz yastığı koyun.","zor":"Süreyi uzatın ve bedeni ayaklardan başa doğru bölge bölge tarayın.","dikkat":"İleri hamilelikte sırtüstü yerine yan yatarak Savasana uygulayın. Bel rahatsızlığında dizleri bükülü ya da destekli tutun. Kaygı hissedenler gözlerini açık tutabilir.","s":127,"fig":false},{"n":116,"bolum":8,"ad":"Yan yatarak Savasana (hamilelikte)","aile":"Restoratif","seviye":"Başlangıç","yogunluk":[1,1,1],"calisan":["Diyafram","Pelvik taban"],"dengeleyen":["Transversus abdominis","Oblikler"],"uzayan":[],"ozet":"Yan yatarak, bacakların arasına ve başın altına destek konularak yapılan son dinlenme pozudur. Sırtüstü yatışın rahatsız edici olduğu hamilelik dönemi ve bel hassasiyeti için alternatiftir.","asamalar":{"giris":"Dizlerinizi bükerek yana dönün, başın altına battaniye ve bacakların arasına bolster yerleştirin. Nefes vererek kalçayı ve omuzu yere bırakın.","kalis":"Kulak, omuz ve kalça aynı hizada; üstteki diz bolsterın üzerinde, kollar rahat. Gerekirse karnın altına da bir battaniye koyun; 5 ila 10 dakika kalın.","cikis":"Nefes alarak üstteki elle yeri itin ve başı en son kaldırarak yavaşça oturun."},"hata":{"ne":"Destek olmadan üstteki bacağı öne düşürüp beli burmak.","neden":"Üstteki bacak desteksiz kaldığında pelvis öne döner ve bel ile sakroiliak bölge gerilir.","yonlendirme":"Diz, kalça hizasında bir desteğin üzerinde."},"soylenecekler":["Bacaklarınızın arasındaki destek kalçanızı düz tutsun.","Başınız omzunuzla aynı hizada; battaniyeyi gerektiği kadar yükseltin.","Hangi yan size daha rahat geliyorsa orada kalın."],"eller":{"nereye":"Dokunmadan, yalnızca bolster ve battaniyelerin yerleşimine.","nasil":"Destekleri öğrencinin işaretine göre ayarlayın; bedeni hareket ettirmeyin.","ne_zaman_degil":"Hamilelikte bu pozda dokunmak yerine sözlü rehberlik ve destek ayarı yapın; onay yoksa hiç dokunmayın."},"kolay":"Sırtın arkasına ikinci bir bolster koyarak gövdeyi yaslayın ve bir sandalye ya da duvar desteği ekleyin.","zor":"Destekleri azaltın ve süreyi uzatarak yan nefese odaklanın.","dikkat":"Hamilelikte genellikle sol yan önerilir, ancak öğrencinin doktorunun önerisi geçerlidir. Baş dönmesi, nefes darlığı ya da rahatsızlık olursa pozisyonu değiştirin ve öğrencinin doktoruna danışmasını önerin.","s":128,"fig":false},{"n":117,"bolum":8,"ad":"Pranayama için oturuş","aile":"Oturarak","seviye":"Başlangıç","yogunluk":[1,2,3],"calisan":["Diyafram","Erector spinae","Multifidus"],"dengeleyen":["Pelvik taban","Transversus abdominis","Orta ve alt trapezius"],"uzayan":[],"ozet":"Nefes çalışmaları için omurganın uzun, göğsün serbest ve bedenin rahat olduğu oturuş kurulumudur. Destek seçimi kişiye göre yapılır; amaç dakikalarca zorlanmadan dik kalabilmektir.","asamalar":{"giris":"Kalçayı dizlerden yüksek olacak şekilde bir minder, blok ya da sandalye üzerine oturun. Nefes alarak oturma kemiklerini yere köklendirin ve başın tepesini uzatın.","kalis":"Pelvis nötr, kaburgalar serbest genişler, omuzlar düşük, çene hafif içeride. Elleri uyluklara bırakın; seçilen nefes tekniğiyle 5 ila 15 dakika kalın.","cikis":"Nefesi doğal ritmine bırakın, birkaç nefes gözlerinizi kapalı tutun ve bacakları yavaşça öne uzatın."},"hata":{"ne":"Göğsü kaldırmak için beli aşırı kavislendirmek.","neden":"Dik oturma çabası erector spinae'yi aşırı çalıştırır ve kaburgalar öne açılarak diyaframın hareketi kısıtlanır.","yonlendirme":"Kaburgalar yumuşak, omurga uzun."},"soylenecekler":["Size uygun yüksekliği seçin; sandalye de tam bir pranayama oturuşudur.","Nefes alırken kaburgalarınızın yanlara ve arkaya genişlediğini hissedin.","Yüz kasları, dil ve çene gevşek."],"eller":{"nereye":"Öğrencinin arkasında, kaburgaların arka yan yüzüne avuçlar düz.","nasil":"Nefesin kaburgaları genişlettiği yeri hissettirmek için avuçları hafifçe yerleştirin; bastırmayın.","ne_zaman_degil":"Onay yoksa, öğrenci gözleri kapalıyken habersiz veya nefes çalışması sırasında kaygı belirtisi gösteriyorsa dokunmayın."},"kolay":"Sırtı duvara yaslayın ya da sandalyede ayaklar yerde oturun.","zor":"Daha alçak bir destek üzerinde veya yarım lotusta, uzun süre dik kalın.","dikkat":"Nefes tekniklerinde baş dönmesi olursa doğal nefese dönün. Hamilelikte nefes tutma içeren tekniklerden kaçının. Kalp, tansiyon ya da solunum rahatsızlığında yoğun teknikler için öğrencinin doktoruna danışmasını önerin.","s":129,"fig":false},{"n":118,"bolum":8,"ad":"Elmas (Vajrasana)","aile":"Oturarak","seviye":"Başlangıç","yogunluk":[1,3,4],"calisan":["Erector spinae","Multifidus"],"dengeleyen":["Transversus abdominis","Pelvik taban"],"uzayan":["Tibialis anterior","Kuadriseps"],"ozet":"Topukların üzerine oturularak diz çökülen sade oturuş pozudur. Meditasyon, nefes ve diz çökerek yapılan geçişlerin başlangıç noktasıdır.","asamalar":{"giris":"Dizler bitişik diz çökün, ayak başparmakları birbirine değsin, topuklar hafif ayrık. Nefes vererek kalçayı topukların üzerine indirin.","kalis":"Ayak üstleri yerde, omurga dik, ellerle uyluklar üzerinde rahat. Dizlerde baskı olmadan 1 ila 5 dakika kalın.","cikis":"Nefes alarak elleri yere koyun, dört ayağa geçin ve ayak bileklerini hafifçe hareket ettirin."},"hata":{"ne":"Ayak bileği önündeki gerginliğe rağmen uzun süre kalmak.","neden":"Tibialis anterior ve ayak bileği önü kısaysa ayak üstleri ve dizler aşırı gerilir.","yonlendirme":"Ayak bileklerinin altına rulo battaniye."},"soylenecekler":["Topuklarınızın üzerine yerleşin, omurga yukarı uzasın.","Dizlerde baskı varsa topuklarla kalça arasına bir blok koyun.","Ellerinizi uyluklara bırakın ve nefesinizi izleyin."],"eller":{"nereye":"Öğrencinin arkasında, omuz başlarına ya da destek yerleşimine.","nasil":"Omuzları hafifçe geriye yönlendirin veya blok ve battaniyeyi doğru yere yerleştirin; aşağı bastırmayın.","ne_zaman_degil":"Onay yoksa, diz ya da ayak bileği ağrısı bildiriliyorsa dokunmayın."},"kolay":"Kalça ile topuk arasına blok, ayak bileklerinin altına rulo battaniye, dizlerin altına katlanmış mat koyun.","zor":"Ayak parmaklarını kıvırarak oturun ve ayak tabanını uzatın; birkaç nefes kalın.","dikkat":"Diz ve ayak bileği sorunlarında destek kullanın veya sandalyede oturun; ağrı sürerse öğrencinin fizyoterapistine danışmasını önerin. Bacaklarda uyuşma olursa pozdan çıkın.","s":130,"fig":false},{"n":119,"bolum":8,"ad":"Bolster üzerinde restoratif burgu","aile":"Restoratif","seviye":"Başlangıç","yogunluk":[1,2,3],"calisan":["Diyafram","Oblikler"],"dengeleyen":["Multifidus","Transversus abdominis"],"uzayan":["Oblikler","Quadratus lumborum","Latissimus dorsi"],"ozet":"Bir kalçanın bolsterın yanında olduğu, gövdenin dönerek bolster üzerine bırakıldığı pasif burgudur. Gövdenin yan ve arka yüzünü nefesle yumuşak biçimde açar.","asamalar":{"giris":"Sağ kalçanızı bolsterın kısa kenarına yaslayarak oturun, dizler sola katlanmış olsun. Nefes alarak omurgayı uzatın, nefes vererek gövdeyi bolstera doğru döndürüp üzerine bırakın.","kalis":"Göğüs ve karın bolstera yaslanır, kollar yanlarda yerde, baş dizlerin ya da karşı yönün tarafına dönük. 2 ila 4 dakika kalın, taraf değiştirin.","cikis":"Nefes alarak ellerle yeri itin, gövdeyi merkeze getirin ve bacakları uzatmadan önce birkaç nefes dik oturun."},"hata":{"ne":"Burguyu derinleştirmek için kollarla gövdeyi çekmek.","neden":"Kollar kaldıraç olarak kullanıldığında dönme bel omurlarına yığılır.","yonlendirme":"Bolster sizi taşısın, burgu nefesle gelsin."},"soylenecekler":["Uzanın, sonra dönün; dönerken uzunluğu kaybetmeyin.","Başınızı size rahat gelen yöne çevirin.","Her nefes verişte gövdenizi biraz daha bolstera bırakın."],"eller":{"nereye":"Sırtın arka yan yüzüne, kürek kemiğinin altına, avuç düz.","nasil":"Avucu hafifçe yerleştirip nefesin sırta yayılmasını hissettirin; burguyu derinleştirmek için bastırmayın.","ne_zaman_degil":"Onay yoksa, bel ya da sakroiliak ağrısı, disk sorunu veya hamilelik varsa dokunmayın."},"kolay":"Bolsterı blokla yükseltin ve burgu açısını küçük tutun.","zor":"Bolsterı alçaltın ve başı bacakların ters yönüne çevirerek boynu da katın.","dikkat":"Bel, disk ya da sakroiliak sorunlarında hareket açıklığını küçük tutun ve öğrencinin fizyoterapistine danışmasını önerin. Hamilelikte karnı sıkıştıran kapalı burgular yerine açık ve hafif burgu tercih edin.","s":131,"fig":false},{"n":120,"bolum":8,"ad":"Bolster üzerinde Viparita Karani","aile":"Restoratif","seviye":"Başlangıç","yogunluk":[1,2,3],"calisan":["Diyafram","Transversus abdominis"],"dengeleyen":["Pelvik taban","Erector spinae"],"uzayan":["Hamstringler","Büyük ve küçük pektoral"],"ozet":"Pelvisin duvar önündeki bir bolster üzerine yükseltildiği, bacakların duvara yaslandığı destekli hafif ters duruştur. Duvara bacakların daha derin, restoratif hâlidir.","asamalar":{"giris":"Bolsterı duvardan bir avuç mesafeye yerleştirin, bir kalçanızı bolstera dayayarak yan oturun. Nefes vererek sırtüstü dönün, bacakları duvara kaldırın ve pelvisi bolsterın üzerine yerleştirin.","kalis":"Sakrum bolsterın üzerinde, alt kaburgalar ve omuzlar yerde, göğüs hafif açık. Kollar yanlara açık; 5 ila 10 dakika kalın.","cikis":"Nefes vererek dizleri bükün, ayakları duvara basın, kalçayı kaldırıp bolsterı kenara alın; yana dönüp birkaç nefes dinlenin."},"hata":{"ne":"Bolsterı duvardan çok uzağa koyup pelvisin destekten kaymasına izin vermek.","neden":"Kalça bolstera tam oturmadığında bel kenarda asılı kalır ve gerilir.","yonlendirme":"Sakrum bolsterda, bel serbest."},"soylenecekler":["Pelvisiniz bolstera tamamen otursun, bel boşlukta kalmasın.","Bacaklarınız duvara yaslı; dizler hafif bükülü olabilir.","Gözlerin üzerine bir göz yastığı alabilirsiniz."],"eller":{"nereye":"Bolsterın yerleşimine ve duvara olan mesafeye; gerekirse ayak bileklerinin üstüne.","nasil":"Bolsterı öğrenci kalçayı kaldırdığında kaydırarak doğru yere getirin; bacakları ya da pelvisi bastırmayın.","ne_zaman_degil":"Onay yoksa, ileri hamilelikte, bel ya da boyun ağrısı bildiriliyorsa veya öğrenci bacaklarda baskı ya da uyuşma hissediyorsa dokunmayın."},"kolay":"Bolster yerine katlanmış battaniye kullanın ya da bolsterı duvardan biraz daha uzaklaştırın.","zor":"Ayak tabanlarını birleştirip dizleri yana açarak bağlı açı bacaklarıyla kalın.","dikkat":"Göz içi basıncıyla ilgili bir durum, kontrolsüz yüksek tansiyon, reflü ve boyun sorunlarında yükseltilmiş pelvis yerine düz zeminde duvara bacakları tercih edin ve öğrencinin doktoruna danışmasını önerin. Hamilelikte bu ters pozisyonu öğrencinin doktoruyla değerlendirin; rahatsızlık olursa yan yatışa geçin.","s":132,"fig":false}],"kaslar":[{"n":1,"ad":"Üst trapezius","latince":"Musculus trapezius, pars descendens","bolge":"Boyun / Omuz kuşağı","baslangic":"Oksipital kemik (linea nuchae superior) ve ligamentum nuchae.","yapisma":"Klavikulanın dış üçte biri.","islev":["Skapulayı yukarı kaldırır (elevasyon).","Serratus anterior ile birlikte skapulayı yukarı döndürür.","Başı aynı tarafa yana eğer, karşı tarafa çevirir."],"yogadaki_rol":"Kollar başın üzerine kalktığında skapulanın yukarı dönmesine katkı verir; bu yüzden Savaşçı I ve Aşağı bakan köpekte tamamen kapanması beklenmez. Sorun, omuzların kulaklara doğru sıkışmasıdır. Başı yana eğdiğiniz boyun esnetmelerinde ve Kartal kollarında ise uzar.","aktive_et":"Kolları kaldırırken kürek kemiklerinin dış köşelerinin yukarı ve dışa döndüğünü hissedin, boynu uzun tutun.","sik_hata":"Kollar yukarıdayken omuzları bilinçsizce kulaklara kadar kaldırmak ve boynu kısaltmak.","asanalar":[3,11,14,15,100],"figur_en":"Posterior view of the neck and upper back; highlight in red the upper (descending) fibres of trapezius from the occiput to the lateral clavicle, rest of the trapezius in light grey.","s":134},{"n":2,"ad":"Orta ve alt trapezius","latince":"Musculus trapezius, pars transversa et pars ascendens","bolge":"Sırt / Omuz kuşağı","baslangic":"C7–T12 omurlarının spinöz çıkıntıları.","yapisma":"Akromion ve spina scapulae.","islev":["Orta lifler skapulayı omurgaya yaklaştırır (retraksiyon).","Alt lifler skapulayı aşağı çeker (depresyon).","Alt lifler skapulanın yukarı rotasyonuna katkı verir."],"yogadaki_rol":"Geriye eğilmelerde göğsün açılmasını ve kürek kemiklerinin sırta yerleşmesini destekler. Çekirge, Kobra ve Ters plankta aktif çalışır; Kartal kollarında ve yuvarlanan öne eğilmelerde uzar.","aktive_et":"Kürek kemiklerini arka cebinize doğru kaydırın; göğüs kendiliğinden öne açılsın.","sik_hata":"Kürek kemiklerini aşırı sıkıştırıp sırtın ortasını kilitlemek; nefes göğüs kafesine giremez.","asanalar":[49,51,22,25,62,92],"figur_en":"Posterior view of the upper and mid back; highlight in red the middle (transverse) and lower (ascending) fibres of trapezius, upper fibres in light grey.","s":135},{"n":3,"ad":"Rhomboidler","latince":"Musculus rhomboideus major et minor","bolge":"Sırt / Omuz kuşağı","baslangic":"C7–T5 omurlarının spinöz çıkıntıları.","yapisma":"Skapulanın medial (iç) kenarı.","islev":["Skapulayı omurgaya yaklaştırır (retraksiyon).","Skapulayı aşağı döndürür.","Skapulayı göğüs kafesine sabitlemeye yardım eder."],"yogadaki_rol":"Göğsün açıldığı ve kolların arkaya uzandığı pozlarda çalışır: Çekirge, Ters masa, Köprüde omuzların altına toplanması. Kartal kollarında, İğneye iplik geçirmede ve Kedi pozunun yuvarlanan sırtında uzar.","aktive_et":"Ellerinizi arkada birleştirin ve kürek kemiklerinin iç kenarlarını birbirine hafifçe yaklaştırın.","sik_hata":"Chaturanga ve plankta kürek kemiklerini birbirine yapıştırıp göğüs kafesinin çökmesine izin vermek.","asanalar":[51,52,53,61,62,24],"figur_en":"Posterior view of the upper back with trapezius removed; highlight in red rhomboid major and minor between the spine and the medial border of the scapula.","s":136},{"n":4,"ad":"Latissimus dorsi","latince":"Musculus latissimus dorsi","bolge":"Sırt / Gövde","baslangic":"T7–T12 spinöz çıkıntıları, torakolomber fasya, iliak krista ve alt kaburgalar.","yapisma":"Humerusun intertüberküler oluğu.","islev":["Omzu ekstansiyona getirir (kolu aşağı ve geri çeker).","Kolu gövdeye yaklaştırır (addüksiyon).","Kolu içe döndürür.","Kollar sabitken gövdeyi yukarı çekmeye yardım eder."],"yogadaki_rol":"Kollar başın üzerindeyken tamamen uzar; bu kısalık Aşağı bakan köpekte ve Çarkta sırtın yuvarlanmasına ya da belin aşırı çukurlaşmasına yol açabilir. Chaturanga ve Ön kol plankında gövdeyi taşımak için çalışır.","aktive_et":"Plankta avuçlarla yeri ayaklarınıza doğru çekiyormuş gibi bastırın, koltuk altlarını aktif tutun.","sik_hata":"Kollar yukarı kalkınca kaburgaları öne fırlatıp belin çukurlaşmasıyla latissimus kısalığını telafi etmek.","asanalar":[14,39,54,94,15],"figur_en":"Lateral-posterior view of the trunk with arm raised overhead; highlight in red latissimus dorsi from the lower spine and iliac crest to the humerus.","s":137},{"n":5,"ad":"Serratus anterior","latince":"Musculus serratus anterior","bolge":"Omuz kuşağı / Gövde","baslangic":"1–9. kaburgaların dış yüzü.","yapisma":"Skapulanın medial kenarının ön yüzü.","islev":["Skapulayı öne ve dışa taşır (protraksiyon).","Skapulayı yukarı döndürür.","Skapulayı göğüs kafesine sabitler."],"yogadaki_rol":"Ellerin üzerinde taşınan her pozun temel kasıdır: Plank, Aşağı bakan köpek, Yan plank ve Karga. Zayıf kaldığında kürek kemikleri sırttan kalkar ve göğüs kafesi kolların arasına çöker.","aktive_et":"Yeri ellerinizle itin, kürek kemiklerinin göğüs kafesini sarmaladığını hissedin.","sik_hata":"Plankta göğsün eller arasına düşmesi ve kürek kemiklerinin kanat gibi açılması.","asanalar":[93,14,28,30,92,100],"figur_en":"Lateral view of the thorax with the arm raised forward; highlight in red the serrated slips of serratus anterior along the ribs to the scapula.","s":138},{"n":6,"ad":"Erector spinae","latince":"Musculus erector spinae (iliocostalis, longissimus, spinalis)","bolge":"Sırt","baslangic":"Sakrum, iliak krista ve lomber ile alt torakal spinöz çıkıntılar.","yapisma":"Kaburgalar, omurların transvers ve spinöz çıkıntıları, oksipital kemik.","islev":["Omurgayı ekstansiyona getirir.","Tek taraflı çalışınca gövdeyi yana eğer.","Öne eğilmede gövdenin inişini eksantrik olarak kontrol eder."],"yogadaki_rol":"Geriye eğilmelerde ve uzun sırtla yapılan öne eğilmelerde omurgayı taşır: Kobra, Çekirge, Yarım öne eğilme, Savaşçı III. Paschimottanasana ve Çocuk pozunda uzar.","aktive_et":"Göğüs kemiğini öne uzatın, başın tepesiyle kuyruk sokumu arasında mesafe yaratın.","sik_hata":"Öne eğilmede hamstring kısalığını sırtı yuvarlayarak telafi etmek ve bu kası gereğinden fazla gerdirmek.","asanalar":[49,51,37,22,52,2],"figur_en":"Posterior view of the back; highlight in red the erector spinae columns on both sides of the spine from the sacrum to the neck.","s":139},{"n":7,"ad":"Multifidus","latince":"Musculi multifidi","bolge":"Sırt","baslangic":"Sakrum, spina iliaca posterior superior, lomber mamiller çıkıntılar, torakal transvers çıkıntılar.","yapisma":"2–4 segment yukarıdaki omurların spinöz çıkıntıları.","islev":["Omurgayı segment segment stabilize eder.","Omurgaya ince ekstansiyon verir.","Rotasyonu kontrol eder."],"yogadaki_rol":"Yüzeydeki büyük kaslardan önce devreye giren derin bir stabilizatördür; Dağ pozunda ve dört ayak üzerinde nötr omurgayı tutar. Burgularda omurların tek tek dönmesine ve kontrollü geri gelmesine katkı verir.","aktive_et":"Dört ayak üzerinde bir kolu kaldırırken pelvisin ve belin kıpırdamamasına odaklanın.","sik_hata":"Burgularda tek bir bel segmentinden zorlamak; dönüş tüm omurgaya dağılmaz.","asanalar":[1,47,48,63,74,22],"figur_en":"Posterior view of the lumbar and thoracic spine with superficial muscles removed; highlight in red the short multifidus fascicles spanning 2-4 vertebrae.","s":140},{"n":8,"ad":"Quadratus lumborum","latince":"Musculus quadratus lumborum","bolge":"Gövde / Bel","baslangic":"İliak kristanın arka kısmı ve iliolomber bağ.","yapisma":"12. kaburga ve L1–L4 transvers çıkıntıları.","islev":["Gövdeyi yana eğer.","Pelvisin bir yanını yukarı kaldırır.","Nefes alırken 12. kaburgayı sabitler.","İki taraflı çalışınca bele ekstansiyon verir."],"yogadaki_rol":"Yana eğilmelerde ve Üçgende üstte kalan tarafta uzar, alttaki tarafta çalışır. Yan plankta pelvisi yukarıda tutmaya yardım eder. Kapı pozunda belin yan tarafını uzatmak için iyi bir yerdir.","aktive_et":"Yan plankta alttaki kalçayı tavana doğru biraz daha kaldırın, belin yan tarafının çalıştığını hissedin.","sik_hata":"Üçgen ve yana eğilmelerde alttaki yan beli ezmek; uzama yerine sıkışma olur.","asanalar":[6,15,28,45,88,23],"figur_en":"Posterior-lateral view of the lumbar region; highlight in red quadratus lumborum between the iliac crest, the 12th rib and the lumbar transverse processes.","s":141},{"n":9,"ad":"Rotator manşet","latince":"Musculi supraspinatus, infraspinatus, teres minor et subscapularis","bolge":"Omuz kuşağı","baslangic":"Skapulanın supraspinöz, infraspinöz ve subskapular fossaları ile lateral kenarı.","yapisma":"Humerusun büyük ve küçük tüberkülleri.","islev":["Humerus başını eklem yuvasında ortalar.","Kolu dışa döndürür (infraspinatus, teres minor).","Kolu içe döndürür (subscapularis).","Abdüksiyonun ilk derecelerini başlatır (supraspinatus)."],"yogadaki_rol":"Kollar yük taşıdığında omuz eklemini merkezde tutar: Chaturanga, Plank, Yunus ve duvarda el duruşu hazırlığı. İnek yüzü kollarında iç ve dış rotatorlar karşılıklı olarak uzar.","aktive_et":"Aşağı bakan köpekte üst kolları hafifçe dışa, ön kolları hafifçe içe çevirin.","sik_hata":"Chaturangada omuzları dirseklerin altına düşürmek; humerus başı öne kayar.","asanalar":[94,93,92,100,82,28],"figur_en":"Posterior and anterior views of the scapula and humeral head; highlight in red supraspinatus, infraspinatus, teres minor and subscapularis.","s":142},{"n":10,"ad":"Deltoid","latince":"Musculus deltoideus","bolge":"Omuz kuşağı / Kol","baslangic":"Klavikulanın dış üçte biri, akromion ve spina scapulae.","yapisma":"Humerusun deltoid tüberozitesi.","islev":["Kolu yana kaldırır (abdüksiyon).","Ön lifler kolu öne kaldırır (fleksiyon).","Arka lifler kolu arkaya götürür (ekstansiyon)."],"yogadaki_rol":"Kollar yere paralel tutulduğunda yükü taşır: Savaşçı II ve Genişletilmiş yan açı. Yan plank ve Yunusta omzu sarmalayarak çalışır; Ters masada ön lifler uzar.","aktive_et":"Savaşçı II’de kolları parmak uçlarından uzatın, omuz başlarını aşağıda tutun.","sik_hata":"Kollar yere paralelken omuzları kaldırıp yükü boyna yığmak.","asanalar":[4,7,28,92,100,61],"figur_en":"Lateral view of the shoulder; highlight in red the anterior, middle and posterior fibres of deltoid.","s":143},{"n":11,"ad":"Büyük ve küçük pektoral","latince":"Musculus pectoralis major et minor","bolge":"Göğüs / Omuz kuşağı","baslangic":"Major: klavikulanın iç yarısı, sternum ve 1–6. kaburga kıkırdakları. Minor: 3–5. kaburgalar.","yapisma":"Major: humerusun intertüberküler oluğunun dış dudağı. Minor: skapulanın korakoid çıkıntısı.","islev":["Kolu gövdeye yaklaştırır ve içe döndürür (major).","Kolu öne kaldırır (major, klaviküler lifler).","Skapulayı öne ve aşağı çeker (minor)."],"yogadaki_rol":"Chaturanga ve Plankta gövdeyi taşırken çalışır. Geriye eğilmelerde, Balıkta, Ters plankta ve bolster destekli göğüs açıcılarda uzar; kısalığı omuzların öne yuvarlanmasıyla görünür.","aktive_et":"Chaturangada dirsekleri kaburgalara yakın tutun, göğsü öne doğru uzatın.","sik_hata":"Geriye eğilmede göğüs yerine omuzları öne iterek yükü omuz önüne yığmak.","asanalar":[94,57,55,62,110,54],"figur_en":"Anterior view of the chest; highlight in red pectoralis major, show pectoralis minor beneath it in a darker red with major partially transparent.","s":144},{"n":12,"ad":"Triceps brachii","latince":"Musculus triceps brachii","bolge":"Kol","baslangic":"Uzun baş: skapulanın infraglenoid tüberkülü. Lateral ve medial başlar: humerusun arka yüzü.","yapisma":"Ulnanın olekranon çıkıntısı.","islev":["Dirseği düzleştirir (ekstansiyon).","Uzun baş omzun ekstansiyonuna katkı verir.","Dirsek eklemini yük altında stabilize eder."],"yogadaki_rol":"Chaturangada inişi kontrol eder, Çarkta ve Yukarı bakan köpekte kolları düzleştirir. Kol dengelerinde ve Destekli omuz duruşunda gövdeyi taşır. Kollar başın üzerinde dirsek bükülünce (İnek yüzü kolları) uzun baş uzar.","aktive_et":"Chaturangada dirsekleri geriye doğru yönlendirin ve inişi yavaşlatın.","sik_hata":"Dirsekleri dışa açarak Chaturangada yükü omuz önüne aktarmak.","asanalar":[94,54,50,30,96,104],"figur_en":"Posterior view of the upper arm; highlight in red the long, lateral and medial heads of triceps brachii.","s":145},{"n":13,"ad":"Rektus abdominis","latince":"Musculus rectus abdominis","bolge":"Gövde / Karın","baslangic":"Pubik simfiz ve pubik krista.","yapisma":"5–7. kaburga kıkırdakları ve ksifoid çıkıntı.","islev":["Gövdeyi öne büker (fleksiyon).","Pelvisi arkaya devirmeye yardım eder.","Karın içi basıncı artırır."],"yogadaki_rol":"Tekne, Karga ve Ön kol plankında gövdeyi toplar. Deve, Çark ve Kobra gibi geriye eğilmelerde uzar; bu uzamayı kontrollü tutmak bel yükünü dağıtır.","aktive_et":"Nefes verirken alt kaburgaları pelvise doğru hafifçe yaklaştırın.","sik_hata":"Teknede karnı dışarı iterek çalışmak; bel yuvarlanır ve yük kalça fleksörlerine kayar.","asanalar":[29,30,93,95,55,96],"figur_en":"Anterior view of the abdomen; highlight in red rectus abdominis from the pubis to the lower ribs, showing tendinous intersections.","s":146},{"n":14,"ad":"Oblikler","latince":"Musculus obliquus externus et internus abdominis","bolge":"Gövde / Karın","baslangic":"Dış oblik: 5–12. kaburgaların dış yüzü. İç oblik: torakolomber fasya, iliak krista, inguinal bağ.","yapisma":"Dış oblik: iliak krista, linea alba, inguinal bağ. İç oblik: 10–12. kaburgalar ve linea alba.","islev":["Gövdeyi döndürür.","Gövdeyi yana eğer.","Gövde fleksiyonuna katkı verir.","Karın içi basıncı destekler."],"yogadaki_rol":"Her burgunun motorudur: Oturarak burgu, Dönen yan açı, Dönen üçgen. Yan plankta gövdeyi yanlardan taşır; Üçgende üstteki tarafta uzar.","aktive_et":"Burguda önce nefes alarak uzayın, sonra nefes verirken göbeği dönüş yönüne çevirin.","sik_hata":"Burguyu kolla kaldıraç yaparak zorlamak; dönüş gövdeden değil omuzdan gelir.","asanalar":[63,68,9,6,28,101],"figur_en":"Anterolateral view of the trunk; highlight in red external oblique, show internal oblique underneath in darker red with crossing fibre directions.","s":147},{"n":15,"ad":"Transversus abdominis","latince":"Musculus transversus abdominis","bolge":"Gövde / Karın","baslangic":"7–12. kaburga kıkırdaklarının iç yüzü, torakolomber fasya, iliak krista, inguinal bağ.","yapisma":"Linea alba ve pubis.","islev":["Karın duvarını içe doğru toplar.","Karın içi basıncı düzenler.","Nefes vermeye yardım eder.","Lomber-pelvik bölgeyi stabilize eder."],"yogadaki_rol":"Bir korse gibi gövdeyi sarar; Plank, Tekne ve Karga gibi pozlarda omurgayı korur. Kedi ve inekte nefesle birlikte nazikçe çalışır; derin restoratif pozlarda gevşemesine izin verilir.","aktive_et":"Nefes verirken alt karnı, kemer bağlıyormuş gibi kalça kemiklerinin arasında hafifçe içe toplayın.","sik_hata":"Karnı sürekli sert biçimde içe çekip nefesi kısıtlamak.","asanalar":[93,29,30,22,95,47],"figur_en":"Anterior view of the abdomen with obliques removed; highlight in red transversus abdominis with its horizontal fibres wrapping around the trunk.","s":148},{"n":16,"ad":"Diyafram","latince":"Diaphragma","bolge":"Gövde / Göğüs kafesi","baslangic":"Sternal kısım: ksifoidin arka yüzü. Kostal kısım: 7–12. kaburgaların iç yüzü. Lomber kısım: L1–L3 (krus).","yapisma":"Merkezî tendon (centrum tendineum).","islev":["Ana solunum kasıdır; nefes alırken aşağı iner.","Göğüs boşluğunu genişletir.","Pelvik taban ve karın kaslarıyla birlikte karın içi basıncı düzenler."],"yogadaki_rol":"Her pozun ritmini belirler. Çocuk pozunda nefes sırtın arkasına, Sırtüstü bağlı açıda karnın önüne yayılır. Pranayama için oturuşta ve Savasanada nefesin akışını gözlemlemek için temel odaktır.","aktive_et":"Bir elinizi alt kaburgalara koyun; nefes alırken kaburgaların yanlara açıldığını hissedin.","sik_hata":"Nefes almak için omuzları ve boyun kaslarını kaldırmak; nefes göğsün üstünde kalır.","asanalar":[117,115,111,40,79,105],"figur_en":"Anterior cut-away view of the thorax and abdomen; highlight in red the dome of the diaphragm with its central tendon and crura.","s":149},{"n":17,"ad":"Pelvik taban","latince":"Diaphragma pelvis (musculus levator ani et musculus coccygeus)","bolge":"Pelvis","baslangic":"Pubisin arka yüzü, obturator fasyanın tendinöz kemeri ve iskiyal spina.","yapisma":"Koksiks, anokoksigeal bağ ve perineal cisim.","islev":["Pelvik organları destekler.","Diyaframla eşgüdümlü nefes ritmine katılır.","Karın içi basıncı aşağıdan karşılar."],"yogadaki_rol":"Nefesle birlikte hafifçe yükselip alçalır; nefes verirken hafif bir kaldırma hissi, nefes alırken gevşeme. Çelenk ve Bağlı açıda gevşemeye, Köprü ve Dağ pozunda hafif destek vermeye alan açar.","aktive_et":"Nefes verirken oturma kemiklerinin birbirine çok hafif yaklaştığını hayal edin; nefes alırken bırakın.","sik_hata":"Pelvik tabanı pozun tamamı boyunca kasılı tutmak; gevşeme fazını atlamak.","asanalar":[80,78,117,53,1,79],"figur_en":"View from above into the pelvis (superior view); highlight in red levator ani and coccygeus forming the pelvic floor.","s":150},{"n":18,"ad":"İliopsoas","latince":"Musculus iliopsoas (psoas major et iliacus)","bolge":"Kalça / Gövde","baslangic":"Psoas major: T12–L4 omur gövdeleri, transvers çıkıntılar ve diskler. İliacus: iliak fossa.","yapisma":"Femurun küçük trokanteri.","islev":["Kalçayı büker (fleksiyon).","Lomber omurgayı stabilize eder.","Bacak sabitken gövdeyi öne getirir."],"yogadaki_rol":"Teknede ve Ayakta el ayak başparmağına pozunda bacağı kaldırır. Alçak hamlede, Savaşçı I’in arka bacağında ve geriye uzanan hamlede uzar; kısalığı belin aşırı çukurlaşmasıyla kendini gösterir.","aktive_et":"Alçak hamlede kuyruk sokumunu hafifçe aşağı yönlendirin, arka kalçanın önünde açılmayı hissedin.","sik_hata":"Hamlede pelvisi öne devirip uzamayı bele aktarmak.","asanalar":[29,12,3,86,26,60],"figur_en":"Anterior view of the lumbar spine and pelvis; highlight in red psoas major and iliacus joining to the lesser trochanter of the femur.","s":151},{"n":19,"ad":"Gluteus maximus","latince":"Musculus gluteus maximus","bolge":"Kalça","baslangic":"İliumun arka yüzü, sakrum, koksiks ve sakrotüberal bağ.","yapisma":"İliotibial bant ve femurun gluteal tüberozitesi.","islev":["Kalçayı ekstansiyona getirir.","Kalçayı dışa döndürür.","Çömelmeden kalkarken ve merdiven çıkarken güç verir.","Pelvisi stabilize eder."],"yogadaki_rol":"Köprü, Çekirge ve Savaşçı III’te arka bacağı ve pelvisi taşır; Sandalyede kalkışı kontrol eder. Güvercinde, Sırtüstü güvercinde ve Mutlu bebekte uzar.","aktive_et":"Köprüde ayaklarınızı mata bastırıp topuklarınızı omuzlarınıza doğru çekiyormuş gibi yapın.","sik_hata":"Geriye eğilmelerde kalçaları sert biçimde sıkıp bel yükünü artırmak.","asanalar":[53,22,2,51,49,76],"figur_en":"Posterior view of the hip; highlight in red gluteus maximus from the sacrum and ilium to the iliotibial band and femur.","s":152},{"n":20,"ad":"Gluteus medius ve minimus","latince":"Musculus gluteus medius et minimus","bolge":"Kalça","baslangic":"İliumun dış yüzü (anterior ve posterior gluteal çizgiler arası).","yapisma":"Femurun büyük trokanteri.","islev":["Kalçayı yana açar (abdüksiyon).","Tek bacak üzerinde pelvisi düz tutar.","Ön lifler içe, arka lifler dışa rotasyona katkı verir."],"yogadaki_rol":"Tüm denge pozlarının sessiz taşıyıcısıdır: Ağaç, Yarım ay, Savaşçı III ve Kartal. Savaşçı II’de ön dizin içe kaçmamasına yardım eder; Yan plankta alttaki kalçayı tutar.","aktive_et":"Ağaçta basan bacağın kalçasını hafifçe içe toplayın, pelvisi iki yanda aynı seviyede tutun.","sik_hata":"Tek bacak üzerinde basan kalçayı yana dışarı salmak.","asanalar":[21,23,4,22,24,28],"figur_en":"Lateral view of the hip with gluteus maximus made transparent; highlight in red gluteus medius and, beneath it, gluteus minimus to the greater trochanter.","s":153},{"n":21,"ad":"Piriformis","latince":"Musculus piriformis","bolge":"Kalça","baslangic":"Sakrumun ön yüzü (S2–S4).","yapisma":"Femurun büyük trokanterinin üst kenarı.","islev":["Kalça düzken dışa döndürür.","Kalça 90° bükülüyken yana açılmaya katkı verir.","Sakroiliak bölgenin stabilitesine destek olur."],"yogadaki_rol":"Derin dış rotatorların en belirginidir; Güvercinde, Sırtüstü güvercinde, Ateş kütüğünde ve İnek yüzünde uzar. Esnetmeyi hafif başlatıp dizin değil kalçanın açıldığını gözlemlemek önemlidir.","aktive_et":"Sırtüstü güvercinde ayak bileğini esnetip (flex) dizinizi göğüsten hafifçe uzaklaştırın.","sik_hata":"Güvercinde kalçanın açılmadığı yerde dizi zorlamak; yük diz eklemine biner.","asanalar":[75,76,81,82,85],"figur_en":"Posterior view of the deep hip with gluteus maximus removed; highlight in red piriformis from the anterior sacrum to the greater trochanter.","s":154},{"n":22,"ad":"Kuadriseps","latince":"Musculus quadriceps femoris (rectus femoris, vastus lateralis, vastus medialis, vastus intermedius)","bolge":"Bacak / Uyluk","baslangic":"Rectus femoris: spina iliaca anterior inferior. Vastuslar: femurun ön ve yan yüzleri.","yapisma":"Patella üzerinden patellar bağ ile tibial tüberozite.","islev":["Dizi düzleştirir (ekstansiyon).","Rectus femoris kalça fleksiyonuna katkı verir.","Diz kapağının hareketini yönlendirir ve dizi stabilize eder."],"yogadaki_rol":"Sandalye, Savaşçı II ve Tanrıçada bükülü dizi taşır. Kuadriseps esnetmeli alçak hamlede ve Kahramanda uzar; Dansçıda arka bacakta rectus femoris uzar.","aktive_et":"Ayakta öne eğilmede diz kapaklarını hafifçe yukarı çekin, dizleri kilitlemeden.","sik_hata":"Düz bacakla duran pozlarda dizi geriye kilitlemek.","asanalar":[2,4,3,13,86,106],"figur_en":"Anterior view of the thigh; highlight in red rectus femoris and the three vasti converging into the patellar tendon.","s":155},{"n":23,"ad":"Hamstringler","latince":"Musculus biceps femoris, semitendinosus et semimembranosus","bolge":"Bacak / Uyluk","baslangic":"Tuber iskiyadikum (oturma kemiği); biceps femorisin kısa başı femurun linea asperası.","yapisma":"Biceps femoris: fibula başı. Semitendinosus ve semimembranosus: tibianın iç yüzü.","islev":["Dizi büker.","Kalçayı ekstansiyona getirir.","Öne eğilmede pelvisin öne dönüşünü kontrol eder."],"yogadaki_rol":"Bütün öne eğilmelerde uzar: Ayakta öne eğilme, Paschimottanasana, Piramit, Yarım split. Köprüde ve Savaşçı III’te çalışarak pelvisi taşır. Kısalığı çoğu zaman sırtın yuvarlanmasıyla görünür.","aktive_et":"Öne eğilmede oturma kemiklerini geriye ve yukarı uzatın; gerekirse dizleri bükün.","sik_hata":"Ellerle yere ya da ayaklara ulaşmak için sırtı yuvarlamak.","asanalar":[20,33,8,42,41,53],"figur_en":"Posterior view of the thigh; highlight in red biceps femoris, semitendinosus and semimembranosus from the sitting bone to the lower leg.","s":156},{"n":24,"ad":"Addüktörler","latince":"Musculi adductor longus, brevis et magnus, gracilis, pectineus","bolge":"Bacak / Uyluk iç yüzü","baslangic":"Pubis gövdesi ve ramusu, iskiyal ramus ve tuber iskiyadikum.","yapisma":"Femurun linea asperası ve addüktör tüberkülü; gracilis tibianın iç yüzü.","islev":["Bacağı orta hatta yaklaştırır (addüksiyon).","Adductor magnus kalça ekstansiyonuna katkı verir.","Ayakta ve dengede pelvisi stabilize eder."],"yogadaki_rol":"Ağaçta basan bacağı ve Kartalda bacak sarmasını stabilize eder. Tanrıçada, Geniş bacaklı oturarak öne eğilmede, Bağlı açıda ve Çelenkte uzar.","aktive_et":"Ağaçta ayağı bacağa, bacağı ayağa eşit güçle bastırın.","sik_hata":"Bağlı açıda dizleri ellerle yere bastırmak.","asanalar":[21,13,35,78,80,87],"figur_en":"Anterior-medial view of the thigh; highlight in red adductor longus, brevis, magnus, gracilis and pectineus.","s":157},{"n":25,"ad":"Tensör fasya lata","latince":"Musculus tensor fasciae latae","bolge":"Kalça / Uyluk dış yüzü","baslangic":"Spina iliaca anterior superior ve iliak kristanın ön kısmı.","yapisma":"İliotibial bant aracılığıyla tibianın dış kondili.","islev":["Kalçayı büker.","Kalçayı yana açar.","Kalçayı içe döndürür.","Diz dış yanının stabilitesine katkı verir."],"yogadaki_rol":"Tek bacak denge pozlarında gluteus medius ile birlikte pelvisi tutar: Yarım ay, Ağaç. Kartalda ve Sırtüstü el ayak başparmağına yana pozunun çapraz varyasyonunda uzar.","aktive_et":"Yarım ayda basan bacağın kalçasını hafifçe geriye çekin, kalçanın önünü sıkıştırmayın.","sik_hata":"Denge pozlarında yükün tamamını kalçanın dış önüne verip gluteus mediusu devre dışı bırakmak.","asanalar":[23,21,24,7,112],"figur_en":"Anterolateral view of the hip and thigh; highlight in red tensor fasciae latae and show the iliotibial band continuing down the lateral thigh in a lighter red.","s":158},{"n":26,"ad":"Gastroknemius ve soleus","latince":"Musculus gastrocnemius et musculus soleus (triceps surae)","bolge":"Alt bacak","baslangic":"Gastroknemius: femurun iç ve dış kondilleri. Soleus: tibia ve fibulanın arka yüzünün üst kısmı.","yapisma":"Aşil tendonu aracılığıyla kalkaneus.","islev":["Ayak bileğini plantar fleksiyona getirir (parmak ucuna kalkış).","Gastroknemius diz fleksiyonuna katkı verir.","Ayakta dururken öne-arkaya salınımı kontrol eder."],"yogadaki_rol":"Aşağı bakan köpekte ve Piramitte uzar; dizler düzken gastroknemius, dizler bükülüyken soleus daha çok esner. Parmak ucunda sandalyede çalışır, Çelenkte topukların yere inmesini belirler.","aktive_et":"Parmak ucunda sandalyede topukları yerden eşit yükseklikte tutun, ayak bileklerini dışa düşürmeyin.","sik_hata":"Aşağı bakan köpekte topukları yere indirmek için sırtı yuvarlamak.","asanalar":[14,31,8,20,80],"figur_en":"Posterior view of the lower leg; highlight in red the two heads of gastrocnemius and, deeper, soleus joining into the Achilles tendon.","s":159},{"n":27,"ad":"Tibialis anterior","latince":"Musculus tibialis anterior","bolge":"Alt bacak","baslangic":"Tibianın dış kondili ve dış yüzünün üst yarısı, interosseöz membran.","yapisma":"Medial kuneiform ve 1. metatarsın tabanı.","islev":["Ayak bileğini dorsifleksiyona getirir.","Ayağı içe çevirir (inversiyon).","Ayağın iç arkını destekler."],"yogadaki_rol":"Ağaçta ve diğer tek bacak pozlarında ayak bileğinin küçük düzeltmelerini yapar. Sandalye ve Çelenkte dizin öne ilerlemesine eşlik eder. Elmas ve Kahramanda ayak üstleri yerdeyken uzar.","aktive_et":"Ağaçta basan ayağın iç arkını hafifçe kaldırın, başparmak kökünü yerde tutun.","sik_hata":"Tek bacak üzerinde ayak arkını çökertmek; diz içe kaçar.","asanalar":[21,2,80,106,118],"figur_en":"Anterolateral view of the lower leg and foot; highlight in red tibialis anterior from the tibia to the medial foot.","s":160},{"n":28,"ad":"Sternokleidomastoid","latince":"Musculus sternocleidomastoideus","bolge":"Boyun","baslangic":"Sternumun manubriumu ve klavikulanın iç üçte biri.","yapisma":"Temporal kemiğin mastoid çıkıntısı ve linea nuchae superior.","islev":["Tek taraflı: başı aynı tarafa yana eğer, karşı tarafa çevirir.","Çift taraflı: boynu öne büker.","Zorlu nefeste yardımcı solunum kası olarak çalışır."],"yogadaki_rol":"Teknede ve sırtüstü karın çalışmalarında başı taşır. Balıkta ve Devede baş geriye bırakılınca uzar; Sırtüstü burguda baş karşı tarafa döndüğünde nazikçe esner.","aktive_et":"Teknede çeneyi göğse doğru hafifçe yaklaştırın, boynun önünü yumuşak tutun.","sik_hata":"Devede başı aniden geriye atmak; boynun önü kontrolsüz uzar.","asanalar":[29,57,55,66,96],"figur_en":"Anterolateral view of the neck with the head slightly rotated; highlight in red sternocleidomastoid from the sternum and clavicle to the mastoid process.","s":161}],"dersler":[{"n":1,"baslik":"Temeller: yeni başlayanlar için hizalanma","seviye":"Başlangıç","s":170,"asanalar":[111,47,40,14,1,2,12,4,6,21,107,34,53,66,114,115,105]},{"n":2,"baslik":"Ayakta dinamik akış","seviye":"Orta","s":172,"asanalar":[105,47,14,18,19,3,4,5,7,11,16,22,23,10,33,66,115]},{"n":3,"baslik":"Kalçalar ve hamstringler","seviye":"Başlangıç","s":174,"asanalar":[111,47,114,41,14,12,42,8,80,75,76,78,35,34,84,115]},{"n":4,"baslik":"Adım adım geriye eğilmeler","seviye":"Orta","s":176,"asanalar":[105,47,39,14,12,86,48,49,51,53,56,58,55,40,73,114,115]},{"n":5,"baslik":"Burgular ve omurga","seviye":"Başlangıç","s":178,"asanalar":[105,47,74,69,1,15,72,16,88,64,63,45,66,114,115]},{"n":6,"baslik":"Yavaş ve restoratif pratik","seviye":"Tüm seviyeler","s":180,"asanalar":[111,47,114,73,109,79,110,119,113,120,115,105]}],"bolumler":{"1":"Ayakta pozlar","2":"Denge pozları","3":"Öne eğilmeler","4":"Geriye eğilmeler","5":"Burgular","6":"Kalça açıcılar","7":"Ters duruşlar ve kol dengeleri","8":"Oturarak, sırtüstü ve restoratif pozlar"},"pdf":"Yoga-Anatomisi-Asana-Asana.pdf"};